import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Канон преподобному Серафиму, Вирицькому чудотворцю","e":"Canon to St Seraphim of Vyritsa, the Wonderworker","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Ка́ко возмо́жем досто́йно воспі́ти твоє́ богоуго́дноє житіє́, Серафи́ме преподо́бне? От ю́ности бо Христу́ любо́вію уязви́вся, світи́льник пресві́тлий мно́гим яви́лся єси́. Ті́мже мо́лим тя: да́руй і нам просвіще́ніє досто́йно тя сла́вити.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","А́нгелом собесі́дник яви́лся єси́ ізря́дний, свя́те, пре́жде бо житія́ і́ночеськаго во́лю Бо́жию о себі́ ісправля́я, в ми́рі благоче́стно пожи́л єси́ і ду́шу Го́споду в сосу́д ізбра́нний угото́вал єси́.","К Бо́гу ум твой вперя́я, о́тче преподо́бне, стра́сті многоразли́чния смире́нієм і житіє́м многотру́дним умертви́л єси́ і в ра́дості всім тре́бующим твоєя́ по́мощі послужи́л єси́.","Богородичен: О Пречи́стая Ді́во Богоро́дице, не пре́зри нас грі́шних, тре́бующих Твоєя́ по́мощі і заступле́нія, і бу́ди нам Хода́тайця, да покая́нієм обря́щем отпуще́ніє гріхо́в і живо́т ві́чний."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня, я́ко крин, Го́споди, язи́чеськая неплодя́щая це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Ві́рним ча́дом преподо́бнаго ста́рця Варна́ви Гефсима́нськаго яви́лся єси́, свя́те, усе́рдно послуша́ніє єму́ во всем явля́я. Ті́мже і сподо́бился єси́ от него́ би́ти наслі́дник благода́ті і даро́в духо́вних.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","О́тче преподо́бне, ти попече́ніє о убо́гих при́сно імі́я, не возгнуша́лся єси́ послужи́ти о́ним твої́ма рука́ма, показу́я, я́ко всяк челові́к се́рдцю твоєму́ возлю́блен єсть.","Словеса́ а́вви твоєго́ Варна́ви до́брі ісполня́я, на стра́сті вельми́ подвиза́лся єси́. Сего́ ра́ди, мно́гими доброді́тельми от Бо́га укра́шен, дом Трисо́лнечнаго Сві́та яви́лся єси́, преподо́бне.","Богородичен: Преблагослове́нная, Всенепоро́чная Богоро́дице Марі́є, ро́ждшая нам Сло́во Бо́жиє, от гріха́ ізбра́нния Своя́ ізба́вившеє, заступи́ і спаси́ ду́ші на́ша."]},{"h":"Сідален, глас 3","ps":["Возра́дуйся, гра́де свята́го Петра́, і ма́лая ві́сі Ви́рице, возвели́чися, се бо світи́льник ві́ри но́вий Серафи́м, пропові́дник любве́ і покая́нія явля́ється і, да́ри Боже́ственния ще́дро істоча́я, мо́литься о душа́х на́ших.","Богородичен: Я́ко невозді́ланная, Ді́во, Лоза́, красні́йшій Грозд прозябла́ єси́, істоча́ющ нам вино́ спасе́нія, всіх веселя́щеє ду́ші і тілеса́. Ті́мже, я́ко вину́ Тя до́брих блажа́ще при́сно со А́нгели, вопіє́м Ті: ра́дуйся, Благода́тная."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні А́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","О́чі се́рдця ко Творцю́ вся́чеських впери́в і на Бо́га Єди́наго упова́ніє возложи́в, преподо́бне Серафи́ме, і́ночеський о́браз восприя́л єси́ і во дні гоне́ній ко́зні вра́жия му́жественні претерпі́л єси́.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Єва́нгельських за́повідей і́стинний послі́дователь яви́лся єси́, преподо́бне, ті́мже лі́ствицею доброді́телей к соверше́нству многотру́дні восходи́л єси́, вся́коє послуша́ніє до́брі ісполня́я і моли́тву в се́рдці непреста́нно соверша́я.","Мона́шеськоє житіє́ в ми́рі взиску́я і жите́йських трудо́в не отвраща́яся, от ю́ности до́брий наста́вник всім яви́лся єси́, о́тче Серафи́ме, сего́ ра́ди са́на ієре́йськаго от священному́ченика Веніями́на Петрогра́дськаго удосто́їлся єси́.","Богородичен: Тебі́, Ді́во, єди́ну всі ві́рнії стяжа́хом Засту́пницю тве́рду, Ти бо Бо́га родила́ єси́ нам, сего́ ра́ди хвала́ми, Чи́стая, Тя ублажа́єм по глаго́лу Твоєму́."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же, Тобо́ю бо, Влади́ко, к Світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія, приведе́ніє і́мами.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Я́ко світи́льник не мо́жеть укри́тися, верху́ гори́ стоя́, та́ко труди́ і по́двизі твої́, преподо́бне Серафи́ме, я́же в ке́лії вта́йні соверша́л єси́, яви́ша тя ми́ру. Сего́ ра́ди ла́врськая бра́тія і мирсті́ї лю́діє притека́ху к тебі́, наставле́нія взиску́я.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Посреді́ бу́ри тя́жких гоне́ній і лю́тих іспита́ній тверд і непоколеби́м преби́л єси́, преподо́бне Серафи́ме, те́плую моли́тву непреста́нно ко Го́споду возсила́я і науча́я всіх твори́ти святу́ю во́лю Єго́.","О́браз а́нгельський, вели́кую схи́му, приє́м, о́тче, і́менем преподо́бнаго Серафи́ма, уго́дника Саро́вськаго, нарече́н бил єси́, єго́же от ю́ности всім се́рдцем возлюби́в, по́двигом о́наго подража́ти потща́лся єси́.","Богородичен: Ди́вно возсія́ сла́ва Твоя́, Богоро́дице Ді́во, се бо Христа́ Бо́га неізрече́нно імі́ла єси́ во чре́ві, я́коже ні́когда Іса́їя провозгласи́, і ви́ше єстества́ родила́ єси́ Спа́са душ на́ших."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Озаря́єм сві́том Христо́вим сви́ше, богому́дре, і по преселе́нії твоє́м к Бо́гу неоску́дно ісціле́нія істоча́єши всім с ві́рою к тебі́ притека́ющим.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Любо́вію боже́ственною распала́єм, дух ми́рен стяжа́л єси́, о́тче преподо́бне, ду́хи же нечи́стия ізгоня́я, мно́гия лю́ди ко Христу́ приве́л єси́.","Гла́сом ти́хим і кро́тким притека́ющия к тебі́ любві́ і смире́нію наставля́л єси́, о́тче Серафи́ме, та́же і моли́тві непреста́нній, попаля́ющей вся́кий гріх, науча́л єси́.","Богородичен: Ужасо́шася А́нгелов во́їнства і челові́ков собо́ри, Всенепоро́чная, ди́внаго і па́че ума́ Рождества́ Твоєго́: ка́ко і Ді́ва пребила́ єси́ і Ма́ти Бо́жия би́ти сподо́билася єси́. Сего́ ра́ди досто́йно Тя всі сла́вим."]},{"h":"Кондак, глас 5","ps":["Дре́внім отце́м подража́я, по́двигом до́брим подвиза́лся єси́ і, благода́ть Ду́ха Свята́го оби́льно стяжа́в, Саро́вському уго́днику уподо́бился єси́ і мно́гим путь спасе́нія яви́л єси́. Сего́ ра́ди зове́м ті: ра́дуйся, преподо́бне Серафи́ме, Алекса́ндро-Не́вския ла́ври ди́вний подви́жниче і Ви́рицькия ві́си сла́вная похвало́."]},{"h":"Ікос","ps":["А́нгелов Творе́ць і Госпо́дь Сил предизбра́ тя от ю́ности, преподо́бне, би́ти Єму́ служи́телем ві́рним і наста́вником на путь спасе́нія притека́ющим к тебі́. Ми же, див'я́щеся таково́му о тебі́ промишле́нію, с любо́вію вопіє́м: ра́дуйся, я́ко ізмла́да Бо́гу послужи́ти возжелі́л єси́; ра́дуйся, я́ко в ми́рі пребива́я, доброді́тельним житіє́м Бо́гу угожда́л єси́; ра́дуйся, я́ко уті́шитель стра́ждущих бил єси́; ра́дуйся, я́ко пла́менную любо́в ко Христу́ стяжа́л єси́; ра́дуйся, преподо́бнаго Варна́ви Гефсима́нськаго учениче́ приле́жний; ра́дуйся, ди́внаго Серафи́ма Саро́вськаго подража́телю усе́рдний; ра́дуйся, Алекса́ндро-Не́вския ла́ври чу́дноє прозябе́ніє; ра́дуйся, ві́си Ви́рицькия Бо́жиє благослове́ніє; ра́дуйся, ско́рий помо́щниче в ско́рбіх і болі́зніх; ра́дуйся, світи́льниче ві́ри правосла́вния і благоче́стія; ра́дуйся, преподо́бне Серафи́ме, ми́лостивий наш предста́телю пред Го́сподем."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ богочести́вим отроко́м ро́су духо́вную, Сий благослове́н і препросла́влен.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Серафи́му і Варна́ві преподо́бним подража́я, святи́ми їх моли́твами укріпля́єм бил єси́, свя́те, ті́мже от Бо́га сподо́бился єси́ проро́чеськаго да́ра: гряду́щая наро́ду на́шему і Це́ркві Українській предвозвіща́ти.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Єле́ню подо́б'яся, устреми́лся єси́ душе́ю твоє́ю ко го́рнім оби́телем, преподо́бне, Про́мислом же Бо́жиїм соблюда́єм, по́двигом до́брим непреста́нно подвиза́лся єси́, взива́я: благослове́н єси́, Бо́же оте́ць на́ших.","Ру́ці твої́ ко Го́споду со умиле́нієм воздіва́я і уго́днику Бо́жию Саро́вському подража́я, о́тче Серафи́ме, моле́ніє на ка́мені соверша́л єси́, поя́: благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: А́нгельськія Си́ли воспіва́ють Тя немо́лчно, Богороди́тельнице, і ми грі́шнії взива́ти дерза́єм: житіє́ на́ше, Пречи́стая, к Твоєму́ всети́хому приста́нищу напра́ви, зову́щих: благослове́н єси́, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Фараони́ти ми́сленния му́жеськи побіди́в, чистоту́ серде́чную стяжа́л єси́, о́тче преподо́бне, сего́ ра́ди душе́внима очи́ма Бо́га узрі́в, с любо́вію воспіва́л єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Іму́ще тя, о́тче, моли́твенника те́пла і помо́щника ізря́дна, от стріл вра́жиїх спаса́ємся і Бо́гу вопіє́м: благослові́те, вся діла́ Госпо́дня, Го́спода.","Мно́гая чудеса́, преподо́бне, си́лою Бо́жиєю, в тебі́ бога́тно ді́йствующею, сотвори́л єси́: сліпі́ї бо прозрева́ху, німі́ї глаго́лаху, одержи́мії же от духо́в зло́би свобожда́хуся. Сего́ ра́ди Бо́гу, ди́вному во святи́х Свої́х, поє́м: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Єстество́ челові́чеськоє із Тебе́ восприя́л єсть, Влади́чице, всіх Цар і Госпо́дь. Сего́ ра́ди Тя, я́ко Богоро́дицю і Ма́тер Сві́та, в пі́сніх прославля́єм."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная. Тім Всепі́тую Богоро́дицю велича́єм.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Чи́сті зрі́ти сподо́бился єси́ Цари́цю Небе́сную, преподо́бне, ско́роє отше́ствіє твоє́ от ми́ра сего́ ті возвести́вшую. Ті́мже ду́хом возра́довався, Бо́га просла́вил єси́.","Приспів: Преподо́бне о́тче Серафи́ме, моли́ Бо́га о нас.","Утверди́ сердця́ на́ша на путі́ за́повідей Госпо́дніх, о́тче преподо́бне, да обря́щем ми́лость на Стра́шнім Суді́ Єго́ і просла́вим Отця́ на́шего, І́же єсть на Небесі́х.","Душе́ю твоє́ю, я́ко о́гненний Серафи́м, пламені́я, по́прище жи́зні твоєя́ сверши́л єси́, о́тче преподо́бне. Научи́ і нас і́стинній любві́ ко Го́споду і помози́ і́м'я сладча́йшеє Ісу́са непреста́нно призива́ти.","Недосто́йними усти́ піснь ни́ні тебі́ принесо́хом, преподо́бне, сподо́би нас твоєго́ оте́чеськаго благослове́нія, да просла́вим Бо́га на́шего, ди́внаго во святи́х Свої́х.","Богородичен: Єго́же па́че єстества́ родила́ єси́, Ма́ти Пренепоро́чная, моли́ о всіх нас, правосла́вно воспіва́ющих Тя, я́ко Ма́тер Бо́жию і Присноді́ву."]},{"h":"Світилен","ps":["Благода́ть Свята́го Ду́ха, оби́льно все́льшаяся в тя, я́ко світи́льника многосві́тлаго, показа́ тя ві́рним, преподо́бне. Освіти́ омраче́нная сердця́ на́ша, да во сві́ті невече́рнім у́зрим Христа́, Бо́га на́шего.","Богородичен: Честні́йши єси́ всея́ тва́рі, Богоро́дице Ді́во, Христа́ ро́ждшая: Того́ у́бо моли́ сохрани́тися ста́ду Твоєму́ невреди́му от вся́каго наві́та сопроти́внаго."]}],"notes":[]},{"u":"Канон мученику Аврамію Болгарському","e":"Canon to the Martyr Abraham of Bulgaria","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́знима Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Неісче́тне в ми́лості, Христе́ Спа́се ми́ра, вразуми́ нас, недосто́йних пра́зднственно соверши́ти па́м'ять страда́льця Твоєго́. Ти же, страстоте́рпче, пода́ждь нам ра́зум чист вся жите́йськая презрі́ти і єди́наго на потре́бу спасе́нія іска́ти.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Преві́чний Бог дарова́ тебі́ си́лу вра́жія возноше́нія сокруши́ти і вся му́ки претерпі́ти, ти же нам, грі́шним, пода́ждь ра́зум похва́льная тебі́ принести́ і моли́ся за всіх, тя восхваля́ющих.","Богому́дре страстоте́рпче Христо́в Авраа́міє, не возгнуша́йся нас, гріха́ми оскверне́нних, і не отри́ни сего́ тебі́ от нас ма́лаго хвале́нія, но прийми́ є і о всіх, воспіва́ющих тя, Го́споду моли́ся, да всі па́м'ять твою́, ра́дующеся, пра́зднуєм.","Богородичен: Яви́ милосе́рдіє Твоє́, Госпоже́ Пречи́стая, на ни недосто́йния, я́ко к Тебі́ прибіга́єм с пла́чем серде́чним і вопіє́м: поми́луй нас, Єди́на всіх грі́шних спасе́ніє."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Наста́ честна́я па́м'ять твоя́, страстоте́рпче Авраа́міє, в ней же, лику́юще, воспіва́єм тя і лобиза́єм честни́я мо́щі твоя́, вся́ких дарова́ній духо́вних нас сподобля́ющия.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","От честни́х моще́й твої́х мно́гоє ісціле́ніє істоча́єши, му́чениче, і град, в не́мже храни́ться нетлі́нноє ті́ло твоє́, от вся́ких бід покрива́єши, сего́ ра́ди любо́вію па́м'ять твою́, страстоте́рпче, пра́зднуєм.","Несу́щий мо́щі твоя́ от Бо́лгарськия страни́ во град Влади́мир не зна́яху тяготи́ ні но́щію, ні днем. Ми же ни́ні, точи́ло о́крест ра́ки твоє́й стоя́ще, мо́лим тя: сохраня́й чту́щия па́м'ять твою́ от вся́ких бід.","Богородичен: Су́ще во грісі́х мно́зіх, к Тебі́ вопіє́м, Всепречи́стая: очи́сти ни Твої́м милосе́рдієм, да не поги́бнем до конця́, Ти бо всіх скверн Очисти́теля родила́ єси́."]},{"h":"Інший кондак, глас 3","ps":["Укріпи́вся, сла́вне, любо́вію Госпо́днею і Того́ честни́й Крест на ра́мо взем, і́го Госпо́днє, посрами́л єси́ дия́воля кова́рствія і пострада́л єси́ да́же до сме́рти, і сего́ ра́ди, досточу́дне, яви́ся страда́лець вели́к, Авраа́міє, і ору́жником храбротаї́нник і уча́стник Бо́жия благода́ті."]},{"h":"Сідален, глас 4","ps":["Днесь сві́тло пра́зднується па́м'ять твоя́, му́чениче Авраа́міє: возбужда́єши бо всіх к весе́лію чудеси́ твої́ми і непреста́нними о нас к Бо́гу моли́твами."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце Пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Христо́во благоуха́ніє яви́лся єси́, му́чениче, в спаса́ємих тобо́ю от неду́гов душе́вних же і тіле́сних, ті́мже всі правові́рнії сла́в'ять Го́спода, Єго́же ра́ди от злові́рних болга́р пострада́л єси́.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Мо́щі твоя́, му́чениче, утвержда́ють обита́телей страни́ сея́ во ві́рі і благоче́стії; ті́мже і ми с любо́вію вопіє́м ті: ра́дуйся, страстоте́рпче і чудотво́рче Авраа́міє.","Покрови́теля жи́зні на́шей і моли́твенника к Бо́гу почита́єм тя, страстоте́рпче Авраа́міє: на стезю́ нас покая́нія напра́ви, му́чеников соприча́стниче, А́нгелов сограждани́не пресла́вне.","Богородичен: Ка́ко присту́пим к Тебі́, Херуви́м і Серафи́м честні́йшей, і ка́ко воззри́м на Тя, обремене́ннії гріхи́ мно́гими? Но, о Пречи́стая Влади́чице, Сама́ очи́сти ни і ві́чния му́ки ізба́ви."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","По пренесе́нії святи́х моще́й твої́х во град Влади́мир, му́чениче Авраа́міє, вели́кий князь Гео́ргій с подру́жієм свої́м і ча́ди і всі обита́телі гра́да па́м'ять твою́ усе́рдно всегда́ творя́ху, зна́юще тя на Небесі́х Христу́ предстоя́ща і непреста́нно покрива́юща почита́ющих тя, ї́хже і ни́ні сохраня́й от всіх бід.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Пла́мень угаси́ на́ших плотськи́х обурева́ній і нечи́стих на́ших помишле́ній, да пла́мене геє́нськаго огня́ твої́ми моли́твами, Авраа́міє, ізба́вимся.","Ду́шу і помишле́ніє к тебі́ простира́єм, страстоте́рпче Авраа́міє: согрі́й на́ше се́рдце любо́вію, я́же к Бо́гу, да зако́ну Єго́ усе́рдно послі́дующе, пре́йдем по́прище на́шего житія́ непреткнове́нно.","Богородичен: Бо́га родила́ єси́ Ти, Пречи́стая, восхоті́вшаго спасти́ грі́шники, к Нему́же і́маши всегда́ мно́гоє дерзнове́ніє, я́ко Ма́ти: моли́ся о нас Єму́, любо́вію воспіва́ющих Тя, Влади́чице."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися ра́ди ми́лости от ребр Твої́х істе́кшею Кро́вію.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Ви́дя тя іско́нний враг, мно́гія доброді́телі на землі́ творя́ща, злові́рних болга́р подви́же на тя, да приобщи́шися скве́рній ві́рі їх, ти же кро́вію запечатлі́л єси́ пра́вую ві́ру твою́ і си́це Небе́сноє Ца́рствіє восприя́л єси́.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Пречестно́є ті́ло твоє́, страстоте́рпче Авраа́міє, обогаща́єть всіх не земни́м і тлі́нним бога́тством, но Небе́сним, єго́же кро́вію дости́гл єси́, ті́мже і нас получи́ти то сподо́би, любо́вію воспіва́ющих тя.","Оми́вся кро́вію, я́ко водо́ю, і всіх мучи́телей ужаси́в крі́пким твої́м за Христа́ страда́нієм, ни́ні на Небесі́ лику́єши і та́мо за всіх ві́рних неуси́пно мо́лишися, да тве́рдо содержа́ть Правосла́вную ві́ру.","Богородичен: Соблюди́ христия́нськоє жи́тельство, Богоро́дице, грі́шних к покая́нію обрати́, чи́сти вся поста́ви пред Си́ном Твої́м, Пренепоро́чная Ді́во, і сподо́би нас моли́твами Твої́ми Небе́снаго Ца́рствія."]},{"h":"Кондак, глас 8","ps":["Я́ко многоці́нноє сокро́вище, принесено́ бисть от Бо́лгарськия страни́ во град Влади́мир пречестно́є ті́ло твоє́, му́чениче Авраа́міє, і́мже подає́ши всім чту́щим пресла́вную па́м'ять твою́ оби́ліє ісціле́ній, предстоя́ на Небесі́ Христу́ Бо́гу і моля́ Єго́ о спасе́нії душ на́ших."]},{"h":"Ікос","ps":["Я́ко пресві́тлая звізда́, в Бо́лгарстей землі́ возсія́л єси́ благи́ми твої́ми дія́нії і апо́стольською про́повідію, страстоте́рпче Авраа́міє, і та́мо же му́чен бил єси́ за Христа́. Ни́ні же чудеси́, я́ко сві́тлими луча́ми, сія́вши, боля́щим ісціле́ніє подає́ши, здра́вствующим же ра́дованіє і весе́ліє. Ті́мже днесь соше́дшеся, ві́рно зове́м ті: ра́дуйся, ізбра́нниче Госпо́день, всея́ Українськия землі́ засту́пниче і всім Христия́ном помо́щниче."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ Авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Вся на́ша земля́ возра́довася, зря́щи тя, от всіх ві́рних срета́єма і благода́рними гла́си, а́ки мусикі́йськими труба́ми, восхваля́єма, і днесь ра́дується, с на́ми лику́ющи і па́м'ять твою́ прославля́ющи.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Крі́пость і ісціле́ніє прийма́ху от тебе́, му́чениче Авраа́міє, немощству́ющії пло́тію, ско́рбнії же ду́хом і удруче́ннії печа́льми жите́йськими обріта́ху душе́вноє утіше́ніє в умиле́нієм призива́нії свята́го і́мене твоєго́, прославля́юще ди́внаго во святи́х Свої́х Христа́ Бо́га на́шего.","Весели́ся, Богоспаса́ємий гра́де Влади́мире, і наслажда́йтеся, всі ві́рнії, Христо́ва благоуха́нія от святи́х моще́й страстоте́рпця Авраа́мія, я́же не то́кмо тіле́сния болі́зні ісціліва́ють, но і душе́вния стра́сті вся врачу́ють.","Богородичен: Ум наш пліни́ в послуша́ніє ві́ри, дух і ду́шу всесоверше́нни соблюди́ і ті́ло в прише́ствіє Го́спода на́шего Ісу́са Христа́ непоро́чно сохрани́ моли́твами Твої́ми, Богороди́тельнице."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Си́лою Бо́жиєю укріпля́єм, отрази́л єси́ сові́ти беззако́нних, і́же ру́ці твоя́ і но́зі неща́дно отсека́ху. Ті́мже і главу́ прекло́нь под меч, вопія́л єси́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Устраши́ти тя не возмого́ша неві́рнії, ніже́ поколеба́ти тве́рдаго ума́ твоєго́ отрещи́ся Христа́, я́ко адама́нт, преби́л єси́ крі́постію ві́ри твоєя́, поя́ непреста́нно: благослові́те, вся діла́ Госпо́дня, Го́спода.","Прийді́те, всі правові́рнії, воспросла́вим па́м'ять страстоте́рпця Авраа́мія і облобиза́єм с ві́рою честни́я мо́щі єго́, істоча́ющия цільби́ неду́гов душе́вних вку́пі і тіле́сних всім воспіва́ющим: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Побіди́, Пречи́стая, врага́ ви́димия і неви́димия, низложи́ти нас тща́щихся, і страсте́й нас вся́ких ізба́ви, да поє́м торже́ственне: благослові́те, вся діла́ Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся, Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Ве́лія сла́ва ти єси́ на́ша і похвала́, страстоте́рпче Христо́в Авраа́міє: вели́ку бо ві́ру во Христа́ Ісу́са імі́я, второ́є крести́лся єси́ в Него́ кро́вію твоє́ю і дости́гл єси́ Небе́снаго житія́, єго́же улучи́ти сподо́би і нас моли́твами твої́ми.","Приспів: Святи́й му́чениче Авраа́міє, моли́ Бо́га о нас.","Псалми́ і пі́сньми восхваля́єм тя, му́чениче, озаря́єши бо нас всегда́ чудеси́ твої́ми, ї́хже кто дово́лен ісчести́, ра́зві Да́вий тебі́ сія́? Єму́же моли́ся, да спасе́ть вся лю́ди, с ві́рою і любо́вію соверша́ющия святу́ю па́м'ять твою́.","Воі́стину нікто́же, притека́яй к тебі́, му́чениче Христо́в Авраа́міє, тощ благода́ті твоєя́ отхо́дить, єя́же і нас іспо́лни, мо́лимся.","Богородичен: Воі́стину і́стиннаго Бо́га пло́тію, Богоро́дице, родила́ єси́, Єго́же ми́лостива нам в день Суда́ соді́лай, да безконе́чно с Ним Тя велича́єм."]},{"h":"Світилен","ps":["Сві́та немерца́ющаго дости́гл єси́, му́чениче Авраа́міє, за крі́пкоє твоє́ страда́ніє Христо́ви ра́ди ві́ри от злові́рних, і ни́ні, пребива́я во Ца́рствії Небе́снім, ра́дуєшися і весели́шися со всі́ми му́ченичеськими ли́ки. Моли́ о нас, чту́щих святу́ю па́м'ять твою́.","Богородичен: Світ нам возсія́ пресві́тлий от Твоєя́ ді́вственния утро́би, Христо́с Бог наш, Пречи́стая Влади́чице, ті́мже Тя мо́лим, Цари́цю і Богоро́дицю: моли́ Си́на Твоєго́ і Бо́га на́шего, да, прости́в нам согріше́нія на́ша, спасе́ть нас, я́ко Благ і Человіколю́бець."]}],"notes":[]},{"u":"Канон преподобному Зосимі, ігумену Соловецькому","e":"Canon to St Zosimas, Abbot of Solovki","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Пої́м Го́сподеві, прове́дшему лю́ди Своя́ сквозі́ Чермно́є мо́ре, я́ко Єди́н сла́вно просла́вися.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Боже́ственною, о́тче, любо́вію приліпи́лся єси́ от ю́ности Христу́, плотські́я стра́сті ув'яди́л єси́ воздержа́нієм, Зоси́мо прему́дре, Бо́гом помога́єм. І ни́ні нам сві́та ми́сленнаго іспо́лнитися помоли́ся Го́сподеві, пою́щим: сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Претруди́л єси́ ті́ло, пребога́те, і стра́сті плотські́я, о́тче, порабо́тил єси́, Зоси́мо, я́сно прия́л єси́ сві́тлость благода́ті і, се́ю просві́щся, боже́ственне взива́л єси́: Го́сподеві пої́м, сла́вно бо просла́вися.","Крі́постію Ду́ха возмо́г, держа́ву низложи́л єси́ і си́лу вра́жию і, похвалу́ побі́дную і по́чести приє́м, преподо́бне, чуде́сними сія́нії просвіти́лся єси́, Го́сподеві поя́: сла́вно бо просла́вися.","Богородичен: Зако́н кромі́ єсте́ственних родила́ єси́ законода́вця Бо́га, Челові́ка би́вша. Того́ я́ко Бла́га моли́, Всенепоро́чная, на́ша беззако́нія презрі́ти, вопію́щих всегда́: Го́сподеві пої́м, сла́вно бо просла́вися."]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє притека́ющих к Тебі́, Го́споди, Ти єси́ Світ омраче́нних, і поє́ть Тя дух мой.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Плоть твою́ умертви́л єси́ воздержа́нієм, преподо́бне, ду́шу же Боже́ственними дарова́нії просвіти́л єси́.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Все у́бо жела́ніє ко Влади́ці Твоєму́ обрати́л єси́, я́рость же на бі́си, богоно́се, вооружи́л єси́.","Імі́я споспішеству́ющую ті Бо́жию си́лу, прему́дре, я́ко чу́ден, чудеса́ істоча́єши і отго́ниши неду́ги.","Богородичен: В ложесна́ Твоя́ с потща́нієм, Всенепоро́чная, всели́ся Зижди́тель на благодія́ніє ві́рно воспіва́ющим Тя."]},{"h":"Сідален, глас 4","ps":["Страстно́є порабо́тил єси́ плотсько́є мудрова́ніє, ду́ху го́ршеє покори́в, о́тче пресла́вне, сокруши́л єси́ ви́ї бісо́м і посто́м возсія́л єси́ в ми́рі, я́ко лучи́ со́лнечних сія́ній, твоя́ доброді́телі показу́я. Сего́ ра́ди тя воспіва́єм."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Прему́дрости пе́рвіє ти рачи́тель яви́лся єси́, прему́дре, житіє́ бо непоро́чно пожи́л єси́, очище́н ізря́дно душе́ю і ми́слію, согла́сно взива́я: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Очи́стив ум твой от страстни́я молви́, сла́вне, і чу́вства, му́дре, упра́вив, к нему́тній тишині́, о́тче, устреми́лся єси́ в морськи́й о́стров і усе́рдно воспіва́л єси́: сла́ва си́лі Твоє́й, Го́споди.","Земни́я печа́лі воздержа́тельно оттря́с, небе́сния наде́жди стяжа́ Твой уго́дник, Влади́ко, преподо́бний Зоси́ма, со усе́рдієм поя́: сла́ва си́лі Твоє́й, Го́споди.","Богородичен: Яви́ся в мир от Ді́ви я́ко Челові́к, дарова́ побі́ду преподо́бним Свої́м, Кресто́м бо Єго́ бі́си прогна́ша, ві́рою зову́ще: сла́ва си́лі Твоє́й, Го́споди."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще вопіє́м Ті: Го́споди, спаси́ ни, Ти бо єси́ Бог наш, ра́зві Тебе́, іно́го не ві́ми.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Умо́м очище́нним, пресла́вне, зри́ши добро́ту неізрече́нную Христа́, вся́чеських Бо́га на́шего.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Умертви́ на́ша мудрова́нія, Человіколю́бче, плотська́я, і взигра́нія богоприя́тними преподо́бнаго Твоєго́ моли́твами.","Сви́ше нас назира́єши, преблаже́нне, і управля́єши живо́т наш, творя́щих любо́вію, преподо́бне, па́м'ять твою́.","Богородичен: Ісціли́ неду́гующаго ума́ моєго́ омраче́ніє, врача́ ро́ждшая, Христа́, Всенепоро́чная Влади́чице."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Я́ко сна о́браз тлі́нний, всего́ ми́ра сла́ву зря, єди́наго жива́го Бо́га сла́ви возлюби́л єси́ прича́стник би́ти: ю́же, преподо́бне, пра́ведно сподо́бился єси́ зрі́ти.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Лука́вий умертви́ся змій свяще́нними твої́ми моли́твами, богоблаже́нне, і того́ ріша́ються зло́би, і́же зна́меніє от тебе́ іспроси́вше, і уго́дник сві́тел Бо́жий позна́н бил єси́ ві́рен.","Богому́дрим по́мислом украси́вся, я́же на землі́ преоби́діл єси́ вся, і небе́сноє, преблаже́нне о́тче, наслі́діє, прему́дре, разсуди́л єси́, Зоси́мо, і ни́ні я́ві на небесі́х живе́ши, ра́дуяся.","Богородичен: Госпо́дь с Тобо́ю, Пречи́стая, я́коже ізво́лил єсть і всіх нас от о́бласти льсти́ваго хода́тайством Твої́м ізба́вил єсть. Ті́мже Тя ни́ні по до́лгу ро́дове родо́в ублажа́ють."]},{"h":"Кондак, глас 8","ps":["Христо́вою любо́вію уязви́ся, преподо́бне, і Того́ Крест сла́вний, на ра́мо взем, поне́сл єси́, боже́ственне вооружи́вся, і непреста́нния моли́тви, я́ко копіє́ в руці́, іми́й, крі́пко ссікл єси́ бісо́вськая ополче́нія. Тім зове́м ті: ра́дуйся, преподо́бне о́тче Зоси́мо, мона́хов удобре́ніє."]},{"h":"Ікос","ps":["Усли́шав Христо́в глас, оста́вил єси́ плотська́я мудрова́нія, бога́тство же і сла́ву, я́ко прах, вміни́в, на стра́сті, я́ко безпло́тен, подвиза́лся єси́, і безпло́тних ликостоя́нію чистото́ю уподо́бился єси́, і ра́зума дарова́ніє прия́л єси́, є́же пода́ждь в пі́сніх пою́щим ті си́це: ра́дуйся, Зоси́мо преподо́бне і богоно́се, небе́сний челові́че і земни́й а́нгеле; ра́дуйся, я́ко кромі́ ми́ра су́єтнаго пусти́ню соді́лав в морсько́м о́строві, в нем оби́тель соста́вил єси́. Ра́дуйся, я́ко в ней мно́жество мона́хов собра́ся, і от них сли́шиши си́це глаго́лемоє: ра́дуйся, мона́шествующим спасе́нія хода́тай; ра́дуйся, унива́ющих о́браз утіше́нія; ра́дуйся, мона́хом от наві́т вра́жиїх ізба́вителю; ра́дуйся, скорбе́й губи́телю на́шего єстества́, я́ко отго́ниши по́мисли зло́бния; ра́дуйся, скорб'я́щих душе́ю сла́дкоє утіше́ніє і ра́дости боже́ственния пода́телю; ра́дуйся, наш предста́телю і ізба́вителю; ра́дуйся, преподо́бне о́тче Зоси́мо, мона́хов удобре́ніє."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци во Вавило́ні іногда́, ві́рою тро́йчеською пла́мень пе́щний попра́ша, пою́ще: отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Всім жела́нієм приліпи́лся єси́, воздержа́нієм тве́рдим твоєму́ Влади́ці, Того́ ни́ні пита́єшися сія́нії, зови́й: оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Просвіти́в твоє́ се́рдце, священнонача́льник бисть о́тча соста́ва, наказу́я і уча́ вся, ізводя́ всяк ум к Бо́жиїм во́лям, поя́: оте́ць на́ших Бо́же, благослове́н єси́.","Плод боже́ствен Влади́ці прине́сл єси́ — житіє́, треблаже́нне, і же́ртву прия́тну і непоро́чну, зови́й: оте́ць на́ших Бо́же, благослове́н єси́.","Богородичен: Се Ді́ва Боже́ственноє Отроча́ породи́, Єго́же ни́ні богоно́снії отці́ позна́вше Бо́га і Го́спода, вопія́ху: оте́ць на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Богоглаго́ливії о́троци, в пещі́ со огне́м пла́мень попира́юще, поя́ху: благослові́те, діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","С похвала́ми бива́єть, богоно́се, па́м'ять твоя́: пра́вди бо яви́лся єси́ показа́тель, му́жества, і му́дрості, і цілому́дрія, о́тче преподо́бне Зоси́мо, Соді́телю і Ізба́вителю взива́я: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Невозвра́тно ше́ствовал єси́ веду́щими к небесі́ боже́ственними стезя́ми, о́тче преподо́бне Зоси́мо досточу́дне, от злих, веду́щих до конця́, укріпи́лся єси́, поя́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богоно́снаго всі хвала́ми почти́м, я́ко іспо́лнена я́ві благода́ті і Боже́ственними сія́ньми просвіще́на, ізря́дне Соді́телю і Ізба́вителю вопія́ше: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Вода́ єси́ неісчерпа́ємая, Ді́во, от нея́же всі, пію́ще, благода́ті ісполня́ємся і, душе́ю і ті́лом освяща́ємі, поє́м: благослові́те, вся діла́ Госпо́дня, Го́спода."]},{"h":"Пісня 9","ps":["Ірмос: Устраши́ся всяк слух неізрече́нна Бо́жия снизхожде́нія, я́ко Ви́шній во́лею сни́де да́же і до пло́ті, от діви́чеськаго чре́ва бив Челові́к. Ті́мже Пречи́стую Богоро́дицю, ві́рнії, велича́єм.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Струя́ми твої́х слез очи́щся, ни́ні Сві́та наслажда́єшися, о́тче преподо́бне, трисія́ннаго. Тому́ предстоя́ я́ві, світоза́рними просвіща́єм луча́ми, сви́ше назира́єши нас, твою́ па́м'ять творя́щих, всеблаже́нне.","Приспів: Преподо́бне о́тче Зоси́мо, моли́ Бо́га о нас.","Я́ко вели́коє со́лнце, нам вели́чієм по́двиг твої́х осія́л єси́, богому́дре, вся земни́я конці́, к Сві́ту, от Сві́та возсія́вшему, у́мер, преше́л єси́. Тім вопіє́м ті: просвіти́ на́ша помишле́нія, о́тче преподо́бне.","Процві́л єси́ в по́стничеських по́двизіх, прехва́льне о́тче наш, я́ко ши́пок благоуха́нен і, я́ко кедр, облагоуха́л єси́ со́вісти ві́рних сердця́ доброді́тельми і чудеси́; тім отжени́ стра́сті смердя́щия, преподо́бне.","Богородичен: Просвіти́, Пречи́стая Ді́во, сі́тующеє се́рдце моє́ при́сно преступле́нії і жите́йськими мно́гими молва́ми і не оста́ви м'я враго́м би́ти в ра́дость, я́ко да сла́влю Тя і я́ко да Тя любо́вію пою́, Препі́тая."]},{"h":"Світилен","ps":["Насажде́ну ті в дому́ Бо́жії, воі́стинну, я́ко фі́нікс, псало́мськи процвіта́єть твоя́ оби́тель, умножа́я тебі́ ча́да, і́же твою́, о́тче Зоси́мо, па́м'ять пра́зднують сві́тло."]}],"notes":[]},{"u":"Канон апостолу і євангелісту Марку","e":"Canon to the Apostle and Evangelist Mark","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Твоя́ побіди́тельная десни́ця боголі́пно в крі́пості просла́вися: та бо, Безсме́ртне, я́ко всемогу́щая проти́вния сотре́, ізра́їльтяном путь глубини́ новосоді́лавшая.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Ма́рка богови́дця восхваля́я, призива́ю благода́ть Ду́ха: я́ко да вдохну́в мі сві́тло, отжене́ть неві́дініє і боже́ственноє бога́тство прему́дрости да́руєть.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Твоєго́ богогла́снаго сві́том просвіти́в, Спа́се, благода́тним, в мир посла́л єси́, Сло́ве Бо́жий, благи́х я́ко вино́вний, Твоє́ прише́ствіє нам благовіству́юща.","Петру́ прему́дрому учени́к бив і того́ обогати́вся синовство́м, Ма́рко всесла́вне, таї́нник показа́лся єси́ та́їн Бо́жиїх і снаслі́дник сла́ви єго́ бил єси́.","Богородичен: І́же єги́птяни во глубині́ потопи́в о́блаком Ду́ха, Сей приї́де от Тебе́, Чи́стия, єги́птяном по́сліжде і Ма́рком тіх от пре́лести ізміни́."]},{"h":"Пісня 3","ps":["Ірмос: Єди́не, ві́дий челові́чеськаго существа́ не́мощ і ми́лостивно в не вообра́жся, препоя́ши м'я с висоти́ си́лою, є́же вопи́ти Тебі́, Святи́й, одушевле́нний хра́мі неізрече́нния сла́ви Твоєя́, Человіколю́бче.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Тя, іпоста́сную, Христе́, Прему́дрость пропові́да, луча́ми Твої́ми озаря́єм, всему́ ми́ру я́вльшуюся, Влади́ко, і жизнь даю́щую, і челові́ки просвіща́ющу, уго́дник Твой сла́вний Ма́рко, Человіколю́бче.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Струю́ приє́м, Христе́, прему́дрости приснотеку́щую, я́ко ріка́, шум'я́щи, земни́я напої́ богоразу́мія сві́том конці́, явля́я Твоє́ су́ще і́стинно прорече́ніє, самови́дець Твой Ма́рко, Человіколю́бче.","Петру́ послі́дуя, му́дре, я́ві, Єва́нгеліє я́ко учени́к єго́ вообрази́л єси́, богосло́вія світ приє́м от него́, апо́столе, і Бо́жиє плотсько́є прише́ствіє возвісти́в я́сно.","Богородичен: Єги́пта пе́рвіє, діви́чеськими рука́ми носи́мий, де́монськая тре́бища Ти потря́сл єси́ і сему́ па́ки Ма́рка посла́л єси́ вразуми́ти всім Твоє́ вочелові́ченіє і боже́ственную, Христе́, Твою́ та́йну."]},{"h":"Сідален","ps":["На висоту́ возше́д доброді́телей боже́ственний Ма́рко, возгремі́л єси́ нам спаси́тельних догма́ть вели́кия та́йни, боже́ственний пропові́дник бив. Ті́мже ві́рою тя мо́лим, преблаже́нне, вся́кия ско́рби, согріше́ній і бід нас свободи́."]},{"h":"Пісня 4","ps":["Ірмос: Го́ру Тя, благода́тію Бо́жиєю приосіне́нную, прозорли́вима Авваку́м усмотри́в очи́ма, із Тебе́ ізи́ти Ізра́їлеву провозглаша́ше Свято́му, во спасе́ніє на́ше і обновле́ніє.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Во всю зе́млю віща́ніє твоє́ ізи́де, і в конці́, прему́дре, вселе́нния твої́х я́сно глаго́л си́ла, дави́дськи сві́тло пропові́дающи спасе́ніє на́ше і обновле́ніє.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Яви́ся, Спа́се, я́ко мо́лнія, апо́стол вселе́нній прему́дрий, і́стини ра́дость благовіству́я, богосія́нієм світоли́тія просвіща́єм во спасе́ніє на́ше і обновле́ніє.","Но́зі твої́ проро́чеськи украси́шася, і́бо па́че сло́ва нам благовісти́л єси́ проявле́нно мир, богоприя́тне, пло́тію Я́вльшагося конце́м во спасе́ніє на́ше і обновле́ніє.","Богородичен: На о́блаці Сло́во діви́честім сі́де, єги́петськия сові́ти і богобо́рния ми́слі, обуї́в, разори́, уче́нії боже́ственнаго Ма́рка, я́ко Милосе́рд, во спасе́ніє на́ше і обновле́ніє."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́вий сія́нієм прише́ствія Твоєго́, Христе́, і освіти́вий Кресто́м Твої́м ми́ра конці́, сердца́ просвіти́ сві́том Твоєго́ богоразу́мія, правосла́вно пою́щих Тя.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Іска́пал єси́ сла́дость благоче́стія слове́с твої́х боже́ственних ту́чу, всю́ду луча́ми осіява́єм, я́влься благода́тію я́ві ми́сленнаго Со́лнця, Ма́рко всеблаже́нне богоприя́тне.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Із до́му Госпо́дня істо́чник ізше́л єси́ і напоя́єши олядені́вшая сердца́ струя́ми бога́тно духо́вними, плод вмі́сто непло́дствія приноси́ти уча́, апо́столе.","Ти Петра́ вели́каго син бил єси́ і, сего́ уче́ньми просвіща́єм всегда́, ду́ші просвіти́л єси́ к тебі́ те́плі присту́пльших, блаже́нне, богови́дче апо́столе.","Богородичен: Я́ко Челові́к от Ді́ви ро́ждься, єги́птяном, Христе́, посла́лся єси́, от Отця́ возсія́в пре́жде всея́ тва́рі, і́мже Ма́рка пома́зал єси́, Му́дре, тіх науча́юща богоразу́мія та́їнством."]},{"h":"Пісня 6","ps":["Ірмос: Оби́де нас послі́дняя бе́здна, ність ізбавля́яй, вміни́хомся, я́ко о́вці заколе́нія, спаси́ лю́ди Твоя́, Бо́же наш, Ти бо крі́пость немощству́ющих і ісправле́ніє.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Низложи́л єси́ бров беззако́нних, Го́споди, і досажде́ніє го́рдоє смири́л єси́, апо́стола Твоєго́ показа́в побідоно́сця си́лою Твоє́ю, Ти бо крі́пость немощству́ющих і ісправле́ніє.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Віне́ць наде́жди, сла́вне, і́мже ни́ні вінча́ємся, словеси́ твої́ми пропові́дал єси́, му́дре Ма́рко, Зижди́теля тва́рі, І́же в на́шу сла́ву ісплете́н єстество́м пло́ті.","Петр тя верхо́вний, сла́вне, я́ві та́йно научи́ Єва́нгеліє списа́ти честно́є, показа́в служи́теля тя Боже́ственния благода́ті, ти бо нам богоразу́мія світ просте́рл єси́.","Богородичен: Єги́пта, і́же пе́рвіє во тьмі су́ща, Го́споди, Ді́вою Богома́терію просвіти́л єси́, я́ко Младе́нець проше́д, того́ обличи́л єси́ су́єтство уче́нії богогла́снаго Ма́рка, Человіколю́бче."]},{"h":"Кондак","ps":["С висоти́ приї́м благода́ть Ду́ха, ри́торськая плете́нія разруши́л єси́, апо́столе, і, язи́ки вся улови́в, Ма́рко всесла́вне, твоєму́ Влади́ці приве́л єси́, Боже́ственноє пропові́дав Єва́нгеліє."]},{"h":"Ікос","ps":["Верхо́внаго апо́стола учени́к бив, с ним Христа́, Си́на Бо́жия, пропові́дал єси́, на ка́мені і́стини утверди́в ле́стію коле́блющіяся. На не́мже і мене́ утверди́в, душі́ моєя́ іспра́ви стопи́, я́ко да вра́жиїх сіте́й ізба́влься, непреткнове́нно сла́влю тя: ти бо всіх просвіти́л єси́, Ма́рко му́дре, Боже́ственноє пропові́дав Єва́нгеліє."]},{"h":"Пісня 7","ps":["Ірмос: Тебі́, у́мную, Богоро́дице, пещ, разсмотря́єм, ві́рнії, я́коже бо о́троки спасе́ три Превозноси́мий, мир обнови́, во чре́ві Твоє́м всеці́л, хва́льний отце́в Бог і препросла́влен.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Боже́ственними блиста́нії освіща́єм, возломле́нієм та́йно возпосила́єши зареви́дния лучи́, Ма́рко преблаже́нне: Сло́во бо пропові́дал єси́ воплоща́ємоє, безлі́тноє, хва́льнаго отце́в Бо́га і препросла́вленнаго.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Богоді́льними, Вседі́телю, си́лами богогла́снаго ученика́ вооружи́в, чудоді́йственника сего́ соверши́л єси́: неду́ги бо отгна́ і я́зі ісціли́л єсть, прехва́льнаго Тя пропові́дуя Бо́га і препросла́вленнаго.","Учени́чеськаго ли́ка старі́йшаго учи́теля імі́я, боже́ственнаго Петра́, подо́бен сему́ яви́лся, все бо іспра́вил єси́ церко́вноє ісполне́ніє прехва́льнаго отце́в Бо́га і препросла́вленнаго.","Богородичен: Столп сам во Єги́пті поста́вил єси́, Єва́нгелія твоєго́ писа́ніє Ро́ждшемуся без сі́мене от Богома́тере, рече́нієм послі́дуя Іса́її, пресла́вне, прехва́льнаго возвіща́я Бо́га і препросла́вленнаго."]},{"h":"Пісня 8","ps":["Ірмос: В пещі́ о́троци Ізра́їлеви, я́коже в горни́лі, добро́тою благоче́стія чисті́є зла́та блеща́хуся, глаго́люще: благослові́те, вся діла́ Госпо́дня, Го́спода, по́йте і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Ро́ждшеєся Сло́во от Отця́ пре́жде всіх вік, в єстество́ челові́чеськоє обле́кшася Христа́, пропові́дал єси́, сла́вне, і вопія́л: вся діла́ Госпо́дня, Го́спода по́йте і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Да́вшаго ізбавле́ніє себе́ за на́ше согріше́ніє і страсть па́дших, воздви́гшаго Христа́ просла́вил єси́, сла́вне, вопія́: вся діла́ Госпо́дня, Го́спода по́йте і превозносі́те во вся ві́ки.","Петро́ву Ма́рко повину́яся прему́дрому учи́тельству, прему́дре писа́нії вообрази́л єси́ ві́рним честно́є Єва́нгеліє, вопію́щим: вся діла́ Госпо́дня, Го́спода по́йте і превозносі́те во вся ві́ки.","Богородичен: Ді́ва, Емману́їла нося́щи я́ко Младе́нця, предста́ єги́птяном, і́мже, я́ко сві́тлая звізда́, Ма́рко посила́ється, взива́я: вся діла́ Госпо́дня, Го́спода по́йте і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: О́браз чи́стаго рождества́ Твоєго́ огнепали́мая купина́ показа́ неопа́льная; і ни́ні на нас напа́стей свирі́піющую угаси́ти, мо́лимся, пещ, да Тя, Богоро́дице, непреста́нно велича́єм.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Дости́г істо́чника неізрече́нна, трисо́лнечнаго, богоявле́нне, сія́нія, чисті́йша наслажда́єшися і ясні́йша обоже́нія, є́же па́че ума́, со а́нгели лику́я непреста́нно, преблаже́нне.","Приспів: Святи́й апо́столе і євангели́сте Ма́рко, моли́ Бо́га о нас.","Петро́ва о́бщник бив уче́нія і боже́ственнаго пропові́данія, в небе́сних живе́ши селе́ніїх, с ни́мже, богоглаго́ливе преблаже́нне, і мо́лишися о нас, Ма́рко апо́столе.","Світ, трисія́нно совокупля́єм, єди́нственно же па́ки стра́нно устроя́єм, пропові́дал єси́ благоче́стно, досточу́дне, просвіща́єм заре́ю благода́ті. Ті́мже тя мо́лим: о нас при́сно моли́ся.","Богородичен: Марк, честни́й апо́стол, єги́птяном святи́тель дарова́ся; к ни́мже, я́ко Младе́нець вопло́щся, приї́де, от Ді́ви Чи́стия Богома́тере, Госпо́дь сла́ви, Єго́же досто́йно велича́єм."]},{"h":"Світилен","ps":["Прему́дрости небе́сния научи́вся, апо́столе, плете́нія виті́йськая і чи́сла звіздосло́вцев разори́л єси́ язи́ком твої́м, о Ма́рко пресла́вне! І, учени́к бив Петро́в, ми́ру пропові́дал єси́ Єва́нгельськая словеса́."]}],"notes":[]},{"u":"Канон святителю Стефану, єпископу Пермському","e":"Canon to St Stephen, Bishop of Perm","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Свяще́ннаго ти Писа́нія от младе́нства научи́вся, богоно́се Стефа́не, в да́льняя міста́ прише́л єси́, і неві́дущим Бог тобо́ю позна́ся.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Іді́же пре́лесть почита́єма бя́ше, та́мо же ни́ні тобо́ю Бог неві́дущим, святи́телю Стефа́не, позна́ся. Ті́мже свяще́нную Твою́ па́м'ять достодо́лжно ублажа́єм.","Богодохнове́нним твої́м уче́нієм научи́л єси́ лю́ди ві́ровати во Христа́ і от і́дольськия пре́лести уклоня́тися. Сего́ ра́ди тя всі, я́ко єдиноревни́теля апо́столом, пі́сньми почита́єм.","Богородичен: Ти Єди́наго, Богоневі́сто, во ви́шніх Сідя́щаго, на руку́ носи́ла єси́, плоть би́вша: Ти бо била́ єси́ ізбра́нна от всіх вік, прия́телище досто́йно Вседержи́теля."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний Істо́чниче, лик Себі́ совоку́пльшія, духо́вно утверди́, в боже́ственній Твоє́й сла́ві, вінце́в сла́ви сподо́би.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Не убоя́лся єси́, святи́телю, люде́й тогда́ нече́ствующих, но тіх дерзнове́нно куми́рницю со і́доли огню́ пре́дал єси́ і всіх научи́л єси́ вопи́ти: ність свят, па́че Тебі́, Го́споди.","Тезоімени́тим му́жеством і смире́нія нра́вом на о́вчу кро́тость уби́йць преложи́л єси́, сего́ ра́ди і вінці́ вінча́лся єси́, святи́телю Стефа́не.","Богородичен: Тя, заступле́ніє небла́зненно, Богома́ти, стяжа́вше і упова́ніє на Тя возлага́юще, спаса́ємся і, к Тебі́ прибіга́юще, сохраня́ємся всі."]},{"h":"Сідален","ps":["Ума́ пречу́днаго і бо́дреннаго учи́теля, священноді́йстви Це́рков украси́вша, і му́тним уче́нієм волхва́, я́ко возбісні́вша во́лка, от Христо́вих ове́ць словеси́ свої́ми отгна́вша, і невре́дно духо́вная своя́ ча́да сохра́нша, восхва́лим, ві́рнії, Стефа́на прехва́льнаго, глаго́люще: моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́ во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, Нетлі́нною Дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Я́ко со́лнце, чи́стоє житіє́ твоє́ возсія́, святи́телю, тьму ідолобі́сія от люде́й твої́х отгна́в, всіх научи́л єси́ взива́ти: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Волше́бная буєсло́вія, я́ко прему́др, посрами́л єси́, і сих от Христо́ва ста́да словеси́ твої́ми, я́ко пра́щею, отгна́л єси́, і зва́ти всіх научи́л єси́: сла́ва си́лі Твоє́й, Го́споди.","Я́ко і́стинний святи́тель тих і кро́ток, о́тче, бил єси́ і столп благоче́стія Це́ркве яви́лся єси́, лю́ди твоя́ благоче́стію научи́во вопи́ти Христу́: сла́ва си́лі Твоє́й, Го́споди.","Богородичен: Тя ору́жіє на враги́ предлага́єм, ско́рби вся́кия лю́тих обстоя́ній отріва́єм, і возмуще́нія єреті́чеськаго, Ма́ти Бо́жия, ізбіга́єм."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й: Ти бо, неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га, і родила́ єси́ Безлі́тнаго Си́на, всім, воспіва́ющим Тя, мир подава́ющая.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Воздви́гл єси́ уче́нієм твої́м дре́вле во тьмі неві́дінія лю́ди лежа́щия, ча́да Бо́жия і сві́та показа́л єси́ наслі́дники, отону́дуже тя, святи́телю, всі любому́дренно почита́єм.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Прему́дрость Ду́ха Свята́го благода́тію во устна́х твої́х ізлія́вшися самотвори́тельно і ко Христо́ву позна́нію приведе́ лю́ди, святи́телю.","Сві́ту вели́кому я́ко віне́чник ни́ні, святи́телю, предстої́ши, помина́й ізря́дноє твоє́ достоя́ніє, є́же мно́гими труди́, о́тче, стяжа́л єси́, да всі тя ублажа́єм.","Богородичен: Возсія́ із Тебе́ ми́сленноє Со́лнце і сві́тлия лучи́ Своєго́ Божества́ всім простре́, Богоро́дице Влади́чице, тім Тя всі сла́вим."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, богому́дрії, Богома́тере, прийді́те, рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Ра́лом слове́с твої́х олядені́вшая люде́й сердца́ возді́лал єси́, боже́ственноє сі́м'я в них всі́яв, плод кра́сний Христу́, святи́телю, приве́л єси́.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Бистрина́ми твої́х уче́ній і́дольськая разжже́нія, прему́дре Стефа́не, угаси́в, боже́ственними твої́ми словеси́ ві́рних сердця́ утверди́л єси́.","Во Єдиносу́щную Тро́йцю ві́ровати лю́ди научи́в, прему́дре Стефа́не, от скве́рни і́дольськия к Живо́му Бо́гу приве́л єси́.","Богородичен: Расто́ргни мої́х согріше́ній рукописа́ніє, одержа́щих ми печа́лей і страсте́й разріше́ніє да́руя, і соблюди́ м'я неврежде́нна, Влади́чице."]},{"h":"Кондак","ps":["Самозва́нен не і́щущим тебі́, святи́телю, обрі́лся єси́, лю́ди, от і́дольськия ле́сти свободи́в, ко Христо́ві ві́рі приве́л єси́ і волхва́ пансо́тника посрами́л єси́, ті́мже і пе́рвий єпи́скоп і учи́тель Пе́рми бил єси́. Сего́ ра́ди духо́вная твоя́ ча́да, я́ко тобо́ю ізба́вльшеся от і́дол, благода́рная тебі́ возопіє́м: ра́дуйся, Стефа́не, учи́телю прему́дрий."]},{"h":"Ікос","ps":["Вся́каго мирська́го пристра́стія кромі́, о́тче, бив, от ю́ности приліжа́л єси́ прему́дрості і ді́тельноє худо́жество дости́гл єси́ богосло́вія. І в да́льнія страни́ прише́д, іді́же весьма́ Бог не познава́шеся, но пре́лесть бісо́вськая почита́шеся, та́мо апо́стольськи лю́ди научи́л єси́ ві́ровати во Христа́, і́доли сокруши́в і волхва́ посрами́в, святи́тель тім бил єси́. Ті́мже духо́вная твоя́ ча́да, я́ко тобо́ю ізба́вльшеся от і́дол, благода́рная тебі́ зове́м: ра́дуйся, Стефа́не, учи́телю прему́дрий."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Злочести́вий он чароді́й, і́же на благоче́стіє хулу́ глаго́лавий, тобо́ю, прему́дре, я́ко беззако́нен, от Христо́ва ста́да но́вих люде́й отгони́м бива́єть. Ми же Христу́ зове́м: благослове́н Бог оте́ць на́ших.","Пресла́вно я́ко преше́д от ми́ра к преми́рним, святи́телю, жили́щем і прича́стієм Бо́гу прибли́жився, воспіва́єши: благослове́н Бог оте́ць на́ших.","Богородичен: Ізба́вльшеся Тобо́ю пе́рвия кля́тви, к присносу́щній Жи́зні преше́дше, ра́дуйся, зове́м Ті, пресла́вная Влади́чице, Я́же Бо́га нам ро́ждшая."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Словеси́ твої́ми наставля́єма ча́да твоя́, святи́телю, от тьми і́дольськия к сві́ту богоразу́мія преше́дше, єдиногла́сно Христу́ вопіє́м: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те Єго́ во ві́ки.","Світ трисо́лнечния Тро́йці, всели́вся в боже́ственноє твоє́ се́рдце, лю́ди вся просвіти́ святи́м креще́нієм і научи́ Творцю́ Ізба́вителю вопи́ти: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те Єго́ во ві́ки.","Богородичен: Усти́ і ра́зумом Богоро́дицю Тя му́дрствующе, пісносло́вим Тя, Пренепоро́чная: родила́ бо єси́, Пречи́стая, пло́тію обложе́на Бо́га і Го́спода. Тім Тя, Ді́во, поє́м і превозно́сим во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Твої́ми труди́, святи́телю, я́же на землі́, небе́сний поко́й прия́т, іді́же святи́х ли́кове і пра́ведних всесві́тлоє торжество́. Отону́дуже і нас помина́й, па́м'ять твою́ при́сно сла́в'ящих.","Приспів: Святи́телю, о́тче Стефа́не, моли́ Бо́га о нас.","Ві́чних і нетлі́нних улучи́ти жела́я, святи́телю, і я́же в ми́рі мня́щихся сла́дких оста́вив, Христу́ послі́довал єси́. Ті́мже і ли́ку архієре́йському сочета́лся єси́, пресла́вне.","Догма́том благоче́стія научи́вся, прему́дре святи́телю, апо́столом ревни́тель бил єси́ і і́дольськую пре́лесть низложи́л єси́, ті́мже твою́ па́м'ять досто́йно ублажа́єм.","Богородичен: Плоть прия́ти восхоті́в, в Тя всели́ся, єди́ну святі́йшу всіх обрі́т Богоро́дицю, воі́стинну яви́ Ма́тер Ді́ву."]},{"h":"Світилен","ps":["Ні челові́ком, ні от челові́к, но от Бо́га ізбра́ніє святи́тельства приї́м, і́же пре́жде тьми си́ни, ни́ні же ча́да і наслі́дники Сві́та, твої́м уче́нієм сотвори́л єси́, прему́дре Стефа́не."]}],"notes":[]},{"u":"Канон дев’яти мученикам Кизицьким","e":"Canon to the Nine Martyrs of Cyzicus","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Тріста́ти крі́пкия, Рожде́йся от Ді́ви, безстра́стія во глубині́, душі́ трича́стноє потопи́, молю́ся, да Тебі́, я́ко в тимпа́ні, во умерщвле́нії тілесе́ побі́дноє воспою́ пі́ніє.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Боже́ственними добро́тами наслажда́ющеся вку́пі, і пото́ка пи́щнаго напита́ющеся бога́тно, і прича́стієм обожа́ємі, му́ченици вінцено́сці, вас блажа́щия от лю́тих бід ізба́віте.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Я́коже со́лнечния лучи́, возсія́вше, заря́ми тве́рдих по́двиг, страда́льці, і чуде́с сія́нії вся просвіща́єте, страсте́й нощ рішіте́ і де́монов мрак разоря́єте.","Умерщвле́ни на землі́ я́звами болі́зней, к неболі́зненній жи́зні прейдо́сте вку́пі, ю́нії многострада́льнії. Ті́мже то́чіте ісціле́нія, вся́ку болі́знь облегча́юще богоприя́тними моли́твами, пребога́тії.","Богородичен: Родила́ єси́ Бо́га із чи́стих Твої́х крове́й, вопло́щшася па́че ума́ зра́ком і́же по нас, Ма́ти Пренепоро́чная. Ті́мже всі Тя, ро́дове родо́в, ублажа́ють, святи́х му́ченик утвержде́ніє."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію, і си́лою, і бога́тством хва́лимся, но Тобо́ю, О́тчею іпоста́сною Му́дростію, Христе́: ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ме́ртвим істука́нним пожре́ти ніка́коже восхоті́вше, Поже́ршемуся нас ра́ди же́ртва жива́ принесо́стеся, о́троци прекра́снії, святі́ї му́ченици.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Зако́ни Боже́ственними, укріпля́ємі си́лою Ду́ха, беззако́ннующих сові́ти і ловле́нія низложи́сте і, зако́нні пострада́вше, сла́ву улучи́сте.","Да восхва́литься Арте́ма і Филимо́н, Феости́х і Магн, Руф сла́вний, і Антипа́тр, і Фавма́сій, Фео́гній і Феодо́т великоімени́тії.","Богородичен: Ору́жія вся вра́жія ни́ні до конця́ оскуді́ша, Тебі́ ро́ждшей Христа́, уя́звлена копіє́м, Всенепоро́чная, о Не́мже му́ченици, уязви́вшеся, пострада́ша."]},{"h":"Сідален","ps":["Лик світови́ден свяще́нних страда́лець, совокупле́ніє красно́, богособра́нен собо́р, дев'яточи́сленний соста́в, пострада́вше крі́пко, попра́вше вра́жиє мучи́тельство і причто́стеся а́нгельським лико́м, Го́сподеві предстоїте́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці при́йде Ісу́с Пребоже́ственний нетлі́нною дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Сожже́нія страда́льці і богожре́нная заколе́нія, приноше́ніє соверше́нно, же́ртви прия́тни, приведо́стеся во́лею поже́ршемуся і смерть умертви́вшему. Ті́мже вас ублажа́єм.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Чу́до вели́коє показу́юще, сля́ченния іспра́висте, страда́льці, ру́ки, і во́днаго труда́ ізба́висте прибі́гшаго с любо́вію к ра́ці ва́шей, наро́чита му́жа іногда́, досточу́днії.","Да ублажа́ться досто́йно Арте́ма і Антипа́тр, Феости́х і Руф, Магн, і Филимо́н, і Фео́н, і Фео́гн с сла́вним Феодо́том, пострада́вшії, зову́ть: сла́ва, Христе́, си́лі Твоє́й.","Богородичен: І́же в ні́дріх О́тчих неізрече́нно сідя́й, на Твої́х об'я́тіїх сіди́ть, Ді́во, я́ко Младе́нець, Єго́же блаже́нную страсть вообража́юще, добропобі́днії о́троци ізво́лиша умре́ти."]},{"h":"Пісня 5","ps":["Ірмос: Нечести́вії не у́зрять сла́ви Твоєя́, Христе́, но ми Тя, Єдиноро́дне, Оте́чеськия сла́ви Сія́ніє Божества́, от но́щі у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Я́коже ми́сленноє у́гліє, вже́гше ум, попали́сте воі́стину хвра́стную вся́ку пре́лесть, блаже́ннії, і запале́ніє угаси́сте і́дольськоє росо́ю ві́ри.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Разділе́нія в тілесі́х не імі́сте мно́зіх, за Неразді́льную пострада́ти, страда́льці, Тро́йцю іду́ще, ті́мже разруши́сте дия́вола ополче́ніє вся́ко.","Воспіва́єть чудеса́ ва́ша от лука́ваго легео́на разріши́вийся де́монська, му́ченици богови́днії, к честни́м ковче́гом ва́шим прише́дий со усе́рдієм.","Богородичен: Ізбавля́ющи яви́ся нас от бід і прегріше́ній, тлітво́рних страсте́й, і скорбе́й, і обстоя́ній, ві́рою пою́щия Тя, Богоро́дице, Присноді́во."]},{"h":"Пісня 6","ps":["Ірмос: Прийдо́х во глубини́ морськи́я, і потопи́ла м'я єсть бу́ря мно́гих гріхо́в, но я́ко Бог із глубини́ возведи́ живо́т мой, Многоми́лостиве.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Честна́ смерть яви́ся боже́ственних страда́льцев пред Тобо́ю, Бо́же вся́чеських, ї́хже ни́ні почита́я, врачевство́ безме́здноє боля́щим яви́л єси́.","Возви́сивше ру́ці і сердця́ висо́ким нра́вом к Ви́шнему мужеу́мно, лука́ваго возноше́нія, му́ченици богоно́сці, низложи́сте.","Богородичен: Я́коже стог, чре́во Твоє́, Чи́стая, яви́ся, пшени́цю нося́щий безсме́ртія, всіх ві́рних ду́ші пита́ющую і му́ченики просвіща́ющую."]},{"h":"Кондак","ps":["Тве́рдий і всесві́тлий лик му́ченик дев'яти́, Трисо́лнечнаго Божества́ іспові́дниці, на суди́щі Тому́ нача́льно взива́ху: кров і ду́ші на́ша с тілеси́, я́ко непоро́чную же́ртву, прино́сим Тебі́, Влади́ко, в ли́ціх небе́сних Твої́х сопричти́, я́ко Бог Ми́лостивий."]},{"h":"Пісня 7","ps":["Ірмос: Ю́ноши три во Вавило́ні, велі́ніє мучи́телево на бу́йство прело́жше, посреді́ пла́мене вопія́ху: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Іска́пають ва́ші тру́дове, му́ченици, боже́ственния струї́ ісціле́ній всегда́, болі́зней рі́ки ізсуша́юще і скве́рну вся́ку отмива́юще страсте́й, досточу́днії.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ра́довахуся страстоте́рпці, внегда́ скорбі́ти їм, ра́достію неізглаго́ланною, поя́ху, усіка́ємі мече́м: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Тяготу́ неду́гов, стра́сті серде́чния і болі́зні тіле́сния, вся́ку же находя́щую скорб нам облегчі́те, сла́внії страда́льці.","Богородичен: Яви́вшися всім му́чеником, Чи́стая Ма́ти Бо́жия, держа́ва ве́лія, яви́лася єси́ челові́ком заступле́ніє, Тя пою́щим всегда́ свяще́нними пі́сньми."]},{"h":"Пісня 8","ps":["Ірмос: Ізба́вителю всіх Всеси́льне, посреді́ пла́мене благоче́ствовавшия, снизше́д, ороси́л єси́ і научи́л єси́ пі́ти: вся діла́, благослові́те, по́йте Го́спода.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Ра́достную хвалу́ принесе́м вели́кия нам засту́пники, страстоте́рпці му́ченики Пода́вшему, вопію́щим: вся діла́, благослові́те Госпо́дня Го́спода.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Укорени́вшеся на ка́мені ві́ри благоро́дне, я́коже ві́тві, му́ченици, плоди́ нам страда́нія принесо́ша, ві́рою пою́щим: благослові́те, вся діла́ Госпо́дня, Го́спода.","Вра́чеве страсте́й великоімени́тії, душі́ моєя́ стра́сті ісцілі́те, і геє́нни ізба́віте, і тьми о́ния кромі́шнія, моля́ще Христа́ Бо́га на́шего.","Богородичен: Законода́вця Христа́ родила́ єси́, зако́нно страда́вшия вінча́вшаго, страстоте́рпці му́ченики, Єго́же моли́ зако́ном гріха́ побіжде́на м'я, Отрокови́це, ісціли́ти."]},{"h":"Пісня 9","ps":["Ірмос: Є́ва у́бо неду́гом преслуша́нія кля́тву всели́ла єсть, Ти же, Ді́во Богоро́дице, прозябе́нієм чревоноше́нія ми́рові благослове́ніє процвіла́ єси́. Тім Тя всі велича́єм.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Се отверзо́шася вам небе́сная врата́, пострада́вшим, — рече́ Христо́с страстоте́рпцем, — вни́діте і приймі́те, ра́дующеся, воздая́нія болі́зней досто́йная, от ві́ка хра́брствовавшим.","Приспів: Святі́ї му́ченици, молі́те Бо́га о нас.","Кра́сни в ра́нах тіле́сних би́сте і а́нгелом уподо́бистеся, ни́ні же предстоїте́ всіх красоті́, ра́дующеся при́сно, прича́стієм я́ві удобря́ємі кра́сних, всечестні́ї.","Ста́нем в дому́ Бо́жії, восхваля́юще Антипа́тра, Феости́ха же, Ру́фа і Филимо́на страда́нія, боже́ственнаго Фавма́сія чудеса́, Ма́гна і Арте́ма, Фео́гнія і Феодо́та непобі́дноє.","День спасе́нія нам возсія́ святи́х торжество́, є́же соверша́юще моле́бно, вопіє́м їм с ві́рою: му́чеников світоза́рний ве́рше, всіх сердца́ озарі́те.","Богородичен: Обле́кся із Тебе́ Цар в тіле́сную багряни́цю, про́йде, весь красе́н, із утро́би Твоєя́, і вся враги́ побіди́, і побі́ду страда́льцем подаде́, Чи́стая єди́на Присноді́во."]}],"notes":[]},{"u":"Канон преподобному Амфілохію Почаївському","e":"Canon to St Amphilochius of Pochaiv","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Твоя́ побіди́тельная десни́ця, боголі́пно в крі́пості просла́вися: та бо, Безсме́ртне, я́ко всемогу́щая, проти́вния сотре́, ізра́їльтяном путь глубини́ новосоді́лавшая.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Благода́тную по́мощ Твою́, Го́споди, низпосли́ нам, во є́же воспі́ти уго́дника Твоєго́, отця́ на́шего Амфило́хия, благоче́стія подви́жника і ла́ври Поча́євськия украше́ніє ди́вноє.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Любо́в і благоче́стіє роди́тельськоє, я́же ізмла́да восприє́м, чрез все житіє́ досто́йно проне́сл єси́, от си́ли в си́лу восходя́ ду́хом, блаже́нне.","А́ще і пліне́н бил єси́ на бра́ні от враго́во ви́димих, но неви́димаго плі́на страсте́й ізбіжа́л єси́, преподо́бне, плоть покаря́я ду́ху.","Богородичен: Жизнь ві́чную со святи́ми жела́я улучи́ти, Ма́тер Бо́жию вседу́шно возлюби́л єси́, свя́те, і, в дому́ Єя́ на горі́ Поча́євстій всели́вся, досто́йні Бо́гу послужи́л єси́."]},{"h":"Пісня 3","ps":["Ірмос: Єди́не ві́дий челові́чеськаго существа́ не́мощ, і ми́лостивно в не вообра́жся, препоя́ши м'я с висоти́ си́лою, є́же вопи́ти Тебі́, Святи́й, одушевле́нний хра́мі неізрече́нния сла́ви Твоєя́, Человіколю́бче.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Єгда́ у гро́ба настоя́теля почи́вшаго моли́лся єси́, преподо́бне, откри́ Госпо́дь тебі́ суєту́ житія́ вре́меннаго, ті́мже, помишля́я о жи́зні ві́чній, нача́ть гріхи́ своя́ пред всі́ми іспові́дати.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Нарече́н бив, блаже́нне, Іо́сиф, є́же сказу́ється преумно́женний, сего́ ра́ди потща́лся єси́ благода́ть в се́рдці твоє́м оби́льно преумножа́ти.","Єгда́ са́ном ієре́йським почте́н бил єси́, свя́те, тогда́ моли́тви, поще́нія і по́двиги усугу́бил єси́, бі́си же, не терп'я́ще доброді́тельнаго житія́ твоєго́, мно́гажди тя хотя́ху погуби́ти, ти же си́лою Бо́жиєю при́сно храни́м бил єси́.","Богородичен: Сла́внійшая без сравне́нія Серафи́м і честні́йшая Херуви́м, Пресвята́я Ді́во, усли́ши моле́нія і мольби́ на́ша, і по́мощію Твоє́ю неотсту́пна бу́ди от нас."]},{"h":"Кондак, глас 3","ps":["Я́ко ві́ри правосла́вния ревни́тель і благоче́стнаго житія́ учи́тель, в болі́зніх і ско́рбіх ізря́дний помо́щник, пред Го́сподем предстої́ши, преподо́бне Амфіло́хіє, сего́ ра́ди вопіє́м ті: защити́ оби́тель, в не́йже подвиза́лся єси́, і спаса́й нас моли́твами твої́ми, о́тче блаже́нне."]},{"h":"Сідален, глас 3","ps":["Христо́вою любо́вію преіспо́лнився, преподо́бне Амфіло́хіє, Ду́хом Святи́м ко спасе́нію наставля́л єси́ вопроша́ющих і та́ко, я́ко світи́льник, во тьмі неві́дінія сідя́щим просія́л єси́. Ті́мже моли́ся за ни ко Го́споду, да просвіті́мся і ми Єго́ благода́тію.","Богородичен: Ма́ти Бо́жия, Покро́в Твой спаси́тельний ми́ру до́льнему с Небесе́ явля́ющая, не оста́ви нас, во грісі́х погиба́ющих і Го́спода Милосе́рднаго прогнівля́ющих, Єго́же моли́ ізба́витися нам душепа́губнаго заблужде́нія, я́ко Предста́тельниця на́ша крі́пкая і Помо́щниця ско́рая."]},{"h":"Пісня 4","ps":["Ірмос: Го́ру Тя, благода́тію Бо́жиєю приосіне́нную, прозорли́вима Авваку́м усмотри́в очи́ма, із Тебе́ ізи́ти Ізра́їлеву провозглаша́ше Свято́му, во спасе́ніє на́ше і обновле́ніє.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Ізбра́нний сосу́д Ду́ха Свята́го бив, мно́гія боля́щия благода́тію Бо́жиєю ісціли́л єси́ і бісо́в полки́ побіди́л єси́, о́тче блаже́нне. Прийми́ моли́тви на́ша і от язв гріхо́вних ісціли́.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","О́браз му́жества і дерзнове́нія богому́драго в тебі́ зрим, о́тче преподо́бне, храм бо Святи́я Тро́йці от поруга́нія і запусті́нія сохрани́л єси́ і ві́рния лю́ди, в ско́рбі су́щия, возвесели́л єси́.","То́ки слез пролива́л єси́, преподо́бне, о заблу́ждших ча́діх Це́ркве Правосла́вния, вре́менная бла́га па́че ві́чних благ возлюби́вших.","Богородичен: Чту́щих Тя і в пі́сніх велича́ющих, не отри́ни нас, Пресвята́я Ді́во, іни́я бо Хода́тайці і Засту́пниці ра́зві Тебе́ не і́мами."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́вий сія́нієм прише́ствія Твоєго́, Христе́, і освіти́вий Кресто́м Твої́м ми́ра конці́, сердца́ просвіти́ сві́том Твоєго́ богоразу́мія правосла́вно пою́щих Тя.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Єгда́ в темни́цю лю́тії гони́теліє всади́ша тя к бісни́м і ума́ лише́нним, тогда́ смире́нні взива́л єси́, о́тче блаже́нне: сла́ва Бо́гу, благоді́явшему мі.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Ні скорб, ні тіснота́, ні гоне́нія, ні глад, ні нагота́, ніже́ біда́, ні меч, ні і́на ка́я напа́сть не возмо́же разлучи́ти тя от любве́ Бо́жия, о́тче преподо́бне.","А́нгел земни́й і челові́к Небе́сний яви́лся єси́, о́тче, мно́гія бо ско́рби в житії́ безро́потні поне́сл єси́, ті́мже і воздая́нія мно́га на Небесі́ восприя́л єси́, блаже́нне.","Богородичен: Ше́дше, возвісти́м всім язи́ком, коли́кая чудеса́ сотвори́ Пресвята́я Богоро́диця во уді́лі Своє́м Поча́євстем і ка́ко ми́луєть всіх, с ві́рою приходя́щих к Ней."]},{"h":"Пісня 6","ps":["Ірмос: Оби́де нас послі́дняя бе́здна, ність ізбавля́яй, вміни́хомся, я́ко о́вці заколе́нія. Спаси́ лю́ди Твоя́, Бо́же наш: Ти бо крі́пость немощству́ющих і ісправле́ніє.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Амфило́хий в схи́мі святі́й нарече́н бив, преподо́бне, труди́ ко трудо́м прилага́л єси́ і доброді́тельми, я́ко степе́ньми, во Ца́рствіє Небе́сноє возше́л єси́.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Мно́жество боля́щих, приходя́щих к тебі́, ісціля́л єси́ і стра́ждущих свобожда́л єси́ от духо́в нечи́стих, кро́тостію і смире́нієм тіх побіжда́я.","Фесви́тянину Ілії́ ре́вностію подража́я, преподо́бне, любо́вію боже́ственною се́рдце твоє́ распаля́л єси́ і, в терпі́нії ду́шу твою́ укріпля́я, проро́чеськи вопія́л єси́: с на́ми Бог, разумі́йте, язи́ци, і покаря́йтеся, я́ко с на́ми Бог.","Богородичен: І́м'я Твоє́, Пречи́стая, всі ро́ди правосла́вних непреста́нно велича́ють, і ли́ци церко́внії сладкогла́сно воспіва́ють: Богоро́дице Влади́чице, спаси́ нас, мно́гими бо напа́стьми обстої́ми єсьми́."]},{"h":"Кондак, глас 2","ps":["Ізволе́нієм Ді́ви Пречи́стия в оби́телі Поча́євстій всели́лся єси́, іді́же, подви́жничеськоє і ско́рбноє житіє́ провожда́я, да́ром моли́тви у́мния обогати́лся єси́ і Ца́рствія Небе́снаго наслі́дник яви́лся єси́. Ті́мже вопіє́м ті: ра́дуйся, Амфіло́хіє, о́тче блаже́нне, ціле́бниче і чудотво́рче."]},{"h":"Ікос","ps":["Сокро́вища Небе́снаго взиску́я, преподо́бне, Го́спода Ісу́са, я́ко би́сер многоці́нен, обрі́л єси́ і, вся Єго́ ра́ди оста́вив, стори́цею в пакибитії́ прия́л єси́. Ни́ні же душе́ю твоє́ю светолу́чною на Небесі́х сія́я і моща́ми многоціле́бними во оби́телі Поча́євстій пребива́я, приє́млеши цілова́ніє от почита́ющих тя і велегла́сно взива́ющих: ра́дуйся, Амфіло́хіє, о́тче блаже́нне, ціле́бниче і чудотво́рче."]},{"h":"Пісня 7","ps":["Ірмос: Авраа́мстії о́троци в пещі́ Тро́йцю прообрази́вше, о́гненний пла́мень на ро́су преложи́ша і, пою́ще, вопія́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Ла́вра Поча́євськая, іді́же подвиза́лся єси́, преподо́бне, приста́нище ті яви́ся, усипа́льниця же єя́ мо́щі твоя́ прия́т, я́же три́десять літ та́мо в землі́ лежа́ху і тлі́нію не преда́хуся.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","От ві́си Малої́ловицькия ме́ртвенноє ті́ло твоє́ во оби́тель Поча́євськую бра́тія принесо́ша і во усипа́льниці бра́тстей с че́стію погребо́ша. Ти же, преподо́бне, во оби́теліх Небе́сних пребива́я, за ни мо́лишися Бо́гу.","Хода́тай к Бо́гу о лю́діх в житії́ твоє́м бил єси́, о́тче преподо́бне, і по преставле́нії хода́тайствуєши о всіх, с ві́рою ко гро́бу твоєму́ приходя́щих, і ми́лостивий послу́шатель їм бива́єши.","Богородичен: Іспещре́на ря́снами злати́ми, я́ко Цари́ця, Царя́ і Бо́га одесну́ю ни́ні предстої́ши, Влади́чице, моля́щи о всіх, ко о́бразу Твоєму́ на горі́ Поча́євстій притека́ющих."]},{"h":"Пісня 8","ps":["Ірмос: В пещі́ о́троци Ізра́їлеви, я́коже в горни́лі, добро́тою благоче́стія чисті́є зла́та блеща́хуся, глаго́люще: благослові́те, вся діла́ Госпо́дня, Го́спода, по́йте і превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Єгда́ лю́діє, одержи́мії ду́хи нечи́стими, ко гро́бу твоєму́ притека́ху, преподо́бне, бі́си, в них су́щії, твоєя́ свя́тости терпі́ти не могу́ще, гро́мкими гла́си вопія́ху, огне́м Бо́жия благода́ті опаля́ємі.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Пресла́вноє чу́до о тебі́ зрим, преподо́бне, ти бо, я́ко при жи́зні, та́ко і по преставле́нії, лю́дем стра́ждущим помога́єши і от лю́тих обстоя́ній с ві́рою приходя́щих к тебі́ свобожда́єши.","Ра́дости неізглаго́ланния іспо́лнишася мона́си і мирсті́ї, єгда́ ті́ло твоє́, преподо́бне, три́десять літ в землі́ погребе́нноє, нетлі́нно і благоуха́нія іспо́лнено обрі́теся.","Богородичен: Єди́на благослове́нная і богора́дованная Влади́чице, Я́же ра́дость челові́ком ро́ждши неізрече́нную, іспо́лни ра́дости сердця́ на́ша, да просла́вим ро́ждшагося от Тебе́ Христа́."]},{"h":"Пісня 9","ps":["Ірмос: О́браз чи́стаго Рождества́ Твоєго́, огнепали́мая купина́ показа́ неопа́льная, і ни́ні на нас напа́стей свирі́піющую угаси́ти мо́лимся пещ, да Тя, Богоро́дице, непреста́нно велича́єм.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Чудеса́ і ісціле́нія то́чиши всім, приходя́щим і усе́рдно моля́щимся тебі́ і благогові́йно покланя́ющимся честни́м моще́м твої́м, преподо́бне о́тче Амфіло́хіє.","Приспів: Преподо́бне о́тче Амфіло́хіє, моли́ Бо́га о нас.","Украше́ніє ла́ври Поча́євськия яви́лся єси́, преподо́бне, нетлі́нним бо ті́лом твої́м в пеще́рнім хра́мі ку́пно со І́овом преподо́бним почива́єши і всім, приходя́щим к тебі́, при́сно помога́єши.","Дал єси́ зна́меніє, Го́споди, крест о́блачний на небесі́ в день прославле́нія преподо́бнаго Амфило́хия, і сим кресто́м благослови́л єси́ всіх, прише́дших почти́ти па́м'ять уго́дника Твоєго́.","Тро́їчен: Неразді́льная Тро́йце, во Єди́ниці покланя́ємая, О́тче, Си́не і Святи́й Ду́ше, спаси́ і сохрани́ всіх, почита́ющих па́м'ять уго́дника Твоєго́ Амфило́хия.","Богородичен: Єди́на Чи́стая і Непоро́чная, Бо́га без сі́мене ро́ждшая, Богоро́дице Влади́чице, моли́твами уго́дника Твоєго́ Амфило́хия покри́й і соблюди́ нас от вся́каго зла."]},{"h":"Світилен","ps":["По́двигом до́брим подвиза́вся, просія́л єси́, Амфіло́хіє чудотво́рче, в землі́ Воли́нстій, я́ко світи́льник Боже́ственния благода́ті, возжже́нний в ла́врі Поча́євстій. Ті́мже по́мощію твоє́ю не оста́ви всіх, с ві́рою к тебі́ притека́ющих.","Слава: Світи́льника ві́ри і о́браз богоуго́днаго житія́, на горі́ Поча́євстій возсія́вшаго, преподо́бнаго Амфило́хия, яви́л єси́ нам, Христе́ Спа́се, той бо зе́млю на́шу сві́том Єва́нгелія просвіща́єть і путь спасе́нія нам указу́єть.","І нині: Ді́во Пресвята́я, Си́на Бо́жия Єдиноро́днаго пло́тію ро́ждшая, І́же от Отця́ рожде́ннаго пре́жде всіх вік, моли́ Ду́ха Свята́го благода́тію осія́ти оби́тель сію́ і сохрани́ти ю моли́твами ізбра́нника Твоєго́, преподо́бнаго Амфило́хия, Бо́га в Тро́йці Святі́й почита́ющаго."]}],"notes":[]},{"u":"Канон святителю Ігнатію (Брянчанінову), єпископу Кавказькому","e":"Canon to St Ignatius (Brianchaninov), Bishop of the Caucasus","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Путь духо́вний, к Бо́гу Жи́ву веду́щий, преше́л єси́, святи́телю Ігна́тіє, я́сно указу́я нам, ка́ко подоба́єть стезю́ житія́ земна́го преходи́ти, уче́нію Христо́ву вне́млюще.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Пе́рвую степе́нь в лі́ствиці доброді́телей Єва́нгельських, нищету́ духо́вную, узрі́л єси́, о́тче, і той послі́довати, ту́ю возлюби́ти, то́ю путі́ духо́внаго нача́ло полага́ти заві́т твой дал єси́.","Нищета́ ду́ха, — рекл єси́, — соль єсть всіх жертв духо́вних, нищета́ бо ду́ха блаже́нство пе́рвоє нарече́ся во святі́м Єва́нгелії Христо́ві, є́йже всі про́чії блаже́нства, кро́тость, милосе́рдіє, се́рдця чистота́, послі́дують і є́ю соверша́ються.","Богородичен: Ма́ти Сві́та, Пречи́стая Богороди́тельнице, житіє́ спаси́тельно на землі́ с Си́ном і Бо́гом Твої́м соверши́вшая, нас, недосто́йних, укріпи́, от гріхо́в ізба́ви і к пра́вді ві́чній ше́ствовати утверди́."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, єди́не Человіколю́бче.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Пра́вду Христо́ву в житії́ своє́м воспису́я, святи́телю Христо́в Ігна́тіє, обрі́л єси́ на путі́ сем, є́же пла́кати і рида́ти о соді́янних злих і к Спаси́телю ми́ра притека́ти.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","В ю́ності пла́чем і́ночеським го́рці воспла́кал єси́ в ке́ллії своє́й о разруше́нії хра́ма се́рдця челові́чеськаго, Бо́гом созда́ннаго Богослуже́нія возви́шеннаго ра́ди, о пліне́нії душі́ і ума́, от сих же всіх то́кмо єди́нім Богочелове́ком Спаси́телем ізба́вимся.","І па́ки плач стяжа́л єси́, о́тче, в і́ночестім житії́ твоє́м, єгда́ вся прегра́ди, от Бо́га удаля́ющия тя, препобіди́л єси́. Сего́ пла́ча ра́ди пом'яни́ нас, чту́щих святу́ю па́м'ять твою́.","Богородичен: Ді́во Пречи́стая, печа́лі на́ша і ско́рби утоля́ющая, плач спаси́тельний подава́й нам, да о бе́здні зол на́ших і непра́вд воспла́чем пред Тобо́ю."]},{"h":"Сідален","ps":["Поуча́л єси́, о́тче достохва́льне, я́ко моли́тву чи́сту стяжа́ти, та́же чу́вство покая́нія і пла́ча возлюби́ти дово́льно єсть, во є́же спасе́ніє ві́чноє улучи́ти, єго́же і нас, грі́шних, сподо́би моли́твами твої́ми, свя́те."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Та́йни житія́ і́ночеськаго взиску́я, блаже́нне Ігна́тіє, позна́л єси́, я́ко ка́ятися подоба́єть і труд і́ночеський нічто́же і́но єсть, є́же ді́ланіє непреста́ннаго покая́нія.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","В покая́нії, слеза́х і пла́чі о соді́янних злих узрі́л єси́, о́тче, спасе́нія путь, ко го́рній жи́зні веду́щий, і́же предлежи́ть і вся́кому нося́щему і́м'я Христо́во.","Рекл єси́, о́тче преподо́бне, я́ко до́лжно єсть покая́нієм стра́сті отсіка́ти, та́же покая́нієм доброде́ланіє стяжа́ти, і а́ще не у́зрить о́ко на́ше, я́ко грі́шни єсьми́, не і́мами спасе́нія ві́чнаго улучи́ти.","Богородичен: Ма́ти Бо́жия, грі́шних Спору́чнице і Помо́щнице, путь наш, к Бо́гу веду́щий, покая́нієм і́стинним укріпи́, зрі́нієм гріха́ і іспові́данієм єго́ напра́ви."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Пла́чем і покая́нієм непреста́нним ду́шу твою́ снабдіва́я, о́тче Ігна́тіє, ді́латель моли́тви яви́лся єси́, сію́ от во́зраста младе́нчеськаго возлюби́в, і в основа́ніє жи́зні духо́вния положи́л єси́.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Моли́твою усе́рдною житіє́ твоє́ от ю́ности укріпля́я, да́же до кончи́ни по́двиг твой моли́твенний ко Христу́ Бо́гу соблюда́л єси́, і́мже о Бо́зі Спа́сі утвержда́яся.","Во во́зраст му́жеський прише́д, мона́хов нача́льник бив і многообра́зния ско́рби іспиту́я, в моли́тві тве́рдій і непреста́нній со мно́гими слеза́ми осла́бу і отра́ду і́стинную почерпа́л єси́, о́тче всеблаже́нне.","Богородичен: Ді́во Пречи́стая, Ма́ти Христа́ Бо́га, віне́ць моли́тви неусипа́ющия, о нас, грі́шних, мольбу́ Бо́гу принеси́ і моле́нієм Твої́м от напа́стей і скорбе́й нас ізба́ви."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду, і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися, і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Яви́лся єси́ учи́тель моли́тви серде́чния, о́тче наш Ігна́тіє, я́сно наставля́я, ка́ко до́лжни єсьми́ пред лице́м Христо́вим предстоя́ти і моли́тву покая́нія твори́ти.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Подоба́єть на моли́тві, — поуча́л єси́, о́тче, — вста́ти в ли́ці прокаже́нних, сліпи́х, глухи́х, хроми́х і та́ко ко Христу́, от се́рдця сокруше́ннаго, от нищети́ ду́ха на́шего, моли́тву тща́тися твори́ти.","Єгда́ тишина́ возві́єть в се́рдці на моли́тві, — поуча́л єси́, о́тче, — і мир ко всім, смире́ніє, сострада́ніє і любо́в к челові́ком, тогда́ позна́єм, я́ко благода́ть Ду́ха Свя́та сіє́ соді́ла.","Богородичен: Ма́ти Бо́жия, Ду́ха Свята́го прия́телище непостижи́моє, о сме́ртних нас моли́ся і моли́тву на́шу к Бо́гу упра́ви."]},{"h":"Кондак","ps":["А́ще і соверша́л єси́ стезю́ житія́ земна́го, святи́телю Ігна́тіє, оба́че непреста́нно зрел єси́ зако́ни битія́ ві́чнаго, сему́ поуча́я ученики́ словеси́ мно́гими, і́мже послі́довати і нам, свя́тче, помоли́ся."]},{"h":"Ікос","ps":["Рекл єси́, о́тче, в писа́ніїх твої́х, я́ко подоба́єть імі́ти страх Бо́жий, да́би вступи́ти в соверше́нство всіх доброді́телей, любо́в Бо́жию, і та́ко Отцю́ Небе́сному уподо́битися. Сему́ уче́нію послі́довати і нам, свя́тче, помоли́ся."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","В зи́мнім обнаже́нії ві́твей древе́сних поуча́лся єси́, о́тче, та́йні воскресе́нія ме́ртвих, я́коже бо дре́во во вре́м'я своє́ ли́ствієм покрива́ється, та́ко і ко́сті челові́чеськія оживу́ть і, обле́кшеся пло́тію, в мир но́вий вступи́ти і́муть.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Позна́л єси́, о́тче, єли́ко возмо́жно, та́йну кончи́ни битія́ челові́чеськаго, та́йну єстества́ а́нгельськаго і душі́ челові́чеськія, і возда́л єси́ благодаре́ніє Бо́гу.","Єди́наго то́кмо Бо́га, Ду́ха І́стини, іспові́дал єси́, І́же Єди́н всесоверше́н єсть, Єму́же покланя́ющеся, тя, о́тче, велича́єм.","Богородичен: Ді́во Марі́є, Ма́ти Неізрече́ннаго Сві́та, нас, грі́шних, от ми́сленних паде́ній огради́, Боже́ственноє же уче́ніє Це́ркве Святи́я в сердця́х на́ших укріпи́."]},{"h":"Пісня 8","ps":["Ірмос: На горі́ святі́й просла́вльшася, і в купині́ огне́м Присноді́ви Моїсе́йові та́йну я́вльшаго, Го́спода по́йте і превозносі́те во вся ві́ки.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Возлюби́л єси́, о́тче, служи́ти бра́тії сло́вом Бо́жиїм, і бисть тебі́ служе́ніє сіє́ в по́двиг житія́ твоєго́, нам же в ра́дованіє непрело́жноє, вопію́щим ті: не оста́ви нас, о́тче, сло́вом і моли́твами твої́ми.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","В служе́нії Сло́ву усли́шал єси́ в душі́ твоє́й глас увіре́нія во спасе́нії, сего́ ра́ди приі́скренні возлюби́л єси́ бли́жніх твої́х і са́моє то Сло́во Бо́жиє.","Поуча́л єси́ бли́жніх твої́х, святи́телю, я́ко Спаси́тель наш єсть Огнь небе́сний, І́же і в словесі́х Єго́ єва́нгельських ді́йствуєть.","Богородичен: Ма́ти Бо́жия, Бо́га Сло́ва ро́ждшая, даждь сло́во рабо́м Твої́м, є́же сказа́ти та́йну всеми́лостиваго заступле́нія Твоєго́, в та́йні рожде́нія Сло́ва, Христа́ Бо́га, я́вльшуюся."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Мно́гі труди́ і болі́зні под'я́во в житії́ твоє́м, святи́телю всече́стне, Кресту́ Христо́ву, сві́тло сія́ющу, поклони́лся єси́ і моли́тву твою́ ко Христу́ просте́рл єси́.","Приспів: Святи́телю, о́тче Ігна́тіє, моли́ Бо́га о нас.","Скорбми́ обурева́ємий, зрел єси́ во виді́нії в ке́ллії своє́й Стра́нника, посети́вшаго тя. Отку́ду ше́ствуєши? І гді селе́ніє Твоє́? Почто́ досе́лі оставля́л єси́ є? — сла́дці вопія́л єси́, о́тче, я́вльшемуся ті Христу́.","В хожде́нії пред Го́сподем позна́л єси́, о́тче, судьби́ оте́чества твоєго́, та́же і кончи́ну твою́ я́сно прови́діл єси́, к Бо́гу Сло́ву, Христу́ возлю́бленному, моли́твенно устремля́яся.","Богородичен: Ма́ти Бо́жия, сія́ніє неізрече́ннаго Сві́та, стопи́ на́ша к жи́зні ві́чній напра́ви, проща́ющи вся зла́я, на́ми соді́янная."]}],"notes":[]},{"u":"Канон апостолу Якову Зеведеєву, братові апостола Іоанна Богослова","e":"Canon to the Apostle James, son of Zebedee, brother of John the Theologian","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Твоє́ю мре́жею, я́ко лове́ць іску́сен, от прегріше́ній глубини́ возве́д, блаже́нне, ду́шу мою́ просвіти́ світолу́чними сія́нії і похвали́ти твою́ досто́йно, о богоявле́нні Іа́кове, па́м'ять, учениче́, сподо́би.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Преві́чний Отцю́, Собезнача́льний, пресоверше́нний же Бог, вопло́щся, яви́ся на землі́ я́ко Челові́к і соді́йственника благода́ті показа́, блаже́нне, і служи́теля тя прему́дра, си́лою Єго́ укріпля́єма.","Разумі́ твоєя́ душі́ благоро́діє, тя Прові́дець Бог, і тве́рдость, учениче́, і непобори́му мисль, сла́вне, Свої́м служи́телем лу́чша поста́ви, язи́ком возвіща́юща.","Богородичен: Сові́та Вели́каго, о́тче, А́нгел, от Ді́ви Ма́тере я́влься ми́ру, плоть приє́м, я́ко доброді́тельми укра́шена ученика́ тя показу́єть і богогла́сника, Іа́кове, словеса́ Єго́ віти́йствующа."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі небеса́ ра́зумом і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят, па́че Тебе́, єди́не Человіколю́бче.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Сви́ше тя диха́ніє ну́ждноє Уті́шителя разже́гше, му́дра богогла́сника, віти́йствующа я́ві вели́чія показа́ вопло́щшагося Сло́ва, Єго́же і самови́дець бил єси́.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Тя, я́коже стрілу́ ізбра́нну, сло́вом ізощре́нну, в сердця́ враго́во вонзи́, растерза́я ду́ші сопроти́вних, прему́дре, і пліня́я, таї́нниче, сих кори́сти, Іа́кове.","Нескве́рния твоєя́ душі́ ти́хость Влади́ці узрі́ся, і пре́жде зва́нія, блаже́нне, достоприя́тен Єму́ яви́лся єси́, о Іа́кові, і смотре́нія Єго́ учени́к бил єси́.","Свяще́нним твої́м, му́дре, житіє́м і світоно́сним, є́же к Бо́гу сро́дством, всеблаже́нне, украша́єм я́сно, і соо́бщник показа́лся єси́, ізмла́да бо яви́лся єси́ Сло́ва ссе́льник.","Богородичен: Двер яви́ся ми́сленная Восто́ка сви́ше, су́щим на землі́ я́вльшагося, Ді́во: Тобо́ю бо к нам Сло́во приї́де спасти́ всіх от безслове́сія, Пречи́стая."]},{"h":"Сідален","ps":["Улови́в язи́ки апо́стол сла́вний і научи́в конці́ земни́я Тебі́ кла́нятися со Отце́м і Ду́хом, Христе́ Бо́же, того́ ра́ди утверди́ Це́рков Твою́ і ві́рним низпосли́ благослове́ніє Твоє́, Єди́не Ми́лостиве і Человіколю́бче.","Богородичен: Прему́дрость і Сло́во в Твоє́м чре́ві заче́нши неопа́льно, Ма́ти Бо́жия, ми́ру родила́ єси́ мир Содержа́щаго, і во об'я́тіях понесла́ єси́ вся Нося́щаго, Пита́теля всіх і Творця́ тва́рі. Ті́мже молю́ Тя, Всесвята́я Ді́во, і ві́рно сла́влю Тя ізба́витися мі от прегріше́ній, і в день Суда́, єгда́ предста́ти і́мам пред лице́м Созда́теля моєго́, Влади́чице Ді́во Чи́стая, Твою́ по́мощ тогда́ пода́ждь мі: вся бо мо́жеши, єли́ка хо́щеши, Всепі́тая."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Пропові́дник Христо́в бив, боже́ственний Іа́кове, ти, зван, у́бо ско́ро послі́довал єси́, оте́чеськую любо́в презрі́в і ві́чная ізміни́в теку́щими; тім неізрече́ннаго небе́снаго наслі́дія сподо́бился єси́, блаже́нне приснопа́м'ятне.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","О, те́плаго жела́нія твоєго́ ко Влади́ці Христу́! Ти бо Сего́ зіло́ возжела́л єси́, сія́нієм Того́ просві́щся, я́коже і вообрази́тися, і яви́тися всім світ втори́й, пе́рваго заря́ми озари́вся і сла́вою, всече́стне блаже́нне Іа́кове.","Житіє́ че́стно імі́л єси́ і пречу́дно, жела́нієм бо жела́ніє неодержи́мо приє́м, жела́нії богонача́лія соверше́ннаго блаже́нства дости́гл єси́, богови́дче, со безпло́тними поя́: си́лі Твоє́й сла́ва, Человіколю́бче.","Всего́ себе́ манове́нію отда́во Влади́чню, учениче́ Богозра́чне, доброді́тельми взя́лся єси́ явле́нно к висоті́ і боже́ственному воі́стину кра́ю, і отту́ду ціле́б рі́ки істоча́єши па́м'ять твою́ ві́рно сла́в'ящим.","Богородичен: Ти ві́рних похвала́ єси́, Безневі́стная, Ти Предста́тельниця, Ти і прибі́жище христия́н, стіна́ і приста́нище, к Си́ну бо Твоєму́ мольби́ но́сиши, Всенепоро́чная, і спаса́єши от бід ві́рою і любо́вію Богоро́дицю Чи́стую Тебі́ зна́ющия."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Нов, я́коже Ілия́, ре́вностію разжига́єм, непоко́ршіяся пропові́данію твоєму́ попали́ти восхоті́л єси́, сла́вне, но возбрани́ тебі́ Хоти́тель милосе́рдія, науча́я кро́тости благода́тній.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Вшед, доброді́телію коне́чною впери́м любве́ ра́ди лу́чших, престо́л Влади́ки возжела́л єси́, прему́дре, нача́льная держа́ти, не я́ко жела́я сла́ви су́єтния, но зрі́ти посреди́ Єго́же возжела́л єси́.","Превзи́де уста́ви, Спа́се, Іа́ков челові́чества, во Твою́ бо си́лу, я́ко в ри́зу, обле́кся, ісціле́нія то́чить рі́ки і чуде́с і просвіща́єть ві́рою конці́.","Сві́тел тя о́блак Сло́ва, облиста́юща сла́вою обоже́на, на Фаво́рстій го́ре осіни́, блаже́нне Іа́кове, і глас сли́шати Оте́чеський сподо́бился єси́, ізвіству́яй Того́ Синовство́."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна гріхо́в і прегріше́ній бу́ря м'я смуща́єть і во глубину́ ну́жднаго рі́єть м'я отча́янія, но Твою́ крі́пкую ру́ку мні простри́, я́ко Петро́ві, о Упра́вителю! І спаси́.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Струи́, я́ко от істо́чника, ісціле́ній непреста́нно ізлива́я і просвіще́ніє уче́нія благоче́стно істоча́я, му́дре, ду́ші, благоче́стно любо́вію, Іа́кове, приступа́ющия, просвіща́єши, преблаже́нне.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Сосу́д вместя́щ Влади́ка обрі́т тя, преблаже́нне, Своєго́ бога́тнаго і честна́го дая́нія, оби́луєть дарова́нії, і́же па́че ума́ та́їнств, служи́телю присносу́щния жи́зні.","Умерщвле́ніє нас ра́ди Влади́ка восхоті́ восприя́ти, ме́ртвих вину́ і́стиннаго воскресе́нія, я́ко му́дра таї́нника, блаже́нне, тя взят соді́тельника, в нощі́, в не́йже предая́шеся.","Богородичен: Бе́здну щедро́т ро́ждшая, Богоро́дице Ді́во, от печа́льних житія́ ду́шу мою́ спаси́ і ра́дости духо́вния две́рі мі отве́рзи, на Тя бо єди́ну наде́жду мою́ возложи́х."]},{"h":"Кондак","ps":["Глас Боже́ственний сли́шав, призива́ющ тя, любо́в отця́ презрі́л єси́ і прите́кл єси́ ко Христу́, Іа́кове, с сро́дником твої́м, сла́вне, с ни́мже сподо́бился єси́ ви́діти Госпо́днє Боже́ственноє преображе́ніє."]},{"h":"Ікос","ps":["Вку́пі сий с бра́том в се́ліх небе́сних, і́же свята́я ни́ні ага́ряни попира́ющия, нога́ми скве́рними і нечи́стими ходя́щия, боже́ственними ва́шими моли́твами отжені́те, і мучи́телем умишле́нія отсі́кше, і і́же от них мно́жества ра́ди согріше́ній на́ших держи́мих, ни́ні свобожде́нія сподо́біте: я́ко да во єди́но собра́вшеся, ви́дим Госпо́днє Боже́ственноє преображе́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снисхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Ча́шу іспи́л єси́, я́коже обіща́лся Влади́ці Христу́, креще́нієм Сего́ ти крести́лся єси́, богоблаже́нне. Єму́же ни́ні усе́рдно зове́ши, ра́дуяся: благослове́н Бог оте́ць на́ших.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Заре́ю осія́єм боговиді́нія, яви́лся єси́, Іа́кове. Сего́ ра́ди тя вінце́м Ца́рствія Благода́тель Христо́с украша́єть, со а́нгели пою́ща: благослове́н Бог оте́ць на́ших.","Се тебі́ іспо́лни обіща́нія Великода́вець, к Нему́ возне́сся подо́бієм страда́ній Єго́, Єму́же предстоя́, ни́ні зове́ши, ра́дуяся: благослове́н Бог оте́ць на́ших.","Богородичен: Дво́їцю у́бо єстество́м, но не лице́м, Ма́ти, пропові́дуєм, із Тебе́ воплоще́ннаго. Єго́же пло́тію ізобража́єм і покланя́ємся зра́ка воображе́нію, Тебе́ ра́ди Бо́гу прими́ршіїся, Чи́стая."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Авраа́мськоє предложе́ніє ти, богови́дче, стяжа́л єси́, призва́вшему тя Христу́ послі́дуя, і пресві́тел служи́тель бил єси́ Єму́, я́ко Соді́телю і Ізба́вителю, поя́: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Кріпча́йше яви́ся гро́ма твоє́ провозглаше́ніє, зако́ннаго о́браза шумі́ніє. Христа́ бо возгремі́л єси́ вселе́нній всей, Бо́га, і Соді́теля, і Ізба́вителя, поя́: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Удиви́лся єси́, сла́вне, муче́нія сві́тлостію і благоче́стія і́стинним просвіще́нієм, я́ко князь апо́стол поста́влен бил єси́ по всей землі́, Соді́телю і Ізба́вителю поя́: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те Христа́ во ві́ки.","Богородичен: Вити́йстії язи́ци Тебі́ воспі́ти не мо́гуть, о Богороди́тельнице, Марі́є Богоневі́сто! Бо́га бо родила́ єси́, су́щаго над всі́ми, Отрокови́це Чи́стая, Соді́теля і Ізба́вителя, Єму́же вопіє́м: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, а́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Свя́то преше́д твоє́ житіє́, святи́х селе́нія дости́гл єси́, іді́же, ра́дуяся, зарю́ зри́ши трисія́нную; єя́же наслажда́яся, прему́дре, іспо́лнени весе́лія півці́ твоя́ і ра́дости, преблаже́нне, покажи́ твої́ми моли́твами, о Іа́кові!","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Ви́діти тя злоді́ї і уби́йці, я́коже твоєго́ Влади́ки пре́жде, не терп'я́ще: тіх бо дія́нія укоря́я, твоєго́ житія́ предложе́нієм обличи́л єси́, убива́ють мече́м подража́теля Христу́, расп'я́тому пло́тію за челові́ки, о богоглаго́ливе преблаже́нне!","Ору́жієм небе́сним томле́н бив, ра́нами І́род поги́бе, я́ко Твоя́, Сло́ве, служи́телі і ученики́, ї́хже апо́столи наре́кл єси́, убива́ти не дово́лен бисть окая́нний. Ті́мже тя, пра́ведному промишле́нію Благода́теля, уди́вльшеся, велича́єм.","Богородичен: Яви́лася єси́, о Ді́во, Ма́ти Бо́жия, па́че єстества́ ро́ждши пло́тію Бо́га Сло́ва, Єго́же Оте́ць отри́гну от се́рдця Своєго́, пре́жде всіх вік, я́ко Благ, Єго́же ни́ні і тіле́с преви́шша разуміва́єм, а́ще і в ті́ло облече́ся."]},{"h":"Світилен","ps":["Іа́кова воспоє́м Зеведе́ова всі: со Христо́м бо взи́де на го́ру Фаво́рськую, і зри́тель бисть Боже́ственнаго преображе́нія, і, соше́д, пропові́даша в четвероконе́чную всю с Петро́м і Іоа́нном."]}],"notes":[]},{"u":"Канон преподобним Антонію і Феодосію Печерським","e":"Canon to Sts Anthony and Theodosius of the Caves","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Я́ко грубосло́вен і косноязи́чен, недоумі́я вам, преподо́бнії отці́, хвале́ніє принести́, молю́ся: да́рствуйте моли́тву о мні, є́же да́тися отсви́ше да́ру воспі́ти па́м'ять ва́шу, сла́вна бо єсть ми́ру і сла́вно просла́вися.","От млади́х ногте́й в дар принесо́сте себі́ Бо́гові, о преблаже́ннії отці́, ті́мже, приє́м ва́ше благо́є предприя́тіє, благода́тію Ду́ха наста́вил ви єсть на путь пра́вий.","За́повідей спасе́нних послу́шавше, жизнь вре́менную преоби́дісте і, Крест Госпо́день на ра́мо взе́мше, мра́чний мир непреткнове́нно прейдо́сте, Небе́сним жела́нієм води́ми.","Оте́чество, роди́телі, дру́ги і бога́тство, а́ки пре́лесть, отве́ргше, го́рній Ієрусали́м Бо́га же Отця́, не стидя́щагося вас бра́тію нариця́ти, Христа́, єди́н би́сер взиска́ти ті́сним путе́м ізво́листе, Анто́ніє свободоімені́те і Феодо́сія богодарова́нне.","Я́ко пустиннолю́бния го́рлиці, гор Пече́рських дости́гше, богоно́снії отці́, во подзе́мная міста́ всели́стеся і, на тве́рдом духо́внаго жела́нія основа́нії гніздо́ своє́ поло́жше, богопе́снивия породи́сте птенці́, і́ночествующих ли́ки.","Троїчен: Сла́ва Ті, сла́ва, Тро́йце Пресвята́я, тихообра́зно подаю́щая благода́ть в сердця́ ві́рних, да сконча́єм хвале́нія святи́х ді́ло і возвеселі́мся зіло́, честні́ї дру́зі Твої́, Го́споди.","Богородичен: Упра́ви ум мой, Пречи́стая, во хвале́нії преподо́бних Твої́х, да не укло́нься в неподо́бная, пліни́ться в рабо́ту лука́вства, і бу́ду ра́дованіє чужде́му."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний істо́чниче, лик себі́ совоку́пльшія, духо́вно утверди́, в Боже́ственній Твоє́й сла́ві вінце́в сла́ви сподо́би.","Я́ко єле́нь, возжа́ждав духо́внаго питія́, о́тче Анто́ніє, от Пече́рськия гори́ на Афо́нськую го́ру, скача́, прише́д, обрі́те струї́ ангелови́дних оте́ць житія́, і сим поревнова́в, от пото́ка уче́нія їх іспи́в, і утверди́ся.","Втора́го тя Мойсе́я, Анто́ніє, скрижа́ли доброді́телей на Пече́рськую го́ру прине́сшаго, сли́шав, Феодо́сій, прите́к, глаго́ля: вчини́ м'я в сих любо́в, утверди́ м'я в них, а́ки в ми́ріх, уя́звен бо єсьм любо́вію сопосле́довати христоподража́нному житію́ твоєму́.","Любо́вію і жела́нієм ко Бо́гу єдиноу́мне сопря́гшеся, отці́ преподо́бнії, на колесни́цю смире́нія, нищети́, терпі́нія і чистоти́ всідо́сте і превисо́ких достиго́сте святи́х селе́ній.","Кто не удиви́ться ва́шему житію́, о преблаже́ннії отці́? Кто не почуди́ться ре́вности по Бо́зі? Я́ко во пло́ті су́ще, А́нгелом весьма́ уподо́бистеся, ї́хже і сожи́теліє су́ще ни́ні, не забу́діте і нас, пі́сньми вас ублажа́ющих.","Троїчен: Непостижи́мая бла́гость і ді́йство Твоє́, во Тро́йці Єди́ний Бо́же: я́ко бре́нних воскриля́єши горе́ і от миродержа́вния но́щі ви́спре ко сві́ту возвиша́єши, приводи́мий і устроя́єши, Бог бо єси́ і твори́ши, єли́ка хо́щеши.","Богородичен: По вели́чію Твоєму́, Пречи́стая, блажа́ть Тя всі ро́ди, і ми с ни́ми блажи́м пі́сньми, чту́ще Тя раболе́пним поклоне́нієм, і велича́єм."]},{"h":"Сідален, глас 4","ps":["Небе́сноє бога́тство і присносу́щную сла́ву тща́щеся восприя́ти, нищету́ і смире́ніє смири́вшагося Влади́ки восприя́сте і ми́ру себі́ расп'я́сте со похотьми́ і страстьми́, тім, блажа́ще па́м'ять ва́шу, преподо́бнії отці́ на́ші Анто́ніє і Феодо́сіє, мо́лим: молі́те Христа́ Бо́га дарова́ти нам ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, нетлі́нною дла́нію, і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Самовла́стная ума́, о́тче Анто́ніє, оста́вль, под і́го Влади́чне преклони́лся єси́, єму́же і до́блественний Феодо́сій припря́гся: плени́стеся в послуша́ніє Христо́во і би́сте до́брії ді́лателіє, єдинонра́вни се́рдцем і ду́хом.","Не устраши́ша вас в те́мних пеще́рах де́монськая страхова́нія, доблему́дреннії во́їни, преподо́бнії отці́, но паде́ся ра́туяй вас под нога́ми ва́шими, низве́ржен ору́жієм: те́плия ко Бо́гу моли́тви.","Тве́рдоє ва́ше і жесто́коє житіє́ ви́дів, Всеблаги́й Бог от те́мних міст просвіти́ вас дарова́нієм чуде́с і сла́вни сотвори́ ми́ру, ї́хже недосто́їн бі мир, в гора́х і верте́пах кри́ющихся толи́ких світи́л.","Я́ко пресві́тлая світи́ла поста́ви вас Бог, преподо́бнії отці́, на сві́щници с под спу́да, і просвіти́сте житія́ доброді́тельми і́ночествующих ли́ки, і́же, со́брани, до́брі пожи́ша ва́шим наставле́нієм.","Троїчен: Царю́ царе́м, Всемогу́щая Тро́йце, бре́нія не́мощію обложе́нним нам, рабо́м Твої́м, даждь благода́ть я́сно пі́ти па́м'ять преподо́бних Твої́х, в ни́хже удиви́л єси́ вся хоті́нія Своя́, Бо́же.","Богородичен: Всеси́льная Влади́чице, нас, немощни́х, препоя́ши си́лою на сопроти́вних, подаю́щи немощні́й пло́ті крі́пость: о Тебі́ бо і немощні́ї крі́пкия враги́ побіжда́ють і побіди́тельная в пі́сніх дароно́сять."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й: Ти бо, Неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га і родила́ єси́ Безлі́тнаго Си́на, всім воспіва́ющим Тя мир подава́ющая.","Уче́нієм і творе́нієм би́сте о́браз і́ночествующим, отці́ треблаже́ннії, і ва́шим наставле́нієм мно́зі успі́ша в за́повіді Госпо́дні і сих ісполне́нієм ко го́рнему ше́ствію благи́й путь улучи́ша.","Проро́чеським сподо́бльшеся да́ром, достохва́льнії отці́, ов бо огнь указа́тельний на мі́сто с небесі́ упа́сти сотвори́, ов же ску́дную жи́тницю моли́твою муки́ іспо́лни, от тіх даро́в крупи́цями наси́тити ду́ші на́ша мо́лимся.","Я́ко законода́вці, по́стничеським лико́м предтеко́сте: ти, о́тче Анто́ніє, скрижа́ли дія́нія і виді́нія предлага́я, богода́нний же Феодо́сій жезло́м правле́нія мо́ре страсте́й пресі́к, предхожде́ніє тім показу́я во обітова́нную зе́млю.","Упова́нієм бу́дущих благ себі́ вооружи́вше і Креста́ меч в рука́х іму́ще, побіди́сте ми́сленнаго Амали́ка, і на́ша враги́ пособі́те побіди́ти, я́ко предводи́телей на́ших, мо́лим ви, отці́ преподо́бнії.","Троїчен: Мирода́тельная Тро́йце, Єдиноче́стний Бо́же, мир огради́, правосла́вний лю́ди, предстоя́щий в честні́м хра́мі преподо́бних Твої́х, храм Себі́ сотворя́я сердца́ принося́щих Ті піснь хвале́нія.","Богородичен: Мирополо́жнице і ски́ніє Пресвята́я Бо́га Сло́ва, нам сло́во даждь і мисль упра́ви, во є́же пі́ти Тя, я́ко Благу́ю Благо́му Роди́тельницю."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, Богому́дрії, Богома́тере, прийді́те, рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Ви́шше єстества́ челові́чеськаго подви́гшеся, преподо́бнії, уподо́бистеся безпло́тних чино́м, ті́мже і по́честь сих улучи́сте; сея́ богодароова́нния вам благода́ті і нас, ча́да ва́ша, не лиші́те хода́тайством свої́м ко Бо́гу, мо́лимся.","Вам, а́ки неуси́пним стра́жем, Ді́ва і Богома́ти вві́ри дом Свой, єго́же пасо́сте, от волко́в ми́сленних стрегу́ще в нем собра́нноє ва́ми ста́до, о преблаже́ннії.","Всегда́шнім я́же к Бо́гу ума́ воскри́лієм і воздія́нієм рук, преподо́бнії отці́, ста́вше, Ду́ху Пресвято́му селе́ніє себі́ сотвори́сте, ті́мже вас, а́ки дом Бо́жий преукра́шен, хвала́ми украша́єм.","Сія́ єста́ преудобре́нная отця́, а́ки Херуви́ми, осіня́ющії дом Богома́тере, і а́ки прему́дрії вожди́ і́ночеському ли́ку, ї́хже не удали́стеся заступа́ти во вся́ких ну́ждах і ско́рбіх.","Троїчен: Тро́йце Пресвята́я, жела́тельноє достоя́ніє да́вшая во ски́ніях святи́х богоно́сним первонача́льником на́шим, сих ра́ди і нас того́ сподо́би, в жи́зні сей сохраня́ющей от язи́чеських нахожде́ній.","Богородичен: Тя, Засту́пницю ми́ра і Богома́тер, всего́ живота́ моєго́ спасе́ніє предлага́ю, Ти бо, Бо́га ро́ждши, спасти́ мо́жеши пою́щия Тя і в заступле́ніє кро́ва Твоєго́ прибіга́ющії."]},{"h":"Кондак, глас 8","ps":["Дво́їцю вели́ких оте́ць і пра́вило і́ноков сві́тлоє, у́мния зари́, онебе́сившия Українськую Це́рков, кто по достоя́нію хвала́ми воспоє́ть? Ті́ї бо Престо́лу Бо́жию предстоя́ть. Но, я́ко іму́щії дерзнове́ніє ко Святі́й Тро́йці, Анто́ніє преблаже́нне і Феодо́сіє приснопа́м'ятне, молі́теся о моле́бная вам принося́щих і любо́вію пі́сньми вас ублажа́ющих."]},{"h":"Ікос","ps":["В присносу́щнім Пресвяти́я Тро́йці Боже́ственнім сві́те да воспри́ймете селе́ніє, преподо́бнії отці́, вся лі́та жи́зні сея́ в ті́сной пеще́рі пожи́вшії; ті́мже і, преста́вльшеся от вре́менних, вели́ким чуде́с дарова́нієм от Го́спода сподо́бистеся: болі́зні ісціля́ти, бі́си от челові́к прогоня́ти і без вре́да оби́тель свою́ сохраня́ти, заступа́юще в ско́рбіх; молі́теся о моле́бная к вам принося́щих і пі́сньми любо́вію вас ублажа́ющих."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі Богому́дрії, па́че Созда́вшаго, но о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог благослове́н єси́.","Благу́ю жизнь зді пожи́вше, блаже́нния кончи́ни сподо́бистеся, отці́ святі́ї, преста́висте бо ся от вре́менних к ві́чним честно́ю сме́ртію, я́же бива́єть честна́ преподо́бних Твої́х, Го́споди Бо́же оте́ць на́ших.","Ра́вними труди́ ни́ву душ ва́ших возді́лавше, преподо́бнії, ра́вная сімена́ доброді́телей посі́ясте і по кончи́ні ра́вних воздая́ній пожина́єте радостотво́рния рукоя́ті, пою́ще: Го́споди Бо́же оте́ць на́ших.","На воді́ поко́йні при істо́чниці вод пресла́дких, на ло́жах преподо́бних упокоя́ющеся, преблаже́ннії отці́, от пото́ка сла́достнаго поне́ ка́плею ва́шея благода́ті ча́да ва́ша обда́рствіте, пою́щия в день па́м'яті ва́шея: Бо́же оте́ць на́ших.","Троїчен: Тро́їчеськоє неразді́льне, разді́льні же Ли́ци, оба́че Єди́но чтем Божество́, Безнача́льна Отця́, Собезнача́льна Си́на і Преблагослове́ннаго, от Отця́ ісходя́щаго Ду́ха.","Богородичен: По Боже́ственному существу́ Отцю́ Своєму́ Єдиносу́щественний Бог Сло́во от Ді́ви єдиноєсте́ствен челові́ком яви́ся, плоть приє́м із пречестни́х крове́й і благослове́нную наре́к Свою́ Ма́тер."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Гра́ди і оте́чества своя́, я́коже Авраа́м, оста́висте, ви́шняго гра́да со Авраа́мом жи́теліє ни́ні, богоно́снії отці́, су́ще, отту́ду посіті́те нас в день па́м'яті ва́шея і умолі́те Христа́ с ва́ми нам пі́ти во ві́ки.","І́же ва́ше торжество́ пра́зднующим днесь, о святі́ї уго́дниці, молі́теся ізба́витися вся́каго вра́жия наві́та, от ва́рварських нахожде́ній, на сопроти́вних возвиша́юще рог христия́н правосла́вних, пою́щих Го́спода во ві́ки.","Ми́лостивно о нас простира́йте ру́ці свої́ ко Влади́ці, святі́ї первонача́льници на́ші, і неотлу́чно назира́йте ста́до ва́ше, я́коже обіща́стеся, сохраня́юще то от волко́в ми́сленних, сподо́біте же с ва́ма пі́ти Го́спода во ві́ки.","Сла́вити ва́шу па́м'ять кто не восхо́щеть, той да не улучи́ть ві́чния сла́ви, нам же, сла́в'ящим, умолі́те Го́спода, іді́же ли́ци святи́х, іді́же собо́р преподо́бних со А́нгели, пі́сньми превозноси́ти Го́спода во ві́ки.","Троїчен: я́ко на превознесе́нную возше́дше го́ру, прийді́те, лю́діє, ста́нем во хра́мі преподо́бних первонача́льников Пече́рських і просла́вим Тро́йцю Пресвяту́ю, я́же нас собра́ во дне́шній день просла́вити па́м'ять святи́х Свої́х.","Богородичен: Святу́ю го́ру Бо́жию і селе́ніє Ви́шняго му́дрствующе Тя, Ді́во Чи́стая, зове́м: сла́ва Ті, ма́терем і ді́вам сла́во і похвало́ челові́чеськаго ро́да."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же Безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","І́же ві́рою приходя́щим ко хра́му ва́шему, святі́ї отці́, утіше́ніє подава́йте в ско́рбіх, сохраня́юще сих разли́чних озлобле́ній, я́ко да вас, засту́пников на́ших, при́сно велича́єм.","А́ки десятистру́нная гусль і велегла́сная труба́, Пече́рськая ва́ми согражде́нная Ла́вра пропові́дуєть ва́шу па́м'ять, Анто́ніє богому́дре і Феодо́сіє достохва́льне, созива́ющи лю́ди на хвалу́ і по́честь, ї́хже і ми велича́єм.","Принесе́нноє в дар благода́рственноє на́ше пі́ніє на́зріте, преподо́бнії отці́, і тихосмотри́тельним о́ком і́же грубогранесло́вноє іспра́віте, приє́млюще не я́ко в дар, но я́ко во серде́ць на́ших к вам раче́ніє, і́мже вас днесь велича́єм.","Влади́чней подо́б'ящеся бла́гости, а́ки дві ле́пті, пі́ніє і ді́ланіє сіє́ от нас приє́мше, треблаже́ннії отці́, іспросі́те гріхо́м оставле́ніє, в час же коне́чний предста́ніте нам, обнаде́ждующе упова́нієм доіти́, іді́же святі́ї Христа́ Царя́ велича́ють.","Єли́ко духо́вную благода́ть Пресвята́го Ду́ха во гру́бий ра́зум, толи́ко воспі́ти дерзну́х па́м'ять ва́шу, Анто́ніє свя́те і Феодо́сіє блаже́нне, сим наверша́я: даю́щему моли́тву моля́щемуся і пі́ніє хотя́щему Бо́гу Єди́ному сла́ва бу́ди, бу́ди.","Богородичен: Хоті́нієм смотре́нія Своєго́ вся сотвори́вий, Пречи́стая, із Тебе́ воплоти́вийся Бог І́стинний і Челові́к Соверше́нний."]},{"h":"Світилен","ps":["Сві́та су́ще ви́шняго ближа́йшії гра́ждане і прекра́снаго Ієрусали́ма насе́льници святі́ї, ни́жніх, ви́ну ра́туємих, посіті́те і подава́йте по́мощ ва́шу честну́ю па́м'ять ни́ні восхваля́ющим.","Богородичен: Сві́та Тричи́сленнаго Ді́ва су́щи і Ма́ти, во сві́ті вчини́ жи́ти ви́шнем пою́щих нетлі́нноє Рождество́ Твоє́, Обра́дованная."]}],"notes":[]},{"u":"Канон апостолу і євангелісту Іоанну Богослову","e":"Canon to the Apostle and Evangelist John the Theologian","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Ца́рство Небе́сноє, блаже́нне, є́же пропові́дал єси́, восприї́м і Сло́ву собесі́дник бив Небе́сному, ве́рующия честно́му твоєму́ пропові́данію і богосло́вію твої́ми моли́твами сохрани́.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Крі́пок смисл явля́я, о всіх небре́гл єси́ су́щих на землі́ і уз єстества́ і, Сло́ву, всему́дре, слове́сні же і у́мні сопребива́я, от безслове́сія безслове́сні живу́щия свободи́л єси́.","Небе́сних ра́зум приї́м богослове́снійше, Бо́га Сло́ва пропові́дал єси́: в нача́лі бі Сло́во, і Сло́во бі к Своєму́ Роди́телю, і Бог бі Сло́во, благовіству́я, научи́л єси́.","Богородичен: Отрокови́ць боже́ственних лик, боже́ственнійше в жена́х Тя до́брую воспіва́ють, Богоро́дице Влади́чице, добро́тами укра́шену Божества́, добротвори́тельноє бо Сло́во па́че сло́ва родила́ єси́."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня, я́ко крин, Го́споди, язи́чеськая неплодя́щая це́рков прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Тро́йці яви́л єси́ богосло́вним язи́ком твої́м, ю́же па́че ума́ та́йну, Іоа́нне богоблаже́нне, в не́йже утверди́ся моє́ се́рдце.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Язи́к твой бисть Пи́сьменника трость, Всесвята́го Ду́ха, богопи́санно зна́менующий честно́є твоє́ і боже́ственноє Єва́нгеліє.","Му́дрости ти бе́здну поче́рпл єси́, всему́дре, возле́г богому́дренним дерзнове́нієм на Прему́дрости Істо́чниці, і Сего́ богопропові́дник бил єси́.","Богородичен: Єди́ну Ді́вствующую і Ма́тер чтим, я́ко спасе́нія Хода́таїцю би́вшу нам, Всенепоро́чная, і мир ізба́вльшую моли́твами Твої́ми."]},{"h":"Сідален, глас 8","ps":["Прему́дрости на пе́рси возле́г і ра́зуму су́щих научи́вся, боже́ственно возгремі́л єси́: в нача́лі бі Сло́во, до́брі написа́в пе́рвий безнача́льноє рождество́, і пропові́дал єси́ всім Сло́ва воплоще́ніє. Ті́мже і язи́ком, я́ко мре́жею, улови́в язи́ки, благода́тію Ду́ха ізуча́єши конці́ і просвіща́єши чудеси́, Богосло́ве апо́столе, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви не хода́тай, ні А́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Сло́во тя Богосло́ва досто́йно показа́, Того́ Божества́ тайнонаучи́в, преізя́щнійше, і є́же по челові́ку строє́нію научи́в неізрече́нному.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Ум боже́ствен і ді́вственно ті́ло стяжа́в, храм бил єси́ живи́й же і одушевле́нний, сла́вне, і жили́ще Всепі́тия Тро́йці свяще́ннійшеє.","Синовство́м Пречи́стия Ді́ви почествова́лся єси́, ді́вственниче блаже́нне, і брат показа́лся єси́ Ізбра́вшему тя і ученика́ Богосло́ва Соверши́вшему.","Богородичен: Ісціля́я Є́ви дре́внєє преступле́ніє, в Тя, Всенепоро́чную і Пречи́стую, всели́ся Пребоже́ственний, всего́ м'я челові́ка вообрази́ти па́дша."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо, Влади́ко, к Світонача́льнику, Отцю́ Твоєму́, от но́щі неві́дінія приведе́ніє і́мами.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Небе́сний ум, Богосло́ве, яви́лся єси́ благода́тію, весь світ бив є́же к Началосві́ту приближе́нієм і чи́стим твої́м зрі́нієм, є́же к Нему́, обожа́єм.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Умо́м чи́стим, і святи́ми устна́ми, богодохнове́нне, і пречи́стими усти́ твоє́ Єва́нгеліє пропові́дал єси́ і о́бщеє спасе́ніє всім ві́рним предложи́л єси́.","Со Христо́м живи́й от младе́нства, орга́н благода́ті от Него́ предложе́н бил єси́, богосло́вії ізобуча́єм і Тро́їчестій сла́ві па́че єстества́ науча́єм.","Богородичен: Глаго́ли Твоя́ помина́юще, Тя ни́ні блажи́м: Тобо́ю, Всенепоро́чная, блаже́нство неізрече́нноє і жизнь нестарі́ющуюся і́стинно прия́хом."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Ісу́с, Бог мой і Госпо́дь, твою́ чистоту́ приї́м і всесоверше́нную свя́тость, бра́та тя Богосло́ве, прия́т.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Вінча́в свя́то житіє́ твоє́, си́це упова́в, Му́дрости возле́гл єси́ на пе́рси, сла́вне, і благода́ть отту́ду ізвле́кл єси́.","Вели́кая і боже́ственная сія́нія богосло́вія твоєго́ всю просвіти́ша, сла́вне, вселе́нную і сві́том Трисо́лнечним озари́ша.","Богородичен: Не́бо простри́й во́лею, Не́бо земно́є іно́є распростре́ Тя, Богома́ти Чи́стая, і, із Тебе́ возсія́в яви́ся."]},{"h":"Кондак, глас 2","ps":["Вели́чія твоя́, ді́вственниче, кто пові́сть? То́чиши бо чудеса́, і ізлива́єши ісціле́нія, і мо́лишися о душа́х на́ших, я́ко Богосло́в і друг Христо́в."]},{"h":"Ікос","ps":["Висоти́ небе́сния уві́діти і мо́ря глубини́ іспита́ти де́рзостно єсть і непости́жно, я́коже бо зві́зди ісчи́слити і примо́рський песо́к невозмо́жно отню́д, си́це ніже́ я́же Богосло́вова рещи́ дово́льно: толи́ціми того́ вінці́ Христо́с, єго́же возлюби́, вінча́, Єму́же і на пе́рси возле́г і на Та́йній ве́чері с Ним яде́, я́ко Богосло́в і друг Христо́в."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть, Христо́с же простре́ богочести́вим отроко́м ро́су духо́вную, сий Благослове́н і Препросла́влен.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Боже́ственним сія́я світоли́тієм, Ду́ха Свята́го я́сно богосло́вил єси́, ісходя́ща із Безнача́льнаго Отця́ і почива́юща в Си́ні неотхо́дно, я́ко Єдиносу́щна.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","В тебі́, блаже́нне, положи́ пра́вди Со́лнце селе́ніє, не́бо приснодви́жимо тя соді́лавий і богосло́вним твої́м язи́ком пропові́дуємий Христо́с, возлю́бленне, препросла́вленний.","Глаго́л твої́х си́ла, боже́ственноє віща́ніє ізи́де, всеблаже́нне досточу́дне, і преми́рноє твоє́ Єва́нгеліє всю об'я́ше зе́млю догма́тов вели́чеством.","Богородичен: Пречи́стоє зача́тіє, нетлі́нно Рождество́ Ти Єди́на показа́ла єси́, Ді́ва преби́вши: Бо́га бо зачала́ єси́, над всі́ми Су́щаго, Чи́стая, Челові́ка би́вша, ві́рних на спасе́ніє і ізбавле́ніє."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Я́коже мо́лнія сві́тлая проходя́щи, вселе́нній, блаже́нне, яви́лся єси́, чистоти́ сві́тлостію, ді́вства же блиста́нієм, і благоче́стія догма́ти мир просвіща́я, возлю́бленне Христу́ Бо́гу.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Ті́ло, і ду́шу, і ум очи́стив, благовісти́л єси́ Небе́сноє Христо́во Єва́нгеліє, і, А́нгелом єдиножи́тель на Небесі́х бив, зове́ши ни́ні: благослові́те, вся діла́ Госпо́дня, Го́спода.","Столп сві́тел, возложе́ніє же боже́ственно Небе́снаго хра́ма бил єси́, і престо́л чу́вствія, і му́дрости прия́телище, богосло́вія орга́н, поя́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Да кля́тву пе́рвую істреби́ши, і сме́ртноє осужде́ніє дре́вле прама́тере, із Ді́ви Богома́тере Сло́ве Бо́жий роди́лся єси́, всім дарова́в безсме́ртіє неги́блемо."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю велича́єм.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Ни́ні не в гада́ніїх, но лице́м к лицю́, сла́дости пото́к зрі́ти удосто́їлся єси́, і реку́ ми́ра, і істо́чник безсме́ртія, і́мже ни́ні напая́єм, наслажда́єшися обоже́нія.","Приспів: Святи́й апо́столе і євангели́сте Іоа́нне, моли́ Бо́га о нас.","Назе́мноє проси́л єси́ сіда́лище прия́ти от Христа́, но Он тебі́ пе́рси Своя́ да́руєть, на ня́же возле́г, Богосло́ве, тве́рдим і пребива́ющим сіді́нієм до́брим обогати́лся єси́, апо́столов украше́ніє.","Му́дрости погаси́л єси́ е́ллинськия безбо́жноє, в нача́лі бі Сло́во, му́дре провіща́в, і к Бо́гу бі Сло́во, і і́стинно Бог бі Сло́во, І́мже вся би́ша, ви́димая же і неви́димая.","Богородичен: Я́ко у́тро обріла́ся єси́ у́треннєє в но́щі житія́, ді́вства заря́ми облиста́ющи, восто́к Со́лнця ми́сленнаго пра́вди нам я́вльшая, Богома́ти Всечи́стая."]},{"h":"Світилен","ps":["Я́ко душе́ю ді́вственна тя і ті́лом, блаже́нне, Сло́во ізбра́, Богосло́ве ді́вственниче, і Того́ Божества́ чу́дна показа́ писця́ і слугу́, і́же і от землі́ преста́вился єси́, не у́мер, но в Бо́зі жив і безсме́ртен пребива́я."]}],"notes":[]},{"u":"Канон апостолу Симону Зилоту, Кананіту","e":"Canon to the Apostle Simon the Zealot, the Canaanite","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Піснь возсле́м, лю́діє, чу́дному Бо́гу на́шему, свободи́вшему Ізра́їля от рабо́ти, піснь побі́дную пою́ще і вопію́ще: пої́м Тебі́, Єди́ному Влади́ці.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Во ви́шніх Влади́ці предстоя́, апо́столе чу́дне, тя просла́вльшему і ученика́ Себі́ сві́тло показа́вшему, просвіти́ ду́шу мою́, да воспою́ боже́ственную твою́ па́м'ять.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Вся́ко ізоби́ліє благи́х тебі́ Христо́с дарова́в, верх боже́ственних дарова́ній, апо́столе, показа́ тя, судо́м пра́ведним, богоявле́нне, пра́ведний єди́н.","Вседухо́вную зарю́ приї́м, апо́столе, соше́дшую на тя с небесе́, огнедохнове́н бил єси́, всю попаля́я пре́лесть многобо́жія.","Богородичен: Ти, моє́ ме́ртвенноє і тлі́нноє, безсме́ртноє і нетлі́нноє, Спа́се, показа́в, во утро́бу всели́лся єси́ Святи́я Ді́ви Пречи́стия неіскусобра́чно, вообрази́вся же в челові́чеськоє єстество́."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́ко Госпо́дь, і ність пра́веден, я́ко Бог наш, Єго́же поє́ть вся твар: ність пра́веден па́че Тебі́, Го́споди.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Боже́ственноє та́їнство воплоще́нія позна́л єси́ воі́стину, апо́столе Си́моне богоприя́тне, от Самаго́ Спа́са зарю́ приї́м преми́рную.","Сло́во Безнача́льноє і Присносу́щноє Своєго́ служи́теля тя, Си́моне чу́дне, блиста́нії сві́тлими бога́тно просвіти́ Боже́ственния благода́ті.","Богородичен: Сві́щник всезлати́й Тя проро́к прописа́, Богоро́дице, нося́щу Світ невече́рній, просвіща́ющаго мир луча́ми Божества́, Христа́ Бо́га на́шего."]},{"h":"Сідален, глас 3","ps":["Боже́ственнаго Ду́ха світозаре́нієм тьму разруши́л єси́ многобо́жія і ві́рних сердця́ просвіти́л єси́, воспі́в спаси́тельная повелі́нія, і упраздни́л єси́ е́ллинськия ба́сни, Си́моне сла́вне, Христа́ Бо́га моли́ дарова́ти нам ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Із гори́ приосіне́нния, Сло́ве, проро́к, єди́ния Богоро́диці, хотя́ща воплоти́тися богови́дно усмотри́ і со стра́хом славосло́в'яше си́лу Твою́.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Весь сокро́вище сий дарова́ній єва́нгельських, благода́ті іспо́лнен, світ ми́ра і соль вселе́нния, Си́моне всеблаже́нне, бил єси́.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Веще́й сту́днаго явле́нія отврати́лся єси́, невеще́ствен же Світ ви́діти сподо́бился єси́, Божества́ вид, приі́мшаго вещ челові́чества, досточу́дне.","Си́моне, учениче́ жи́зні нетлі́нния, умертви́ наш живу́щий гріх живоно́сною си́лою Животода́вця, єя́же прия́л єси́ ді́йствіє.","Богородичен: Ра́вен бив Отцю́ Твоєму́ по существу́, ра́вен челові́ком бил єси́ по єстеству́, от Пречи́стия Ді́ви на́шу, Влади́ко, плоть приє́мий."]},{"h":"Пісня 5","ps":["Ірмос: От но́щі неві́дінія богові́дінієм просвіти́вий конці́, просвіти́ м'я у́тром человіколю́бія Твоєго́, Го́споди.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Со огне́м, богови́дче, ти зри́мий язи́к Ду́ха прия́л єси́ усе́рдно, на го́рниці сідя́.","Я́ко висо́к сий, в преви́шних се́ліх живи́й, висо́кая і вели́кая уче́нія нам прине́сл єси́.","Богородичен: Зако́н пе́рвий, Ді́во, рождество́м Твої́м преста́, процвіте́ же благода́ть, і пра́вда возсія́."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том, я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Ре́вности тезоімени́ть нарече́нний, Си́моне досточу́дне, ре́вностію поревнова́л єси́ по Го́споді Бо́зі Вседержи́тели.","Тя Боже́ственних чуде́с самоді́лателя Спас показа́, дав власть тебі́ ді́йством Своєя́ бла́гости.","Богородичен: Да заградя́ться уста́ злочести́вих, Богоро́дицю Тя не му́дрствующих, Всенепоро́чная, і ли́ця во студ да облеку́ться."]},{"h":"Кондак, глас 2","ps":["Ізві́стно прему́дрости уче́нія в душа́х благоче́ствующих поло́жшаго во хвале́нії ублажі́м, я́ко богоглаго́ливаго всі Си́мона: престо́лу бо сла́ви ни́ні предстої́ть і со безпло́тними весели́ться, моля́ся непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Апо́стола па́м'ять всі, я́ко спаси́тельний день, восхва́лим ни́ні і благоче́стно ублажи́м: той бо всей вселе́нній, я́коже со́лнце, сія́єть, сві́та луча́ми всю мглу отгоня́я, і просвіща́єть любо́вію сего́ па́м'ять соверша́ющия і любе́зно почита́ющия. Ті́мже усе́рдно стеце́мся, воспіва́юще єго́: той бо Христу́ предстої́ть, моля́ся непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно, і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Стра́нну ре́вность, Си́моне, імі́я, тезоімени́ть ре́вности, блаже́нне, наре́клся єси́ і нрав, зва́нію согла́сен, стяжа́л єси́, — благослове́н єси́, Го́споди, — вопія́, — во ві́ки.","Вку́пі Сло́ву сликовству́я і собесі́дник Тому́ бив, Ца́рствія та́мо сопричасти́лся єси́, зови́й: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Богородичен: Ле́стію дре́вле благожре́бія пра́отці ізгна́ змій, Ти же сих, Ма́ти Бо́жия, воззвала́ єси́. Благослове́н, Пречи́стая, Плод Твоєго́ чре́ва."]},{"h":"Пісня 8","ps":["Ірмос: Мусикі́йським орга́ном согласу́ющим і лю́дем безчи́сленним, покланя́ющимся о́бразу в Деї́рі, три о́троци не повину́вшеся, Го́спода воспіва́ху і славосло́в'яху во вся ві́ки.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Я́ко красни́, Си́моне, твої́ но́ги, благолі́пен єсть і язи́к, глаго́лющ сла́ву Христо́ву, і научи́ зва́ти: Го́спода по́йте і превозносі́те во вся ві́ки.","Добро́тами укра́шен світолу́чними і чуде́с пуща́я сія́нія, позна́лся єси́, Си́моне, лю́дем сі́м'я благослове́нноє: Го́спода по́йте, діла́, і превозносі́те во вся ві́ки.","Богородичен: Ум не мо́жеть рождества́ Твоєго́, Богороди́тельнице, сказа́ти і ізрещи́ сло́во ізнемога́єть: Бо́га бо, заче́нши, родила́ єси́, Ді́во, Єго́же превозно́сим во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Чи́стую сла́вно почти́м, лю́діє, Богоро́дицю, огнь Божества́ приі́мшую во чре́ві неопа́льно, пі́сньми велича́єм.","Приспів: Святи́й апо́столе Си́моне, моли́ Бо́га о нас.","Явле́н бил єси́ конце́м, сві́том сія́я, і, огнь духо́вний приє́м, світови́ден показа́лся єси́, ті́мже тя велича́єм.","Весь Бо́гу возложе́н, Тому́ сраствори́лся єси́, Єго́же ни́ні моли́, богоявле́нне, о нас, ві́рою і любо́вію восхваля́ющих тя.","Богородичен: Спасе́нія всіх Хода́таїцю, я́вльшуюся челові́ком і мир просві́щшую сія́нії богови́дния чистоти́, в пі́сніх велича́єм."]},{"h":"Світилен","ps":["Тече́ніє кра́сних твої́х ног, Си́моне апо́столе, возврати́в, к ше́ствію небе́сному возше́л єси́, ра́дуяся, і, Тро́йце предста́в, во Отці́ ви́диши Си́на і Ду́ха Боже́ственнаго. Сего́ ра́ди ві́рою пресвяще́нную твою́ і боже́ственную пра́зднуєм па́м'ять."]}],"notes":[]},{"u":"Канон праведному Симеону Верхотурському","e":"Canon to the Righteous Symeon of Verkhoturye","secs":[{"h":"Глас 3. Пісня 1","ps":["Ірмос: Во́ди дре́вле ма́нієм Боже́ственним во єди́но со́нмище Совокупи́вий і разділи́вий мо́ре ізра́їльтеським лю́дем, Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Омраче́нний гріхми́, недоумі́ю, ка́ко по достоя́нію восхвали́ти тя, свя́те Симео́не, сія́юща по благода́ті Христо́вой по́двиг і чуде́с твої́х світлостьми́. Ти мі, благосе́рде, помози́, возсіява́я в душі́ моє́й світ, і́мже осіява́єшися, я́ко да поне́ єли́ко воспою́ в похвале́ніє твоє́ я́вльшаяся на тебі́ чу́дная діла́ Госпо́дня, воззива́юща всіх, пра́зднующих па́м'ять твою́, пі́ти Влади́ці Христу́: Сей Бог наш, ди́вний і сла́вимий во святи́х Свої́х, препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Благоче́стія любо́вію і спасе́нія об'я́т бив, ізбіга́яй того́ ра́ди треволне́ній жите́йських, удали́лся єси́, блаже́нне Симео́не, от ро́да твоєго́ і ма́нієм Боже́ственним ізведе́н бил єси́ в малонаселе́нную іногда́ страну́ Сиби́рськую, іді́же пресе́льник бив землі́ оте́чеськия, подо́бник яви́лся єси́ пра́отцю Авраа́му, і стяжа́в нрав єго́, в хи́жинах у́бо убо́гих вита́яй, я́коже он в ку́щах. Ду́шу же впери́в к Небесі́, в го́рній Сіо́н доброді́телей стезе́ю ходи́л єси́, веду́щею на Не́бо, всю жизнь твою́, во сла́ву Христа́, Спа́са всіх, ті споспішеству́юща. Єму́же вся сія́ науча́ють нас ра́достно днесь зва́ти: Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","По рожде́нію твоєму́, блаже́нне, бив о́трасль благонарочи́тих люде́й і сла́вних в наро́ді своє́м, єгда́ ма́нієм Боже́ственним Сиби́ри доше́л єси́, а́біє отгна́л єси́ от себе́ самомні́нія пре́лесть, і смире́нію подклони́л єси́ ви́ю, себі́ вміня́яй послі́днійша от всіх, та́же труди́ мно́гими ті́ло твоє́ удручи́л єси́, і укроти́л свирі́поє страсте́й мо́ре воздержа́нієм, і та́ко возше́л єси́ на висоту́ доброді́телей, укріпля́ющу тя Христу́, прославля́ємому твої́ми благи́ми ді́ли. Єму́же велегла́сно того́ ра́ди вопіє́м: Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","В нищеті́ пожи́л єси́ в Сиби́рстій страні́, блаже́нне Симео́не, і, я́ко от ко́рене благопло́дна плод благоцвіту́щ, доброді́тельми обогати́лся єси́. Ті́мже вельми́ украси́вша тя боже́ственними добро́тами, толи́ко нам вожделі́нними, і си́ми просла́вленна Влади́ку Христа́ пі́сньми славосло́вим, зову́ще: Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Столп доброді́телей непрело́жен і благоче́стія жили́ще бил єси́, блаже́нне, імі́яй основа́ніє у́бо тве́рдоє, Правосла́вную ві́ру, посо́біє же непобіди́мо, соді́йствующую ті си́лу Христо́ву. І ни́ні, імі́яй дерзнове́ніє ко Христу́, Спаси́телю всіх, моли́ Єго́ дарова́ти к прославле́нію і́мені Єго́ всім нам утвержде́ніє си́лою Єго́ в сей толи́ко спаси́тельній ві́рі, я́ко да всі єди́ними усти́ согла́сно зове́м Єму́: Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися.","Богородичен: Преблагослове́нна єси́, Богоро́дице Ді́во, я́ко родила́ єси́ Христа́, Спа́са на́шего, Єго́же славосло́вим, я́ко Єдиноро́днаго от Отця́, іспо́лнь благода́ті і і́стини, і Єму́же ви́ну взива́єм: Сей Бог наш препросла́влен єсть, Тому́ Єди́ному пої́м, я́ко просла́вися."]},{"h":"Пісня 3","ps":["Ірмос: Непло́дная душе́ і безча́дная, стяжи́ плод благосла́вний, веселя́щися возопи́й: утверди́хся Тобо́ю, Бо́же, ність свят і ність пра́веден па́че Тебі́, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Правосла́вною ві́рою утверди́вся, блаже́нне Симео́не, стяжа́л єси́ благосла́вний плод єя́, обогати́вий тя доброді́тельми, оба́че ніколи́же велему́дрствовал єси́ о себі́ і не дал єси́ человікоуби́йці іскони́ обуя́ти тя тщесла́вієм. Но ви́ну води́лся єси́ смиренному́дрієм, я́ко ви́діти тя при́сно всім а́ки би усво́їша себі́ піснь єди́наго от богому́дрих: утверди́хся Тобо́ю, Бо́же, ність свят і ність пра́веден па́че Тебі́, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","С нището́ю тіле́сною соєдини́в нищету́ духо́вную, я́ко ко́рень всіх благи́х, молчали́во і благоче́стно твою́ жизнь соверши́л єси́, блаже́нне Симео́не, і яви́л єси́ в себі́ плод благосла́вний Правосла́вния ві́ри, предукріпи́в пе́рвіє ті́ло твоє́ посто́м неосла́бним, та́же ду́шу твою́ храм Бо́жий пресвя́т соді́лав, боже́ственним хра́мом присідя́, внегда́ пі́тися та́мо свяще́нним піснопі́нієм, всім іму́щим єди́н сей ра́зум: ність свят і ність пра́веден па́че Тебі́, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Сугу́бо благоро́ден бил єси́, блаже́нне Симео́не, і ро́дом, і нра́ви: душі́ бо твоєя́ благоро́діє благоро́дія сви́ше добро́тами уясни́л єси́, Правосла́вія сві́том блиста́я, і по́стничеством, і цілому́дрієм, і смире́нієм, і терпі́нієм, і му́жеством на го́рдаго змі́я, єго́же си́ми низложи́л єси́, соді́йствующу ті Христу́, і та́ко дости́гл єси́ блаже́нних селе́ній святи́х, ї́хже во усті́х коєго́ждо ви́ну бисть піснь Це́ркве: утверди́хся Тобо́ю, Бо́же, ність свят і ність пра́веден па́че Тебі́, Го́споди.","Дре́во благосінноли́ственноє, насажде́нноє при ісхо́дищих вод, є́же дає́ть плоди́ во вре́м'я своє́, бил єси́, блаже́нне Симео́не. Ти бо, ізмла́да напоє́н бив вода́ми благоче́стія, ізрасти́л єси́ доброді́телей плоди́, благоприя́тни Бо́гу, дарова́вшему ті за та́я живо́т ві́чний, єго́же і нас сподо́би моли́твами твої́ми ко Го́споду, я́ко да і в гряду́щем ві́ці, я́коже днесь, воспіва́єм Єму́: ність свят і ність пра́веден па́че Тебі́, Го́споди.","Богородичен: Те́рніє і волчці́ гріхо́в непло́дни содіва́ють ду́ші на́ша, милосе́рдая Ма́ти Христа́ Бо́га на́шего, моли́ с пра́ведним Симео́ном Си́на Твоєго́ сотвори́ти ни́ву душ на́ших, во є́же приноси́ти єй плод благосла́вний і́стинния ві́ри, несумні́нния наде́жди і нелицемі́рния любве́, я́ко да ви́ну воспіва́єм Ро́ждшемуся от Тебе́: утверди́хомся Тобо́ю, Бо́же, ність свят і ність пра́веден па́че Тебі́, Го́споди."]},{"h":"Сідален, глас 4","ps":["Храм Бо́гу хотя́ яви́ти се́рдце твоє́, блаже́нне Симео́не, ізво́лил єси́ нелі́ностно присіща́ти хра́ми Госпо́дні в часи́ піснопі́ній. Отону́дуже і прия́л єси́ світ благода́ті Свята́го Ду́ха і яви́лся єси́ звізда́ многосві́тлая, сві́тлаго ра́ди житія́ твоєго́ і чистоти́ душе́вния же і тіле́сния, озаря́яй ві́рних собра́нія. Ті́мже пра́зднующе па́м'ять твою́, ра́достно восхваля́єм тя, блаже́нне.","Богородичен: Храм Сві́та Неізрече́ннаго била́ єси́, Всепі́тая Ді́во, вмі́щши во чре́ві Твоє́м просвіща́юща і освіща́юща ми́ра конці́ Христа́ Бо́га на́шего. І ни́ні моли́твами Твої́ми с пра́ведним Симео́ном соді́лай прича́стники Того́ Сві́та і нас, Богоро́дицю Тя воі́стину імену́ющих."]},{"h":"Пісня 4","ps":["Ірмос: Положи́л єси́ к нам тве́рдую любо́в, Го́споди, Єдиноро́днаго бо Твоєго́ Си́на за ни на смерть дал єси́. Ті́мже Ті зове́м, благодаря́ще: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Непости́дно бисть твоє́, блаже́нне, на си́лу і по́мощ Человіколю́бця Го́спода, преда́вша Си́на Своєго́ за ни на смерть, упова́ніє, і́мже укрі́пль ду́шу твою́, не ужа́слся єси́ вступи́ти в по́прищі по́двиг твої́х. Го́сподем бо помога́єм, пе́рвіє удержа́л єси́ в пості́ чре́во твоє́, та́же воздержа́нія росо́ю до́бльственні страсте́й пещ погаси́л єси́ і, та́ко мра́ка їх ізба́влься, просія́л єси́ безстра́стія сві́тлостію, се́ю же показа́л єси́ нам путь, веду́щий в жизнь і́стинную. Ті́мже, восхваля́юще тя, Го́споду, дарова́вшу ті си́лу і крі́пость, поє́м: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Насажде́н бив при вода́х воздержа́нія, блаже́нне, лоза́ яви́лся єси́ благора́сленна, благоче́стія гро́здіє предлага́ющая. К сим же показа́лся єси́ всім і о́браз трудолю́бія, подо́б'яся бо скинотво́рцю апо́столу, рука́ми свої́ми приобріта́вшему себе́ і су́щим с ним вся потре́бная к жи́зні вре́менній, упражня́лся єси́ в шве́нії оде́жд други́м і в ловле́нії риб на потре́бу к жи́зні, я́ко да не отяготи́ши ко́єго ли́бо пропита́нієм тебі́. Ті́мже укрі́пльшу тя о сем Христу́ Бо́гу поє́м: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Тружда́яся в шве́нії оде́жд, блаже́нне, к смотре́нію ми́сленних твоє́ худо́жество упра́вил єси́, помишля́я одія́ніє душі́ твоєя́, в нем же да вни́деши в черто́г Спа́сов. Та́кожде у́дицею ри́би лов'я́й, ви́ну мисль к Бо́гу імі́л єси́, блюди́й себе́, я́ко да не у́дицею гріха́ уловле́н бу́деши от вселука́ваго врага́ спасе́нія на́шего. І та́ко непрело́жен імі́яй по́мисл благоче́стія, устро́їл єси́ жизнь твою́ по Бо́зі, Христу́ ті споспішеству́ющу, Єму́же, сві́дуще сія́, велегла́сно поє́м: сла́ва си́лі Твоє́й, Го́споди.","Тезоіме́нно усли́шанію, і́мже преднаре́клся єси́ в креще́нії, блаже́нне, поуча́яся свято́му послуша́нію, са́мим ді́лом ісполни́тель о́наго бил єси́, нрав сообра́зний і́мені твоєму́ стяжа́в. Гото́в бо бил єси́ всегда́ послужи́ти всім, тре́бовавшим твоє́й, благосе́рде, по́мощі в житії́ твоє́м, і служи́л єси́, єли́ко ті мо́щно бисть, со усе́рдієм, уві́тлив ко всім весь явля́яся, і че́стен, і послушли́в. Разумі́юще у́бо, я́ко і сіє́ дарова́ніє ті даде́ся от Христа́ Бо́га, поє́м Єму́: сла́ва си́лі Твоє́й, Го́споди.","Богородичен: І́маши вся мощі́, є́же а́ще хо́щеши, всеблага́я Ма́ти Христа́ Бо́га на́шего, употребля́ющи Ма́тернєє дерзнове́ніє к Нему́. Ті́мже мо́лим Тя, моли́ с пра́ведним Симео́ном Си́на Твоєго́ дарова́ти нам си́лу і крі́пость ше́ствовати неукло́нно путе́м доброді́телей, я́ко да благода́рно ви́ну зове́м Ті: сла́ва, Влади́чице, всемо́щній си́лі Твоє́й."]},{"h":"Пісня 5","ps":["Ірмос: На землі́, Неви́димий, яви́лся єси́ і челові́ком во́лею сожи́л єси́, Непостижи́мий, і к Тебі́ у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Імі́яй в се́рдці своє́м о́браз восхище́на до тре́тіяго Небесе́ в рай апо́стола, ре́кша: ми юро́ди Христа́ ра́ди, ти, блаже́нне Симео́не, таково́є юро́дство во́лею восприя́л єси́ на ся, я́ко бо цвітни́к благоуха́ннійший і доброді́телей рай одушевле́н, воздержа́нієм процві́л єси́. Оба́че хотя́ утаї́тися от челові́к, юро́д бил єси́ ми́ру, сам ся неблагоро́ден сотво́р, скудоу́мія притворе́нії, Христу́ же прему́др бил єси́, соверша́я пресла́вная, безстра́стія дости́гл єси́ і́стиннаго. Ті́мже восхваля́юще тя, пі́сненно прославля́єм да́вшаго ті такову́ю му́дрость Христа́ Человіколю́бця.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Уму́ стра́сті твоя́ подчини́в, блаже́нне, духо́вную му́дрость стяжа́л єси́ і, се́ю управля́єм, нищету́ возлюби́л єси́, і воздержа́ніє, і чистоту́, і смиренному́дріє. І та́ко, си́лі Христо́вой ті соді́йствующей, на висоту́ доброді́телей восте́кл єси́, і́миже зря тя Христо́с обогати́вшася, человіколю́бне призрі́ на тя і сла́ви Ца́рства Небе́снаго показа́ тя прича́стника пресла́вна, Єго́же моли́ і нас сподо́бити о́бщники би́ти тоя́, я́ко да во ві́ки воспіва́єм Єго́, Человіколю́бця.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Юро́дствуяй Христа́ ра́ди, блаже́нне, і та́ко би́сер многоці́нний доброді́телей в селі́ се́рдця твоєго́ сокрове́нний імі́вий, я́ко безпло́тен, на землі́ пожи́л єси́ і соді́лался єси́ уго́дник Христу́, І́же тя, во возме́здіє того́, просла́ви нетлі́нієм і чудеси́ і поста́ви моли́твенника о лю́діх Свої́х. Сего́ ра́ди, ублажа́юще тя, велича́єм просла́вльшаго тя, Го́спода Человіколю́бця.","Ве́лію сотвори́л єсть Госпо́дь ми́лость Свою́ с на́ми, дарова́в нам тебе́, блаже́нне, істо́чника чуде́с і моли́твенника о нас. Ті́мже ублажа́юще тя днесь в па́м'яті твоє́й, сла́вим Да́вшаго ті і нам такову́ю благода́ть, вопію́ще: к Тебі́ у́тренююще, Го́споди, воспіва́єм Тя, Человіколю́бче.","Богородичен: Арха́нгельський глас вопіє́м Ті, Чи́стая Присноді́во: ра́дуйся, Благода́тная, я́ко родила́ єси́ Спаси́теля ми́ру, Христа́ Человіколю́бця."]},{"h":"Пісня 6","ps":["Ірмос: Глубина́ страсте́й воста́ на м'я і бу́ря проти́вних ві́тров, но, предвари́в м'я, Ти спаси́, Спа́се, і ізба́ви от тлі, я́ко спасл єси́ от зві́ря проро́ка.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Воздержа́нія вітри́лом управля́єм в житії́ твоє́м, блаже́нне, дости́гл єси́ в безстра́стія сла́вная приста́нища і та́ко спа́слся єси́ от тлі душепа́губних страсте́й. Госпо́дь же по преставле́нії твоє́м ізба́ви і ті́ло твоє́ от тлі і яви́ є нетлі́нно, а́ще і мно́га лі́та преби́сть в ні́дріх земни́х. І ни́ні моли́, благосе́рде, Го́спода, я́ко да спасе́ть і нас от вся́кия тлі, я́коже спасл єсть тебі́ от тлі і от зві́ря проро́ка.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Враг спасе́нія, іскуша́яй нас на гріхи́, сластьми́ пали́ть, но коль сія́ па́губна суть, су́щи тля сме́ртная, тлять бо добро́ту душі́ на́шея, тлять і здра́віє ті́ла і к сим гото́в'ять нам огнь неугаса́ющий і черв неумира́ющий. Блаже́нне Симео́не, предстоя́ с ли́ки А́нгелов і святи́х Бо́жиїх челові́ков Престо́лу Влади́ки, моли́ Єго́ с ни́ми, я́ко да ізба́вить от губи́тельства сласте́й і спасе́ть нас, вопію́щих Єму́: спаси́, Спа́се, і ізба́ви от тлі, я́ко спасл єси́ от зві́ря проро́ка.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Мно́го согріша́юще на вся́кий час і гріхми́ при́сно растліва́ємії, та́ко сля́чени єсьми́, я́ко не мощі́ нам восклони́ти глави́ і воззрі́ти когда́ к Небе́сній добро́ті, і бу́рею проти́вних ві́тров та́ко уноси́ми дале́че от путі́ доброді́телей і от стезі́ покая́нія, я́ко колеба́тися в нас упова́нію спасе́нія. Ти же, блаже́нне, предстоя́ ни́ні Всесвято́му, к Нему́же і бога́тноє стяжа́л єси́ дерзнове́ніє, моли́ ізба́вити ни от тлі гріхо́вния і бу́рю тіх проти́вних ві́тров утоли́ти, вопію́щия: спаси́, Спа́се, і ізба́ви от тлі, я́ко спасл єси́ от зві́ря проро́ка.","Блаже́н єси́, свя́те Симео́не, і добро́ тебе́ єсть, поне́же Госпо́дь, зря тя пра́ведна, вчини́ с ли́ки святи́х во оби́теліх Небе́сних, ізба́вль та́ко геє́нни, су́щия тлі ві́чния. Єя́же ізба́витися і нам моли́ Христа́ Бо́га, пою́щим Єму́: спаси́, Спа́се, і ізба́ви от тлі, я́ко спасл єси́ от зві́ря проро́ка.","Богородичен: Пречи́стая Влади́чице, Цари́це Небе́сная, стра́хом тлі ві́чния сме́рти содержи́мії, мо́лимтися, моли́ с пра́ведним Симео́ном Си́на Твоєго́, Христа́ Бо́га на́шего, я́ко да ізба́вить нас тоя́, вопію́щих: спаси́, Спа́се, і ізба́ви от тлі, я́ко спасл єси́ от зві́ря проро́ка."]},{"h":"Кондак на перенесення мощей, глас 4","ps":["Наста́ днесь всечестна́я па́м'ять но́ваго ціле́бника, пра́веднаго Симео́на, созива́єть же лю́діє в пречестни́й храм свята́го Бо́жия архієре́я Никола́я, іді́же, ра́достно соше́дшеся, благочести́вих мно́жества ве́село пра́зднують пренесе́ніє честни́х і многоціле́бних моще́й твої́х пра́здник. Ти бо яви́лся єси́ гра́ду на́шему і всей Сиби́ри врачевство́ безме́здноє, подава́я ісціле́ніє с ві́рою приходя́щим к тебі́, Симео́не всеблаже́нне. Но, я́ко імі́яй дерзнове́ніє ко Влади́ці Христу́, Того́ моли́ спасти́ град і лю́ди, моля́щіяся тебі́, па́че же хода́тай бу́ди ко Го́споду во дні наше́ствія печа́лі рабо́м твої́м, да зове́м ті: ра́дуйся, Сиби́рстій страні́ похвало́ і утвержде́ніє гра́ду на́шему."]},{"h":"Інший кондак, на прославлення, глас 2","ps":["Ми́ра су́єтнаго отве́рглся єси́, да бла́га ві́чния жи́зні наслі́диши, возлюби́в незло́біє і чистоту́ душі́ і ті́ла. Сниска́л єси́, є́же возлюби́л, свиді́тельствують бо о сем гроб і нетлі́ніє моще́й твої́х і благода́ть чудотворе́нія найпа́че. То́чиши бо цільби́ всім притека́ющим к тебі́ і непросвіще́нним, Симео́не блаже́нне, чудотво́рче преди́вний."]},{"h":"Ікос","ps":["Многоціле́бнаго сокро́вища, чудотво́рних моще́й твої́х, ні́дра подзе́мная не сокри́ша, пра́ведний Симео́не, но в обогаще́ніє ізда́ша та́я притека́ющим ві́рним і неві́рним. Ті́мже прийді́те всі і приймі́те бога́тий ток цільби́, ще́драго бо Влади́ки раб ще́дрить і дає́ть і єсть в подая́нії неоску́ден. Восхваля́юще у́бо в пі́сніх сицева́го засту́пника і благоді́теля на́шего, да зове́м єму́: ра́дуйся, Сиби́рстій страні́ похвало́ і утвержде́ніє гра́ду на́шему."]},{"h":"Пісня 7","ps":["Ірмос: я́коже дре́вле благочести́вия три о́троки ороси́л єси́ в пла́мені халде́йстім, сві́тлим Божества́ огне́м і нас озари́, благослове́н єси́, взива́ющия, Бо́же оте́ць на́ших.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Благоче́стіє тріє́х о́трок вавило́нських привлече́ к ним сві́тлий Божества́ огнь, су́щую благода́ть Бо́жию, сохра́ньшую їх в пла́мені халде́йстім невреди́ми. То́єжде благоче́стіє привлече́ і к твоєму́, блаже́нне, ті́лу благода́ть, сохра́ньшую є невреди́мо от тлі в ні́дріх земни́х. І ни́ні пребива́яй с на́ми, Симео́не, я́ко прича́стник Боже́ственнаго огня́, возжзи́ в нас огнь ре́вности по благоче́стію, я́ко да і ми, сим сохра́ньшеся пла́мене страсте́й, воспри́ймем піснь о́ніх отроко́в, є́же взива́ти Христу́ ви́ну: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Чу́дно бисть халде́єм виді́ніє тріє́х отроко́в, неопали́вшихся пла́менем огня́. Та́кожде удиви́шася христоимени́тії лю́діє і умили́шася се́рдцем, ви́дівше твой гроб, блаже́нне, восходя́щ от землі́. Єгда́ же узрі́ша в нем нетлі́нния мо́щі твоя́ і точа́ща чудеси́ пресла́вни Боже́ственною си́лою, в них обита́ющею, і па́че почуди́шася, і, стра́хом і ра́достію об'я́ти би́вше, со умиле́нієм славосло́в'яху Го́спода, ди́вная творя́щаго во святи́х Свої́х. Ті́мже і ми, торжеству́юще днесь па́м'ять твою́, свя́те, гла́сом тріє́х о́ніх отроко́в благода́рственно взива́єм Христу́, Спа́су всіх: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Воі́стину ве́ліє, я́коже то тріє́х отроко́во во Вавило́ні, та́кожде і твоє́, блаже́нне, бисть о́но чу́до, я́ко честни́я мо́щі твоя́ по толи́ціх лі́тіх обріто́шася ці́ли і неразруши́ми, сохраня́єми в землі́ Боже́ственною благода́тію і ізда́вшеся си́лою єя́ от нідр земни́х, я́ко світи́льник, єго́же Госпо́дь поста́ви не под спу́дом, но на сві́щниці, да сві́тить всім сія́нієм чуде́с, озари́ша і обогати́ша правосла́вних разумі́нієм боже́ственним. Уцілому́дрітеся ни́ні, вопію́щії, і возлюбі́те па́че всіх Го́спода, да благода́ть обря́щете ві́чную, єще́ же і подаю́щу всім ісціле́ніє, притека́ющим к тебі́. Тебі́ же і ми покланя́ющеся, ра́достно поє́м піснь тріє́х о́ніх отроко́в Христу́, сподо́бившу нас такови́я благода́ті: благослове́н єси́, Бо́же оте́ць на́ших.","Я́ко фі́нікс, процвіте́ ті́ло твоє́ нетлі́нієм, блаже́нне, і, я́ко кедр, і́же в Лива́ні, умно́жися чудеси́, принося́щи боже́ственную жизнь. Сего́ ра́ди Сиби́рськая страна́, іму́щи тя моли́твенника, я́ко боже́ственний зри́ться рай, цві́ти разли́чния принося́ще чуде́с. І́миже, я́ко дре́вле вавило́няне чу́дом тріє́х отроко́во вразумля́ємі би́ша в і́стинній сих ві́рі, та́ко лю́діє спаса́ємії при́сно утвержда́ються в і́стинній ві́рі Бо́жієй, вводя́щей в живо́т ві́чний, єго́же да́руєть Госпо́дь Свої́м уго́дником, благослове́н сий Бог оте́ць на́ших.","Богородичен: Зри́ши, Пресвята́я Ді́во, я́ко в пла́мені гріхо́внім ісчеза́ють дні́є на́ша. Моли́твами Твої́ми с пра́ведним Симео́ном сотвори́, я́ко да не погуби́ть сій пла́мень нас до конця́, но росо́ю сві́тлаго Боже́ственнаго огня́ уту́шен бу́деть. І ми та́ко, невреди́ми от пла́мене єго́ яви́вшеся, Пода́телю того́ огня́, Си́ну Твоєму́, ви́ну взива́єм: благослове́н єси́, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Нестерпи́мому огню́ соєдини́вшеся, богоче́стія предстоя́ще ю́ноши, пла́менем же неврежде́нні, боже́ственную піснь поя́ху: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Я́коже благочести́вії о́троци в пещі́ вавило́нстій пла́менем іногда́ неврежде́нні би́ша Боже́ственною си́лою, та́ко сподо́бившіїся по́мощі твоєя́, блаже́нне, спасе́ни би́ша от многоразли́чних зол, я́ко пла́менем огня́ їх обдержа́щих. Ті́мже обновля́ющіяся в душа́х ві́рних чудеса́ твоя́ днесь в па́м'яті твоє́й, я́коже чу́до в пещі́ вавило́нстій ю́ноши о́ни, пі́ти всіх науча́ють: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Богото́чний істо́чник, ороша́ющ стра́ждущих в пла́мені нестерпи́мих зол, Госпо́дь яви́ тя, блаже́нне, я́ко воі́стину сокро́вище дарова́ній, ми же моли́твами твої́ми сподобля́ємся би́ти невреди́ми от злих. От незави́стних бо вод духо́вния благода́ті всім с те́плою ві́рою прибега́ющим к тебі́ подає́ши благопотре́бная ко спасе́нію і та́ко твори́ши, я́ко да всі, ра́достно торжеству́юще па́м'ять твою́, согла́сно вопіє́м: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Чуде́с твої́х, блаже́нне, рі́ки ізлія́вшеся ісціле́ній, бе́здну тя яви́ша, точа́щу благода́ть Го́спода. Іні́ї бо стражда́ нестерпи́мою бо́лію во о́чію своє́ю, пе́рстію то́кмо от гро́ба твоєго́ обложи́вше я і о сем укріпи́вшеся, прозрі́ша, друзі́ї же прикоснове́нієм то́кмо к моще́м твої́м облегче́ніє в болі́зні получи́ша; пре́жде су́щії німі́ї глаго́ланіє прия́ша, печа́льнії крі́пкоє утіше́ніє, хромі́ї благотече́ніє, разсла́бленнії ісправле́ніє, боля́щії нога́ма здра́віє; та́кожде мно́гі утро́би непло́дни соді́лашася многоча́дни, пію́ще то́кмо во́ду от мі́ста явле́нія твої́х моще́й, мно́зі же єле́єм от канди́ла твоєго́ ісціли́шася от неісці́льних болі́зней. І всім вся́ко пролива́єши ту́чі врачева́ній, уставля́я пале́ніє неду́гов, і лю́ди, сих свобо́ждшіяся, устроя́єши піснопі́ти: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Вельми́ тя просла́ви Госпо́дь, блаже́нне, в чудесі́х, от любве́ бо і ві́ри свято́є то́кмо і́м'я твоє́ призива́ющії а́біє усли́шани бива́ють, я́коже пліне́ннії іногда́ пога́ними, і стра́ждущії от дух нечи́стих, і іні́ї мно́зі боля́щії, і ніколи́же ску́дні по́мощі твоєя́ оставля́ються. І не то́чію тща́щимся і́м'я твоє́ нариця́ти, но і о́браз твой любо́вію, я́же к тебі́, напису́ющим, вели́к помо́щник явля́єшися. К сим же і неві́дущим тя боля́щим, я́ко і во мно́гі стра́ни і ве́сі проізи́де і сли́шана бисть сла́ва і́мене твоєго́, в со́ніїх явля́яся, врачу́єши я. Ті́мже па́м'ять твою́ пра́зднующе, в прославле́ніє Го́спода, просла́вльшаго та́ко тя, велегла́сно взива́єм: благослові́те, вся діла́ Госпо́дня, Го́спода і превозносі́те во вся ві́ки.","Богородичен: о́брази нося́щи дре́вле Твоєго́ Рождества́, ю́ноши не опаля́єть, Ді́во, пещ, я́коже не опали́ утро́бу Твою́ Огнь Боже́ственний. Вся бо твори́ть Ісу́с, Син Твой, Бог і Челові́к, Єго́же превозно́сим во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Благослове́н Госпо́дь Бог Ізра́їлев, воздви́гнувий рог спасе́нія нам в дому́ Дави́да, о́трока Своєго́, милосе́рдія ра́ди ми́лости, в ни́хже посіти́ нас Восто́к с висоти́, і напра́вил ни єсть на путь ми́ра.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Благослове́н Госпо́дь Бог, яви́вий тя, блаже́нне, споспі́шника всем ко спасе́нію житіє́м твої́м і наста́вника сло́вом. Лі́ствиця бо небовосхо́дная житіє́ твоє́ бисть, сло́во же твоє́ благода́тію срастворе́но єсть, науча́юще трезве́нію душі́ і ті́ла і воздержа́нію по благоче́стію і та́ко направля́юще всіх на путь ми́ра.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Благослове́н Госпо́дь Бог, дарова́вий нам тебе́, блаже́нне, чудотво́рця преди́вна, ку́пно же і сті́ну, і предгра́діє от язикозло́бія і озлобле́нія заблу́ждших от і́стинния ві́ри. Ї́хже чудеси́ от моще́й твої́х дале́че отгна́л єси́ от о́бласти Верхоту́рськия, не терп'я́ рачи́телей єресе́й і хуле́нія іспо́лненних на Правосла́віє би́ти та́мо, іді́же яви́шася мо́щі твоя́: чу́дная бо зна́менія от сих, я́ко огнь паля́щ, яви́шася в посрамле́ніє єретико́м, нам же всім во утвержде́ніє на путь ми́ра.","Приспів: Святи́й пра́ведний Симео́не, моли́ Бо́га о нас.","Благослове́н Госпо́дь Бог, поста́вивий тя, блаже́нне, хода́тая на Небесі́ і моли́твенника о нас. А́ще бо і земля́ сокри́ла тя, но горе́ тя всі бога́тна і́мами предста́теля і моли́твенника к Бо́гу, любо́вію чту́щим тя, я́коже іногда́ моли́твами твої́ми спасл єси́ іни́я от потопле́нія, іни́я от о́гненнаго запале́нія, призива́ющия свято́є і́м'я твоє́ і моля́щіяся тебі́ о по́мощі, і іни́я от неізбі́жния сме́рті в болі́зні їх і та́ко всіх напра́вил єси́ на путь ми́ра.","Благослове́н Госпо́дь Бог, сподо́бивий прославле́ніє твоє́, блаже́нне, світоза́рноє і чудеса́ пресла́вная воспі́ти, єли́ко мо́щно єсть нам. Ти же, благосе́рде, не отста́ви по́мощі твоєя́ от нас, со умиле́нієм про́сим тя, і не пом'яни́ беззако́ній на́ших, но обрати́ся на ми́лость, і моли́ ми́лостиваго Бо́га дарова́ти мир ми́рові, і всім согріше́ній проще́ніє, і душа́м і тілесе́м здра́віє і напра́вити всіх на путь ми́ра.","Богородичен: Благослове́н Госпо́дь Бог, Тобо́ю, Пресвята́я Ді́во, посіти́вий нас Восто́к сви́ше, просвіти́ти во тьмі і сі́ні сідя́щия і напра́вити но́ги на́ша на путь ми́ра."]},{"h":"Світилен, глас 2","ps":["Сві́тло возсія́ днесь па́м'ять твоя́, блаже́нне Симео́не, луча́ми мно́го облиста́ющи твої́х доброді́тельних дія́ній і озаря́ющи ві́рних ра́зуми сві́том чуде́с твої́х. Сію́ у́бо пра́зднующе, ра́достно сла́вим тя і любо́вію ублажа́єм, уго́дниче Христа́, Бо́га на́шего, Єго́же моли́ ізба́вити ни от мра́ка гріхо́внаго, і просвіти́ти сві́том за́повідей, разори́ти же і всю мра́чную тьму напа́стей, нас облежа́щих, і облиста́ти весе́лієм сердця́, і спасти́ ду́ші на́ша.","Богородичен: Сві́та немерца́ющаго вмісти́лище яви́лася єси́, Пречи́стая Ді́во, носи́вши Христа́, Бо́га на́шего, І́же єсть Світ присносу́щний, просвіща́яй вся́каго челові́ка, гряду́щаго в мир. Ті́мже Тя по до́лгу ублажа́єм."]}],"notes":[]},{"u":"Канон благовірному великому князю Дмитру Донському","e":"Canon to the Right-Believing Grand Prince Demetrius of the Don","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́знима Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Заря́ пресві́тлая в рождестві́ твоє́м яви́лся єси́, свя́те Дими́тріє, Христу́ возлю́бленне, сро́дники же твоя́ рожде́нієм твої́м возвесели́л єси́.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Заря́ у́тренняя бил єси́, свя́те Дими́тріє, во́зраста о́трочеська достига́я, Христу́ моли́тви усе́рдния возноси́ти поуча́лся єси́.","Заря́ кра́сная яви́лся єси́ Оте́честву твоєму́, свя́те Дими́тріє, княже́ніє приї́м і в Бо́га богаті́я, в моли́тві і іспові́данії ві́ри Правосла́вния укрепля́лся єси́.","Богородичен: Отрокови́це Пречи́стая, ю́ния о́троки сохраня́й і во во́зраст прише́дшия наставля́й, святи́я на землі́ возраща́й."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Утіше́ніє бога́тоє і о́браз богому́дрий імі́л єси́, кня́же Дими́тріє, во отці́ твоє́м духо́внім, святи́телі Алексі́ї прему́дрім, ка́ко упра́вити Оте́чество твоє́.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Утіше́ніє оби́льноє прия́л єси́ в се́рдці твоє́м, свя́те Дими́тріє, послу́шав словеса́ богому́драго святи́теля, к му́жеству укрепля́вшаго тя.","Утіше́ніє ве́ліє імі́л єси́, богому́дре кня́же Дими́тріє, ви́дя мно́гія дру́ги твоя́ во бранеіх о Бо́зі гото́вия ві́рно сподвиза́тися ті.","Богородичен: Пресвята́я Ді́во, Богороди́тельнице, Ти му́дре лю́ди Твоя́ ко спасе́нію устроя́єши, соблюди́ і нас в по́двизіх благи́х."]},{"h":"Сідален, глас 4","ps":["Я́ко світи́льник сві́тел в житії́ своє́м лю́дем твої́м яви́лся єси́, богому́дре Дими́тріє, кня́же приснопа́м'ятне і боголюбе́зне. Не оста́ви нас, ме́ньших бра́тій свої́х, о Оте́честві на́шем моли́тв твої́х те́плих прося́щих.","Богородичен: При́зри на моли́тви на́ша, Ді́во Пресвята́я, по́мощ і спасе́ніє лю́дем Оте́чества на́шего подаю́щи."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Терпі́ніє ве́ліє показа́л єси́, Дими́тріє прему́дре, в княже́нії твоє́м, преді́ли землі́ твоєя́ укріпля́я і защища́я.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Терпі́ніє і му́дрость яви́л єси́, свя́те, в похо́діх твої́х на ага́ряни, с по́мощію Бо́жиєю побіжда́я сих.","Терпі́ніє мно́гоє імі́л єси́, богому́дре Дими́тріє, кня́зі Українськия с полки́ їх об'єдиня́я во єди́но во́їнство христолюби́воє.","Богородичен: Пресвята́я Богоро́дице, Ма́ти Пречи́стая, Си́на Твоєго́ при́сно моли́ о є́же возраста́ти і в си́лу Бо́жию прийти́ ізбра́нним Твої́м."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой світ, в мир прише́л єси́, світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Доброді́тельми богому́дрими богаті́я, Дими́тріє всече́стне, строї́тель сла́вний града Києва яви́лся єси́, ті́мже і лю́ди твоя́ возвесели́л єси́.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Доброді́тельми христия́нськими в житії́ твоє́м укріпля́яся, свя́те кня́же Дими́тріє, мно́гі хра́ми Бо́жії пречу́дния по градо́м княже́нія твоєго́ воздви́гл єси́.","В доброді́теліх возраста́я, Дими́тріє прему́дре, дом і кня́жество твоє́ до́брі упра́вил єси́, во Христі́ Спа́се обогаща́лся.","Богородичен: Ді́во Пренепоро́чная, Ма́ти Христа́ Бо́га, лю́ди і кня́зі Твоя́ в ми́рі соблюди́ і в доброді́теліх многоімени́тих возрасти́."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею Кро́вію.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Смиренному́дріє удоборазсуди́тельноє і любо́в ізря́дную к ві́рним лю́дем твої́м показа́л єси́, пресла́вне кня́же Дими́тріє, єгда́ ко бра́ні ве́лії на Мама́я ополчи́лся єси́ со сро́дники і дру́ги свої́ми.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Смиренному́дріє ве́ліє яви́л єси́, свя́те Дими́тріє, єгда́ к стопа́м Се́ргия преподо́бнаго припа́л єси́, того́ благослове́нія на по́двиг ра́тний іспроша́я.","Смиренному́дріє і послуша́ніє яви́л єси́ отцю́ твоєму́, Се́ргію вели́кому, єгда́ благослове́нієм того́ два і́нока боголюби́ва, Алекса́ндра і Андре́я, во во́їнство твоє́ прия́л єси́.","Богородичен: Ді́во Пренепоро́чная, Наде́ждо на́ша непости́дная, во дні іспита́ній і скорбе́й ве́ліїх не оста́ви моля́щихся Тебі́."]},{"h":"Кондак, глас 2","ps":["По́двиги твої́ми, свя́те Дими́тріє, страну́ на́шу Бог сохрани́, да́вий тебі́ си́лу непобіди́мую. І ни́ні, предста́телю крі́пкий, соблюда́й моли́твами святи́ми град твой Київ невреди́м от всіх наві́т вра́жиїх."]},{"h":"Ікос","ps":["Ізмла́да за́повідем Госпо́днім поуча́лся і любо́в Христо́ву в се́рдці своє́м стяжава́я, свя́те Дими́тріє, кня́же всече́стне, словесе́м Госпо́днім і наставле́нію святи́х оте́ць, Алексі́я і Се́ргия, внима́я, в му́жа соверше́нна дости́гл єси́, та́же побі́ду пресла́вну одержа́л єси́. І ни́ні, предста́телю крі́пкий, соблюда́й моли́твами святи́ми град твой Київ невреди́м от всіх наві́т вра́жиїх."]},{"h":"Пісня 7","ps":["Ірмос: В пе́щі авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че не́жели пла́менем опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","На ізбавле́ніє Бо́жиє упова́я, блаже́нне кня́же Дими́тріє, пред нача́лом бра́ні благослове́ніє отця́ твоєго́ Се́ргия прия́т і, по́двигом і́нока Алекса́ндра вдохновля́єм, в би́тву со враги́ твої́ми вступи́л єси́.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Ізбавле́нія от враг лю́тих не ча́ющи, стеня́ше земля́ от кро́ве во́єв твої́х пролива́ємия, сам же ти, кня́же Дими́тріє, в оде́жди во́їна препро́стаго с враго́м му́жественні сража́лся єси́.","Ізбавле́нія не жда́ху мно́зі пресла́внії кня́зіє і во́ї твої́, ду́ші полага́юще за дру́ги своя́ на по́лі Кулико́ве, воєво́да же Бренко́ Михаї́л под зна́менем Спа́совим за тя поги́бе.","Богородичен: Ізба́вительнице крі́пкая, Богороди́тельнице Пречи́стая, честно́ю іко́ною Твоє́ю, я́же Донська́я нарече́ся, укріпи́ла єси́ лю́ди Твоя́ в сме́ртній бра́ні вели́цій, зе́млю Українськую спаса́ющи."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р Данії́л, львов зія́нія в ро́ві затче́, о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Чу́до пресла́вноє бисть побі́да во́їнства Українськаго, тобо́ю, кня́же Дими́тріє, собра́ннаго, єгда́ полці́ князе́й Влади́мира і Дими́трія Воли́нськаго на орду́ ага́рянськую внеза́пу ізидо́ша і в бі́гство ту́ю обрати́ша.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","Чу́до непости́жно бисть, єгда́ земля́ Українськая поколеба́ся от шу́ма бі́гства ага́рянськаго. Ти же, сла́вне Дими́тріє, мно́гі ра́ни приє́м, на землі́ сей, я́ко мертв, лежа́л єси́.","Чу́до стра́шноє бисть, ве́черу доспе́вшу і би́тве ути́хшей, мно́гоє бо мно́жество во́їнства Українськаго о́стрієм меча́ падо́ша, ї́хже імена́ вели́кий а́вва Се́ргій, открове́нієм ди́вним, во оби́телі своє́й на моли́тві возноша́ше.","Богородичен: Чу́дноє зна́меніє попече́нія Твоєго́, Пречи́стая Ді́во Марі́є, о ро́ді українськім яви́вши в день пра́зднованія Рождества́ Твоєго́, пресла́вную побі́ду тому́ дарова́ла єси́."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся, Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","О, ка́ко пострада́ земля́ Українськая в би́тві вели́цій, я́ко мно́жество люде́й за Оте́чество ду́ші своя́ положи́ша, ти же, свя́те Дими́тріє, с моли́твою і любо́вію во днех мно́зіх тілеса́ їх землі́ предава́л єси́.","Приспів: Святи́й благові́рний кня́же Дими́тріє, моли́ Бо́га о нас.","О, ка́ко просла́вися і́м'я Бо́жиє в по́двизі твоє́м, кня́же Дими́тріє пречу́дне, в сла́вній побі́ді сей, є́юже лю́ди українськия і́га стра́шнаго свободи́л єси́, і, нарече́ніє Донська́го прия́в, моли́твенник при́сний о нас явля́єшися.","О, ка́ко вели́к бисть по́двиг сей в лю́діх твої́х, пречу́дне кня́же наш Дими́тріє, я́ко і на гряду́щая времена́ простре́ся сла́ва побі́ди христолюби́ваго во́їнства Українськаго на по́лі Кулико́ве.","Богородичен: О пречу́дная Влади́чице Богороди́тельнице, на путі́ люде́й Твої́х і вожде́й їх призира́ющи і тім побі́ду на супоста́ти да́рующи, прийми́ моли́тви недосто́йних раб Твої́х, к Тебі́ прибіга́ющих."]},{"h":"Світилен","ps":["Побі́ду ве́лію во і́м'я в Тро́йці сла́вимаго Бо́га, по сло́ву пресла́внаго Се́ргия, с во́ї твої́ми одержа́л єси́, богому́дре кня́же Дими́тріє. Тім тя, я́ко предста́теля пред Бо́гом, всі почита́єм.","Богородичен: Єди́наго от Тро́йці Бо́га в ложесна́х Твої́х носи́ла єси́, Богома́ти Пречи́стая. Сего́ Бо́га Сло́ва і Си́на Твоєго́ о лю́діх умоля́ющи, покри́й нас предста́тельством Твої́м, Всепі́тая."]}],"notes":[]},{"u":"Канон преподобному Корнилію, ігумену Комельському","e":"Canon to St Cornelius, Abbot of Komel","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Сло́во мі даждь, Сло́ве Бо́жий, Світода́вче Христе́, воспі́ти сві́тлоє і світоно́сноє житіє́ Твоєго́ уго́дника, преподо́бнаго Корни́лія. Моли́твами єго́ разори́ мрак се́рдця моєго́ і Твої́м сві́том душі́ озари́тися, молю́ся.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Влади́чнему любостра́нству, преподо́бне, подо́б'яся, сам стра́нствовати ізво́лил єси́. Ті́мже і Всеви́дящеє О́ко, ви́дів твоє́ благо́є ізволе́ніє, да́ром чуде́с обогати́ тя, Корни́ліє, я́ко пресла́вно.","Трисо́лнечним сія́нієм, Богому́дре, озаря́єм, зло́є, блаже́нне, бісо́в шата́ніє і вра́жия преще́нія ра́нами болі́зней, я́коже паучи́ну, разори́л єси́, Бо́жиїм Ду́хом разжига́єм, Корни́ліє блаже́нне.","Богородичен: Я́ко Бо́жия Ма́ти, дерзнове́ніє іму́щи к ро́ждшемуся із Тебе́ Єдиноро́дному Сло́ву, і Отцю́ Собезнача́льному, і Соєсте́ственному Ду́ху Свято́му, моля́щися не преста́й от бід спасти́, Всенепоро́чная, Тя, Богоро́дицю, сла́в'ящия."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі небеса́ ра́зумом і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят, па́че Тебе́, Єди́не Человіколю́бче.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Кто ізрещи́ мо́жеть зе́млен твоя́ болі́зні, о́тче, і по́двиги, ї́хже ра́ди досто́йну мзду стяжа́л єси́ от Бо́га? І бил єси́ прия́телище Боже́ственнаго Ду́ха, преподо́бен і і́стинен, пра́веден і непоро́чен.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Укрі́пль ум ра́зумом Боже́ственним, о́тче Корни́ліє, і прему́дростію духо́вною і сло́вом укра́шен, тім привле́кл єси́ мно́гих ду́ші во спасе́ніє, яви́в мона́хом ізві́стно житія́ прописа́ніє.","Зло́би нача́льник враг, хотя́ тебі́ па́кость сотвори́ти, преподо́бне Корни́ліє, лука́вих челові́к на тя вооружа́єть: тебі́ прирази́вся, постиді́ся, Христу́ бо тя соблюда́ющу.","Богородичен: Херуви́м і серафи́м преви́шши яви́лася єси́, Богоро́дице: Ти бо прия́ла єси́ невмісти́маго Бо́га во Твоє́м чре́ві, Нескве́рная. Ті́мже Тя, всі ві́рнії, пі́сньми, Чи́стая, ублажа́єм."]},{"h":"Сідален, глас 8","ps":["Христо́вою любо́вію связа́в твою́ ду́шу і поще́нія страда́ньми утверди́вся, зла́та світлі́йши, благоче́стієм облиста́л єси́ і, чи́стоє прия́телище бив Ду́ху, лука́вих духо́в тьму разгна́л єси́; тім собра́в і́ночествующих мно́жества, па́стир їм бил єси́ і світи́льник сві́тел, Корни́ліє преподо́бне. Моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́сто Творцю́, я́ко Неіскусому́жная Ма́ти Ізба́вителю, прия́телище я́ко су́щи Уті́шителя, Препі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і бісо́м ігра́лище, в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Сві́тлоє твоє́ житіє́ я́ко пра́вило ізві́стно вся́кия, о́тче, доброді́телі показа́ся в моли́твах і поще́ніїх, бді́ніїх же і мольба́х, я́же ко Христу́ Человіколю́бцю.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Сна твої́ма очи́ма не дал єси́, блаже́нне Корни́ліє, ні ві́ждома дрема́нія, до́ндеже сподо́бился єси́ пра́ведних селе́нія, є́же угото́ва Бог, преподо́бне, лю́б'ящим Єго́.","Стеня́, і пла́ча, і сі́туя, умиле́нієм і слеза́ми кроп'я́ зе́млю, при́сно, о́тче Богому́дре, моли́тву соверша́л єси́, до́ндеже обрі́л єси́ Боже́ственноє утіше́ніє во гра́ді Бо́жії і со всі́ми святи́ми, преподо́бне, всели́лся єси́.","Богородичен: Бо́га, із Тебе́ воплоще́ннаго непрело́жно, єдиносу́щна Отцю́, і Тебі́, ро́ждшей, ра́вна по челові́честву, моли́ проще́ніє согріше́ній і душа́м спасе́ніє пою́щим Тя ві́рою дарова́ти."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Погаси́в стра́сті росо́ю подвиго́в твої́х, о́тче блаже́нне, бога́тно возже́гл єси́ огне́м любве́ і ві́ри воздержа́нія світи́льник, і просвіще́ніє безстра́стія, і дне син яви́лся єси́.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Ісціле́ній тебі́ благода́ть Христо́с в неду́зіх разли́чних дарова́ і на ду́хи нечи́стия власть, му́дре: єстество́ бо, о́тче, побіди́в, па́че єстества́ дарова́ній сподо́бился єси́ Ду́ха.","Ра́йськия добро́ти жела́я, преподо́бне Корни́ліє, в слеза́х, і воздиха́ніїх, і бді́ніїх і моли́твах твою́ жизнь препроводи́л єси́ і сего́ ра́ди по сме́рті от Христа́ чудеси́ просла́вился єси́.","Богородичен: Тя сті́ну іму́щії і заступле́нієм Твої́м соблюда́ємії, Твоє́ю Боже́ственною сла́вою хва́лящеся, Тя ублажа́єм: Ти бо, Пречи́стая, душа́м на́шим істоча́єши весе́ліє і ра́дованіє."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Глави́ враго́в ми́сленних сокруши́ти, мо́лимся, і ви́димия под но́зі на́ша покори́ти, моли́ся, преподо́бне, чту́щему любо́вію святу́ю па́м'ять твою́.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Житія́ твоєго́ ісправле́нія і віща́нія, о́тче, всю обтеко́ша отню́д вселе́нную, і́бо в пресла́вную дости́гл єси́ висоту́: Бог бо тя просла́ви і сла́вна всім сотвори́.","Ни́щих строї́тель, вдов предста́тель, проми́сленник си́рих, печа́льних утіше́ніє, па́дших ісправле́ніє, оби́димих засту́пник скор бил єси́, твоєму́, о́тче, подо́б'яся учи́телю.","Богородичен: Вознесла́ єси́ воі́стину па́дшеє челові́чеськоє существо́, о́браз Боже́ственний і Отцю́ ра́венство іму́ща, ви́димаго Си́на неізмі́нна, Богома́ти, без сі́мене во чре́ві поноси́вши."]},{"h":"Кондак, глас 8","ps":["Го́сподеві, от Святи́я Ді́ви возсія́вшу ми́рові, і Тому́ ізмла́да, я́ко А́нгел, послужи́л єси́, блаже́нне, і си́лою Єго́ пусти́ню, я́ко град, сотвори́л єси́, мно́жество же учени́к в ней собра́л єси́, ї́хже Богодохнове́нними уче́ньми просвіти́л єси́. Тім вопіє́м ті: ра́дуйся, о́тче наш Корни́ліє, і́ноком Боже́ственноє удобре́ніє."]},{"h":"Ікос","ps":["Зва́нію Го́спода твоєго́ послі́довал єси́ прилі́жно, блаже́нне, вся, я́же в ми́рі кра́сная, Єго́ ра́ди преоби́дів. Ті́мже вопіє́м ті: ра́дуйся, я́ко, ізмла́да Христа́ возлюби́в, си́лою Єго́ претерпі́л єси́ пусти́нноє озлобле́ніє усе́рдно; ра́дуйся, я́ко Ви́шняго по́мощію бісо́вськую пре́лесть попра́л єси́; ра́дуйся, я́ко прече́стен храм Бо́жия Ма́тере воздви́гл єси́; ра́дуйся, я́ко в нем тобо́ю Бог прославля́ється; ра́дуйся, я́ко собра́л єси́ учени́к мно́жество; ра́дуйся, я́ко с ті́ми прилі́жно Го́сподеві рабо́тал єси́; ра́дуйся, я́ко удиви́л єси́ А́нгели житіє́м твої́м; ра́дуйся, я́ко тобо́ю челові́ци по́льзовашася; ра́дуйся, правосла́вному наро́ду похвала́; ра́дуйся, христолюби́вому во́їнству утвержде́ніє; ра́дуйся, я́ко моли́твами твої́ми сопроти́внії побіжда́ються; ра́дуйся, о́тче наш Корни́ліє, і́ноком Боже́ственноє удобре́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снисхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Істощи́в тул стріл, враг вселука́вий устраши́ти тя не возмо́же, си́лою бо Ви́шняго укріпля́єм і Того́ по́мощію вооружа́єм, преподо́бне, піл єси́: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Бу́дущия жи́зні взиска́в, сла́ву маловре́менную небре́гл єси́ і, в пусти́ню всели́вся, блаже́нне, со звірми́ жи́ти ізво́лил єси́, поя́: благослове́н єси́, Бо́же оте́ць на́ших.","Враг, прирази́вся тебі́, преподо́бне, разбо́йники на тя посила́єть, постиде́в же ся, душе́внаго твоєго́ хра́ма не поколеба́, утвержде́н бо бі на ка́мені.","Богородичен: Го́ру Тя проро́к Данії́л Боже́ственним Ду́хом нарече́, Ді́во, із нея́же ка́мень без рук отсіче́ся і сокруше́ніє соді́я істука́нній пре́лести."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель Богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Царю́ всіх і Бо́гу со святи́ми предстоя́, с ни́миже, Корни́ліє, моли́ся, во́їнству на́шему побі́ди на ва́рвари дарова́ти і гріхо́в оставле́ніє, твою́ па́м'ять почита́ющим і пою́щим ви́ну: свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Госпо́дніх за́повідей ізві́стен храни́тель бил єси́, раздробля́я а́лчущим хліб твой, преподо́бне, та́ющу гла́дом доброді́телей ду́шу мою́ наси́ти, блаже́нне, пою́ща любо́вію: свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Ва́рвар іногда́ наше́ствіє, і ко оби́телі твоє́й устреми́вшихся, Боже́ственною си́лою устраши́л єси́. І ни́ні на нас ми́сленних враг устремле́ніє моли́твами твої́ми разори́, пою́щих: свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Богородичен: К Богоро́диці все твоє́ упова́ніє імі́л єси́, Корни́ліє, і Тоя́ призива́нієм вра́жия сі́ті вся расто́ргл єси́ і лю́тих воста́ніє, с Не́юже, преподо́бне, моли́ся о і́же любо́вію честну́ю твою́ па́м'ять чту́щих і вопію́щих: свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем Не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","Бі́гая сла́ви от челові́к, в пусти́ню всели́лся єси́, вся уме́ти вміни́в, да Христа́ єди́наго приобря́щеши, Єго́же ра́ди пусти́нная озлобле́нія претерпі́л єси́, да тлі́нними нетлі́нная ізміни́ши, Корни́ліє.","Приспів: Преподо́бне о́тче Корни́ліє, моли́ Бо́га о нас.","От мі́ста отгони́ти тя враг покуша́вся, мона́хи на убіє́ніє твоє́ поощря́ше, Корни́ліє преподо́бне, я́же до́брі уче́нієм твої́м наказа́л єси́ і, я́коже твоя́ ча́да, при́сно тіх возлюби́л єси́.","Не забу́ди, посіща́я чад твої́х, Корни́ліє преподо́бне, к ра́ці моще́й твої́х притека́ющих і любо́вію па́м'ять твою́ торжеству́ющих, от всіх іскуше́ній вра́жиїх ізба́витися, всіх Влади́ці моли́ся, блаже́нне.","Богородичен: Зачала́ єси́, Ді́во, без сі́мене, вся́чеськая созда́вшаго Сло́во Бо́жиє, кромі́ хоті́нія пло́ті, і без істлі́нія родила́ єси́, без болі́зней ма́терських. Тім Тя, Богоро́дице, язи́ком і се́рдцем іспові́дающе, велича́єм."]},{"h":"Світилен","ps":["Стра́стнаго омраче́нія ду́шу очи́стив, преподо́бне, честни́м поще́нієм і моли́твами непреста́нними, зерца́ло бил єси́ Боже́ственних сія́ній, світи́льниче мона́хов, Корни́ліє Богому́дре."]}],"notes":[]},{"u":"Канон преподобному Никиті Стовпнику, Переяславському чудотворцю","e":"Canon to St Nikita the Stylite of Pereslavl, the Wonderworker","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Сві́том благода́ті озаря́єм, преподо́бне, ві́рою па́м'ять твою́ торжеству́ющия світови́дную тьми гріхо́вния моли́твами твої́ми ізба́ви, Ники́то пресла́вне.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","К Бо́гу вводя́щ несовра́тно ше́ствовал єси́ путь, ко гра́ду Небе́сному, Ники́то, дости́гл єси́, і́бо Святи́й наста́ви тя Дух, почива́яй в се́рдці твоє́м.","Вознося́щеє смире́ніє, Ники́то, імі́л єси́, тім мо́лимся тебі́: уще́дри, преподо́бне, смире́ніє на́ше і болі́зні вся облегчи́ серде́ць на́ших.","Богородичен: Ра́дости нам Хода́тайця, я́ко приє́мши ісполне́ніє всего́ Божества́, яви́лася єси́, Всенепоро́чная, тім всі Тебі́, — ра́дуйся, — А́нгелово согла́сно зове́м, Богора́дованная."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію, і си́лою, і бога́тством хва́лимся, но Тобо́ю, О́тчею Іпоста́сною Му́дростію, Христе́, ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Пре́жднєє весе́ліє ізміни́л єси́ бу́дущих ра́ди благи́х же́стостію, доброді́тельно пожи́в, блаже́нне, на істо́чниці в гора́х, я́ко вели́кий Ілия́, пребива́я.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Путь пра́вий, єго́же возжелі́в поще́нія ра́ди, удивле́нієм бра́шен тебі́ показа́ Бог, єго́же обрі́л єси́ безме́здно я́коже приста́нище, му́дре.","Коле́блемих разли́чними страстьми́ ко твоєму́ столпу́, Ники́то, приходя́щих, честни́м твої́м хода́тайством всіх нас посіти́, моля́ Человіколю́бця.","Богородичен: Тя Му́дрость Бо́жия всечестни́й орга́н обрі́тши, от Твої́х чи́стих крове́й воплоща́ється і по рождестві́ нетлі́нну показа́."]},{"h":"Ікос","ps":["А́ще і челові́к, о́тче, по єстеству́, но па́че єстества́ челові́чеськаго стяжа́л єси́, вся бо в ми́рі сла́дкая і кра́сная преоби́дів, послі́довал єси́ Христу́, ті́мже і от всіх сли́шиши: ра́дуйся, я́ко Пречи́стою наставля́єм, пусти́ню дости́гл єси́; ра́дуйся, я́ко в ней прече́стен храм Бо́жієй Ма́тері воздви́гл єси́; ра́дуйся, я́ко та́мо в нем Бог тобо́ю прославля́ється; ра́дуйся, я́ко вшел єси́ на столп, преподо́бне; ра́дуйся, я́ко плоть порабо́тил єси́ ду́ху; ра́дуйся, я́ко твоєму́ житію́ А́нгели удиви́шася; ра́дуйся, я́ко тобо́ю челові́ци по́льзовашася; ра́дуйся, я́ко чудеси́ удиви́вий вся; ра́дуйся, я́ко на Небесі́х предстоя́ Тро́йці, о нас мо́лишися; ра́дуйся, істо́чниче чудесе́м неісчерпа́ємий; ра́дуйся, Ники́то преподо́бне, моли́твенниче о душа́х на́ших."]},{"h":"Сідален, глас 5","ps":["Ті́лом возше́д на столп, ум же возви́сив на преми́рная, труди́ ко трудо́м прилага́єши, жела́я дости́гнути угото́ванних тебі́ благ на Небесі́х, ї́хже получи́в, помина́й нас, почита́ющих свяще́нную па́м'ять твою́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́ во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, Нетлі́нною Дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Столпу́, Богоно́се, согражда́єму непоколе́блемою душе́ю сам ся пре́дал єси́, бу́дущую жизнь предзря́, єя́же улучи́ти жела́я, я́ко храбр во́їн.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Ла́ври честни́я дости́гл єси́, му́дре, возви́сився смире́нієм, верхи́ де́монськия смири́л єси́ і в ней до́блествовал єси́, сла́ва мона́хов і утвержде́ніє.","Моли́твами і посто́м вооружи́вся і стра́хом себі́ умертви́в Госпо́днім, блаже́нне, отсту́пника ізсіка́єши, неви́димаго змі́я, о́тче, побі́дник бил єси́.","Весь Боже́ственним Ду́хом разже́н бив, о́тче, труди́ под'я́л єси́ на мно́га лі́та, в хліви́ні у́зці терп'я́, взиська́я Го́спода, благода́тію тя Боже́ственною укріпля́ющаго.","Богородичен: На престо́лі висо́ці стра́шно сідя́й на ма́тернюю руку́, Младе́нець бив, сіди́ть, низпа́дший о́браз возводя́ і обоже́ніє су́щим подава́я."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й: Ти бо, неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га, і родила́ єси́ Безлі́тнаго Си́на, всім, воспіва́ющим Тя, мир подава́ющая.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Ходи́л єси́, преподо́бне, по у́зькому путі́, Боже́ственними восхожде́нії се́рдця распространя́яся і прича́стієм обожа́яся, всему́дре. Тім бил єси́ мона́хом сві́тлость.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","О́ко очи́стившу у́мноє, преподо́бне, благода́ть даде́ся тебі́, а́ки проро́ку, є́же пре́дняя предзрі́ти і предглаго́лати я́ко су́щая да́льняя і безві́стная.","Болі́знь облегчи́ мі гріхо́в і скорбе́й, і преста́ви се́рдця моєго́ болі́зні, і согріше́ній разріше́ніє да́руй, Благоді́теля Бо́га імі́я, послу́шающаго честни́х твої́х моли́тв.","Богородичен: Ума́ моєго́ ісціли́ превраще́ніє, Пречи́стая, уврачу́й стра́сті душі́ моєя́ і лі́ностную тьму отжени́, я́ко да хвала́ми Тя при́сно ублажа́єм, Всенепоро́чная."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, Богому́дрії, Богома́тере, прийді́те, рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Умертви́л єси́ стра́сті тіле́сния, я́ко дре́во ви́діся високове́рхо, плоди́ чуде́с принося́, Ники́то Богоблаже́нне.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","І́же безчи́сленним болі́знем прибли́жихся, ті́лом не́мощен преби́в, преподо́бне. Тім зову́ ті ві́рою: болі́зні уста́ви се́рдця моєго́.","От душе́вних не́мощей, о́тче, коле́блемих, ві́рою тя призива́ющих ни́ні посіти́ моли́твами твої́ми, я́же к Бо́гу, я́ко да благоче́стно тя сла́вим.","Богородичен: Єди́на Помо́щнице, помози́ мі, погиба́ющу, і ру́ку мі простри́, і ко приста́нищу наведи́ покая́нія, Ді́во Богора́дованная."]},{"h":"Кондак, глас 8","ps":["Христа́ ра́ди от твої́х рабо́в ну́ждную смерть претерпі́л єси́ і віне́ць нетлі́нія от Него́ восприя́л єси́, приходя́щим же с ві́рою от честна́го твоєго́ гро́ба подає́ши цільби́, о Ники́то преподо́бне, моли́твенниче о душа́х на́ших."]},{"h":"Ікос","ps":["Земни́й А́нгел, Небе́сний челові́к бил єси́, преподо́бне, посто́м і бді́нієм ду́шу просвіти́в, алка́нієм, і жа́ждею, і на землі́ лега́нієм Бо́гу угоди́л єси́ і вся́ку доброді́тель мона́шеськаго житія́ іспра́вил єси́, к сим же і ну́ждную смерть от твої́х рабо́во восприї́м, возше́л єси́ к жела́ємому Христу́, ра́дуяся, о Ники́то преподо́бне, моли́твенниче о душа́х на́ших."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі Богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Се́рдце твоє́ Тро́їчеськоє жили́ще соді́лав, три крести́ і тя́жкая желі́за, Ники́то, на себі́ поне́с, от ни́хже Боже́ственною благода́тію цільби́ істека́ють на просвіще́ніє і очище́ніє ві́рно притека́ющим ті.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Душа́ твоя́ світозаре́нієм Боже́ственнаго Ду́ха сія́ющи при́сно, ду́ші ви́дяще притека́ющих ті ві́рою сві́тло, блаже́нне, проро́чеськими прорече́нії, тім тя ублажа́єм.","Неду́гов тружда́ющих, блаже́нне, ду́ші і тілеса́ твої́ми святи́ми моли́твами вско́рі ізміни́ і пі́ти сотвори́: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Богородичен: Непремі́ннаго ро́ждши, єди́на Богора́дованная, десни́цею Єго́, Чи́стая, преміни́ти мі ум на лу́чшеє молю́ Ті ся, лю́ті превраща́ємий жите́йськими упраждне́нії."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Стоя́ на столпі́ виспр, я́ко на сві́щниці свіща́, преподо́бне, світя́щи, всім ра́зуми ві́рним просвіща́я, пока́зовал єси́ до́брі словеси́ і дія́нії стезю́ живота́ і возводи́л єси́ сія́ Боже́ственним сми́слом к висоті́ безстра́стія.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Ум безстра́стієм очи́щ, бесі́довал єси́ ко Го́споду Вседержи́телю, от Него́же неізрече́нная, преподо́бне, навика́я, проро́чеськи предглаго́лал єси́, просвіща́я ду́ші, я́ко вели́кий, преблаже́нне, проро́к; тім тя согла́сно ві́рою воспіва́єм.","Найдо́ша мі ра́ни тя́жкия, і неду́зі ча́сто тружда́ють, тіх м'я ізміни́, о́тче, молю́ ті ся, я́ко от Бо́га приї́м, Ники́то, благода́ть ісціля́ти стра́сті і болі́зні облегча́ти.","Тро́їчен: Со всі́ми Го́рніми во́їнстви Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Неразді́льну, Несозда́нно Божество́, пісносло́в'яще: Свят, Свят, Свят, — возопіє́м ра́достно, — Єди́на Власть, Нача́ло і Ца́рство.","Богородичен: І́же всі́ми непристу́пен Сий Зижди́тель Го́рніми, Отрокови́це, чи́ньми, всели́вся в ложесна́ Твоя́, неопа́льну соблюде́ Тя і по рождестві́ нетлі́нну. Єму́же ни́ні при́сно поє́м: Го́спода воспіва́йте діла́ і превозносі́те Єго́ во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же Безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Воздвиза́я ру́ки твоя́ к Бо́гу, моли́лся єси́, кріп'я́ ум твой удержа́ти от страсте́й, а́ки А́нгел, в тілесі́, о́тче, ти бил єси́. Тім со А́нгели всегда́ на Небесі́х живе́ши, сла́вному престо́лу предстоя́, Сві́та невече́рняго ісполня́єм.","Приспів: Преподо́бне о́тче Ники́то, моли́ Бо́га о нас.","Я́ко на Небесі́, в хліви́ні у́зці пожи́л єси́, преподо́бне: тім ті умири́шася ди́внії зві́ріє, покори́вшему стра́сті тіле́сния і злостремле́нія, Ники́то преподо́бне. Сего́ ра́ди ві́рою тя почита́єм.","Твоя́ честни́я і святи́я мо́щі, во гро́бі лежа́ще, погружа́ють неду́ги, і попаля́ють толпи́ де́монськия всегда́, преподо́бне Ники́то, Боже́ственною благода́тію, і істоча́ють всім ісціле́нія, ві́рно тя блажа́щим.","Уже́ к Бо́гу приближа́яся я́сні і чи́сті, пом'яни́ ві́рою тя, Ники́то, помина́ющих, гріхо́в оставле́ніє нам іспроси́, і неду́гов всіх ізбавле́ніє, і Бо́жия Ца́рства селе́ніє.","Богородичен: Сві́том м'я озари́ Твої́м, Непоро́чная, ро́ждшая Світ непристу́пний, разжени́ о́блак страсте́й душі́ моєя́, і от тьми ізми́, молю́ Ті ся, і Боже́ственнаго спасе́нія сподо́би, Чи́стая, єди́на Присноді́ва."]},{"h":"Світилен","ps":["Вся житія́ оста́вль, Христа́ приобрі́л єси́, трудополо́жно пожи́в і смерть ну́ждную восприя́т; тім па́м'ять твою́, Ники́то, почита́єм.","Слава, і нині: Бо́га нам, Пречи́стая, родила́ єси́, і всі, прароди́тельния кля́тви ізба́вльшеся, воспіва́єм Тя, Препі́тая."]}],"notes":[]},{"u":"Канон преподобному Агапіту Печерському, лікарю безмездному","e":"Canon to St Agapitus of the Caves, the Unmercenary Physician","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Я́ко німа́го дре́вле прикоснове́нієм устро́їл єси́ пра́во глаго́лати, си́це і мні, Христе́, мой язи́к разріши́, ум отве́рзи, да принесу́ в па́м'ять уго́дника Твоєго́ хвале́ніє, любо́вію поя́.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Не могу́ воспі́ти я́сно благода́ті твоєя́, преподо́бне, а́ще не ти моли́твами твої́ми пода́си мні по́мощ, да просла́влю Влади́ку, да́вшаго тебі́ благода́ть ісціле́ній, во хвале́нії поя́.","По предуві́дінію воззва́н бил єси́, свя́те, вслід Влади́ки своєго́ ше́ствовати і, Тому́ послі́дуя, вся кра́сная ми́ра оста́вль, любо́вію прише́л єси́ к вели́кому Анто́нію і с ним пожи́л єси́, непреста́нноє хвале́ніє Бо́гу поя́.","Земно́му А́нгелу і Небе́сному челові́ку послі́дуя, і сам а́нгельськоє житіє́ стяжа́л єси́, о́тче преподо́бне. Тім твоя́ ісправле́нія почита́єм і прославля́єм всіх Влади́ку, о тебі́ піснь Єму́ пою́ще.","Богородичен: От земни́х і Небе́сних сил сла́вимая, Присноді́во, в дне́шній день хвале́ніє Тебі́ дерза́ющих приноси́ти, от всіх прило́гов сохраня́й, да ви́ну Тя воспоє́м, Обра́дованная."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Во мно́гих лі́тіх мно́жайшия проше́л єси́ труди́, Ага́пите, подвиза́яся во бді́нії і поще́нії, до́ндеже єдинонра́вен показа́лся єси́ наста́внику своєму́ і от него́ утверди́лся єси́ на ка́мені тве́рдаго житія́.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Нічто́же і́но, то́кмо нищету́ імі́я, обнища́вшему нас ра́ди Христу́ послі́довал єси́, о́тче, і, Того́ за́повіді храня́, служи́л єси́ больни́м, посіща́я, і упокоєва́я, і здра́віє тім моли́твою своє́ю подава́я.","С преподо́бним жи́тельствуя, стяжа́л єси́ преподо́бство, достохва́льне Ага́пите, і ісціле́нія даро́в сподо́бился єси́, я́ко моли́твою і зе́лієм сні́дним здра́віє подава́л єси́ боля́щим, ті́мже і врач наре́клся єси́ безме́здний.","Просла́вил єси́ Бо́га во удесі́х твої́х, преподо́бне, ті́мже і Бог тя просла́ви благода́тію ісціле́нія, і́мже і на́ша неду́ги уврачу́й душе́вния і тіле́сния, да утверді́мся на ка́мені іспові́данія Бо́жия.","Богородичен: Ізрасти́вшая живо́тноє дре́во, Того́ плодо́м нас, умерщвле́нних гріха́ми, оживи́ і да́руй нам, Ма́ти Чи́стая, крі́пкоє бла́гости Твоєя́ іспові́даніє."]},{"h":"Сідален, глас 4","ps":["Я́ко ту́не приє́мий от Бо́га дар ісціле́нія, стра́ждущим ісціле́ніє ту́не подає́ши, с ві́рою к тебі́ притека́ющим. Ті́мже і ми, кла́няющеся ра́ці моще́й твої́х, о́тче преподо́бне, про́сим прия́ти от Тебе́ неду́гом на́шим ісціле́ніє.","Богородичен: К Твоєму́ благоутро́бію в ско́рбіх притека́юще, мо́лимся, Всенепоро́чная: пода́ждь преподо́бнаго Твоєго́ ра́ди нам, неду́ги одержи́мим, ско́роє ісціле́ніє."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Бу́їя ми́ра сего́ Христо́с ізбра́, да прему́дрия посрами́ть, є́же і на тебі́ сби́стся, о́тче всеблаже́нне: благода́тію бо, а не хи́тростію прему́драго посрами́л єси́ врача́. Тім тя сла́вим, о Го́споді пра́зднующе.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Прельсти́ся, і́же пе́рвіє больни́х прельща́ше, ізвіща́я їм день і час сме́рти, єму́же ти поно́сив, преподо́бне, боля́щаго ісціли́л єси́ моли́твою і зе́лієм сні́дним, рек: даждь сла́ву Бо́гу, іму́щему ключ живота́ і сме́рті.","За́висти стріло́ю злочести́вий армени́н уя́звен, поноша́ше ті, свя́те, і, посла́в на смерть осужде́ннаго, повелі́ пред тобо́ю умертви́ти би́лієм смертоно́сним. Но ти сего́ моли́твою і зе́лієм ісціли́в, посрами́л єси́ єретика́, хотя́щаго тя посрами́ти.","Претика́ющемуся, да́нная ті благода́ть бисть паде́ніє, преблаже́нне, найпа́че бо на тя вооружи́вся злочести́вий армени́н, наусти́ да́ти тебі́ отра́ву, но ти, і сме́ртно іспи́в, невреди́м бил єси́, я́ко Бо́жия благода́ть сохрани́ тя к бо́льшему чудоде́йствію.","Богородичен: Ра́дуйся, сосу́де, носи́вший ми́ро, ісціли́вшеє род челові́чеський; я́дом м'я гріхо́вним умерщвле́нна оживи́, да про́чеє вре́м'я ціл поживу́, Тя, Ді́во, восхваля́я."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","От Бо́га благода́ть ісціле́нія приє́м, ісціли́л єси́ кня́зя, і́же а́ще і врачу́єм бі от армени́на, но не получа́ше отра́ди, твоєго́ же зе́лія вкуси́в, от неду́га ізба́вися.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Зрі́те, і́ночествующії, і доброді́тельному терпі́нію Богоно́снаго отця́ почуді́теся, ка́ко со отрече́нієм ми́ра во́лі своєя́ отрече́ся, і не ізи́де нікогда́же вні врат монасти́рських, є́же ви́дяще, сему́ поревну́йте.","Єди́ну любо́в ко всім імі́я, а не на лице́ зря, а́ще князь, а́ще прост к тебі́ прихожда́ше, преподо́бне, всім приходя́щим подава́л єси́ ісціле́ніє ту́не, єди́наго іща́ возме́здія от Бо́га.","Приє́м князь тобо́ю ісціле́ніє, всеблаже́нне, уразумі́, я́ко і́стинен раб Бо́жий єси́, і ви́діти тя жела́ше, ті́мже приї́де к тебі́ с дари́. Ти же, Єди́наго імі́я Бо́га, нічто́же от тіх даро́во восхоті́л єси́ прия́ти.","Богородичен: Хва́лим Тя, Пречи́стая Ді́во, я́ко отверза́єши нам две́рі ми́лости Твоєя́ і подає́ши всім незави́стний істо́чник ісціле́нія, от я́да гріхо́внаго ізбавля́ющий."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Вся тлі́нная ми́ра сего́ оста́вив, принесе́нноє зла́то ізве́ргл єси́, блаже́нне, пред врати́ ке́ллії своєя́, ізверга́я вку́пі любоіме́ннаго врага́ і стира́я душегу́бную того́ главу́.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Єди́н би́сер стяжа́в многоці́нний — Ісу́са, вся во уме́ти вміни́л єси́, свя́те, і тім купи́л єси́ себе́ селе́ніє в Небе́сних, є́же і ми получи́ти мо́лимся твої́ми, о́тче, моли́твами.","Мно́гими лі́ти постя́ся, ізнемо́гл єси́ ті́лом, преподо́бне, но ду́хом преби́л єси́ крі́пок, а́ки столп, вся наноси́мая терп'я́ і благодаря́ Бо́га, к Нему́ взива́л єси́: возведи́ от тлі живо́т мой, Многоми́лостиве.","Ті́лом болі́знуя, ду́хом бра́лся єси́ с злочести́вим армени́ном, і́же по тріє́х днех смерть тебі́ провозвіща́ше, сего́ ти, блаже́нне, одолі́л єси́, по тріє́х мі́сяціх отше́ствіє своє́ к Бо́гу возвіща́я.","Богородичен: К Твоєму́ приста́нищу прибіга́єм, Богоневі́стная Ді́во, / носи́ми жите́йських страсте́й волна́ми, / я́же Ти укроти́, да воспоє́м Тебі́: / ра́дуйся, приста́нище жите́йських пла́ваній."]},{"h":"Кондак, глас 6","ps":["Врач сий ізря́ден, чу́дне, явля́я несумне́нную твою́ ві́ру, облича́я же армени́ново неві́ріє і приводя́ єго́ к благоче́стію, себі́, близ сме́рти би́вшу, іспроси́л єси́ от Бо́га продолже́ніє живота́ і, сим чу́дом того́ уві́рив, приве́л єси́ Христо́ві, Єму́же во весе́лії предстоя́, моли́ся о нас, преподо́бне."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла А́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Дарова́ніє іми́й сви́ше неду́ги ісціля́ти, преподо́бне, боля́ща м'я небреже́нієм благи́х дія́ній уврачу́й, я́коже іногда́ принесе́ннаго в неду́зі уврачева́л єси́, моли́твою пода́в тому́ здра́віє і воспі́в: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Чудоді́йствуя святи́ми, тва́рі Созда́тель внеза́пу поста́ви тя здра́ва пред злочести́вим, і́же ви́дів, удиви́ся ско́рому твоєму́ от болі́зні в здра́віє преміне́нію. Му́чима м'я я́звами сту́дних діл, во ізміне́ніє ісправле́нія приведи́ твої́м, о́тче, сви́ше посіще́нієм, да пою́: благослове́н Бог оте́ць на́ших.","Болі́знь твоя́ і зе́ліє сні́дно прину́ди іспові́сти врача́ своє́ злоче́стіє, єго́же укори́л єси́, я́ко дерзну́ осяза́ти святу́ю твою́ ру́ку; се дерза́ю і аз к тебі́, о́тче, приступи́ти, но молю́ тя: не отри́ни м'я в ну́ждах мої́х, да пою́: благослове́н Бог оте́ць на́ших.","Трудо́в свої́х собра́в плоди́ с весе́лієм, а́ки добр земледі́лець, блаже́нною кончи́ною отше́л єси́ ко Го́рнім, прия́ти от Христа́ Бо́га дая́ніє і прия́л єси́ от Него́ неконча́ємую ра́дость, многочу́дне Ага́пите.","Богородичен: Во Твоє́ чре́во, Пренепоро́чная Ді́во, все́льшеєся Сло́во род челові́чеський в Небе́сних дво́ріх всели́. Умоли́ Того́ от тлі́нія м'я сея́ жи́зні пресели́ти, іді́же пото́ком сла́дости пита́ються святі́ї."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Врач бил єси́, о́тче, преди́вен, тіле́сния болі́зні врачу́я, в жи́зні сей живи́й ті́лом, по кончи́ні же твоє́й душе́вноє врачевство́ подава́я, я́коже сіє́ на армени́ні яви́л єси́, душі́ того́ дав цільбу́ і ко благоче́стію наказа́ніє.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Ви́дів тя, свя́те, армени́н во виді́нії чу́дном, іспові́да я́сно, я́ко свят єси́ і преподо́бен, і во ві́ру із неві́рія прело́жся, бисть і́нок твої́м направле́нієм, єго́же і нас не лиши́, пою́щих Го́спода во ві́ки.","Мно́гоє іми́й дарова́ніє, чудоді́йствовал єси́, ісціля́я боля́щих, ни́ні же, сподо́бивийся бо́льших дарова́ній, приложи́ пла́стир на ра́ни душі́ моєя́, да, получи́в осла́бу, превозношу́ Го́спода во ві́ки.","Із пламенови́днаго сві́та святи́м струї́ благода́ті подая́й, Христе́ Бо́же, паля́щия м'я стра́сті угаси́ щедро́т Твої́х росо́ю, разгоня́я тьму страсте́й. Се бо преподо́бний мо́лить с на́ми Тебі́, Го́спода, превозноси́маго от всіх во ві́ки.","Богородичен: Просвіти́вшая мир пречи́стим Рождество́м Твої́м, мрак злодія́нія моєго́ разжени́, ізлива́я мні на благотворе́ніє щедро́т Твої́х бога́тую ми́лость, да превозношу́ Тя, Ма́тер Бо́жию, во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни А́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с Небе́сними во́ї, Тя ублажа́єм.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Богодарова́ннаго ціле́бника лю́діє іму́ще, нікто́же да гряде́ть к су́єтним враче́м, і́же імі́ніє і здра́віє врежда́ють, но тре́буяй с ві́рою да гряде́ть к ра́ці Богоно́снаго отця́ і ту́не при́йметь ісціле́ніє.","Приспів: Преподо́бне о́тче наш Ага́пите, моли́ Бо́га о нас.","Ми́сленния ура́ниша ни разбо́йници ни́ні, неісці́льния у́бо іму́ще я́зви, несумні́нно к многочуде́сней припа́даєм ра́ці твоє́й, преподо́бне, і про́сим: пода́ждь цільбу́ тре́бующим, да всі тя хва́лим і велича́єм.","В Го́рняя душе́ю возше́д, во всесветя́щіяся черто́ги, оста́вил єси́, преблаже́нне, ра́ку моще́й свої́х в пеще́рі; і́мже покланя́ющеся, про́сим: пода́ждь неду́гом на́шим ісціле́ніє, да тя пі́сньми велича́єм.","По́мощі от тебе́ в не́мощіх прося́щих не пре́зри, но посіще́нієм твої́м даждь душе́вноє вку́пі і тіле́сноє ісціле́ніє, преблаже́нне Ага́пите, я́ко сий врач преізя́щний, да ви́ну тя велича́єм.","Богородичен: По́мощі от Тебе́ тре́бующих не пре́зри, Ді́во, но подава́й с ві́рою к Тебі́ притека́ющим: Ти бо єси́ істо́чник цільба́м неоску́ден, да Тя с Небе́сними си́лами при́сно велича́єм."]},{"h":"Світилен","ps":["Тлі́нная ми́ра оста́вив і нетлі́нная сподо́бився прия́ти, потща́лся єси́ ху́ждшая на лу́чшая преміни́ти, обнища́в любоіме́нієм стра́стним, но обогати́вся дарова́нієм ісціле́ній, і нам сія́ пода́й, днесь па́м'ять твою́ почита́ющим, всеблаже́нне Ага́пите.","Слава, і нині: Спа́сшіїся Тобо́ю, Чи́стую Тя Ма́тер іспові́дуєм: родила́ бо єси́ Того́, І́же Кресто́м разруши́ смерть, і, возше́д на висоту́, вся привлече́ к Себі́, і нам дарова́ ве́лію ми́лость."]}],"notes":[]},{"u":"Канон преподобному Мефодію, ігумену Пєшношському","e":"Canon to St Methodius, Abbot of Peshnosha","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Мо́ре огусти́л єси́, погрузи́вий со ору́жієм го́рдаго фарао́на, і лю́ди спасл єси́ немо́кренно, Го́споди, і ввел єси́ я в го́ру святи́ні, вопію́щия: пої́м Тебі́, Бо́гу на́шему, піснь побі́дную, я́ко просла́вися.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Мо́ря страстна́го пучи́ною обурева́єми, к Тебі́, Ісу́се Всеблаги́й, прибіга́юще, вопіє́м: от тимі́нія страсте́й нас ізба́ви, да в тишині́ ду́ха уго́днику Твоєму́ піснь хвале́бную принесе́м, єго́же чудеси́ сла́вно просла́вил єси́.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Мо́рю песо́к преді́л положи́вий Госпо́дь, тя ізбра́, преподо́бне о́тче Мефо́діє, от ю́ности Єму́ благоугожда́ти і сего́ ра́ди к вели́кому Се́ргію тя наста́ви, от него́же подвиго́м духо́вним научи́вся, в них сла́вно просла́вился єси́.","Мо́ря жите́йськаго треволне́ніє не потопи́ ладьи́ твоєя́, о́тче преподо́бне, но, ве́янієм Ду́ха Бо́жия управля́ємий, в ти́хоє приста́нище спасе́нія вшел єси́ і чудеси́ мно́гими от Го́спода просла́вился єси́.","Богородичен: Мо́ре слез іспроси́ нам, Влади́чице Преблага́я, у Ми́лостиваго Си́на Твоєго́ і Бо́га на́шего, да, і́ми угаси́вше пещ страсте́й, оми́єм скве́рну гріхо́вную душ на́ших і, спасе́ніє ві́чноє улучи́вше, воспої́м Христу́ піснь побі́дную, я́ко просла́вися."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́ся се́рдце моє́ во Го́споді, вознесе́ся рог мой в Бо́зі моє́м, разшири́шася на враги́ моя́ уста́ моя́, возвесели́хся о спасе́нії Твоє́м.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Утверди́л єси́ на ка́мені за́повідей Христо́вих се́рдце твоє́, преподо́бне о́тче Мефо́діє, у́зьким і приско́рбним путе́м ше́ствовал єси́, а́лчбою і жа́ждею плоть свою́ ізнуря́я блаже́ннаго ра́ди бу́дущаго поко́я, єго́же получи́в, весели́шися ві́чно со святи́ми.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Утвержде́нний благослове́нієм і моли́твою преподо́бнаго Се́ргия, в пусти́ню удали́лся єси́, о́тче Мефо́діє, і, в ней многолі́тні потруди́вся, оби́тель і́ноком возгради́л єси́, я́же спасе́нія хода́тайця бисть мно́гим.","Утвержда́л єси́ словеси́ твої́ми душеспаси́тельними бра́тію твою́, преподо́бне о́тче, і бил єси́ о́браз благоче́стія твої́м ученико́м, і́же, тобо́ю наставля́ємі, подража́телі би́ша твоєму́ житію́ свято́му і вку́пі с тобо́ю получи́ша спасе́ніє.","Богородичен: Утвержде́ніє на Тя наді́ющихся, Пресвята́я Богоро́дице Влади́чице, не посрами́ упова́нія на́шего, є́же по Бо́зі на Тя возлага́єм, но бу́ди нам Засту́пниця от нападе́ній дия́вольських, да, Тобо́ю помоществу́ємі, возвеселі́мся о спасе́нії на́шем."]},{"h":"Сідален, глас 4","ps":["Ско́рий помо́щник явля́єшися, преподо́бне о́тче Мефо́діє, с ві́рою в моли́твах тя призива́ющим: даде́ся бо тебі́ от Го́спода благода́ть неду́ги врачева́ти і ско́рби утоля́ти, оби́тель же твою́ святу́ю і по сме́рті назира́ти. Сего́ ра́ди с любо́вію почита́єм святу́ю і всера́достную па́м'ять твою́.","Богородичен: Ско́рий Твой покро́в, і по́мощ, і ми́лость покажи́ на раби́ Твоя́, і во́лни, Чи́стая, укроти́ су́єтних по́мислов, і па́дшую мою́ ду́шу возста́ви, Богоро́дице: вім бо, вім, Ді́во, я́ко мо́жеши, єли́ко хо́щеши."]},{"h":"Пісня 4","ps":["Ірмос: Проро́к Авваку́м у́мнима очи́ма прови́ді, Го́споди, прише́ствіє Твоє́, тім і вопія́ше: от ю́га при́йдеть Бог. Сла́ва си́лі Твоє́й, сла́ва снизхожде́нію Твоєму́.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Проро́ком Бо́жиїм Ілії́ і Крести́телю уподо́бился єси́, преподо́бне о́тче Мефо́діє, пусти́нний жи́тель бив, я́ко го́рлиця уєдине́нная, славосло́вія пі́сні єди́н Єди́ному Христу́ возноси́л єси́, воспіва́я Того́ Боже́ственноє снизхожде́ніє.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Проро́чеськи прови́дів преподо́бний Се́ргій імі́вшую устро́їтися в пусти́ні твоє́й оби́тель, прише́д к тебі́, о́тче Мефо́діє, ізбра́ і благослови́ мі́сто, на сооруже́ніє оби́телі удо́бноє, єго́же посіще́нієм обра́дован бив, вку́пі с ним воспіва́л єси́ Спа́сово Боже́ственноє снизхожде́ніє.","Проро́ка і царя́ Дави́да словесе́м послі́дуя, преподо́бне о́тче, жи́ти бра́тії вку́пі в оби́телі твоє́й законоположи́л єси́ і о́бщаго житія́ ревни́тель бил єси́ вели́кий, примі́р собо́ю всім подава́я і немо́лчно воспіва́я Христо́во Боже́ственноє снизхожде́ніє.","Богородичен: Проро́чеськая рече́нія на Тебі́ сби́шася, Ді́во Богоро́дице, Ти бо Сло́во Бо́жиє нетлі́нно воплоти́ла єси́, і Невмісти́маго во утро́бі Твоє́й ді́вственній неті́сно вмісти́ла єси́; тім Тя хвале́бно ублажа́єм і воспіва́єм спаси́тельноє Христо́во снизхожде́ніє."]},{"h":"Пісня 5","ps":["Ірмос: Го́споди Бо́же наш, мир даждь нам, Го́споди Бо́же наш, стяжи́ ни, Го́споди, ра́зві Тебе́, іно́го не ві́ми, І́м'я Твоє́ імену́єм.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Го́спода Бо́га освяти́л єси́ в душі́ твоє́й, преподо́бне о́тче, і же́ртвенник ми́сленний ду́шу твою́ соді́лал єси́, на не́мже же́ртву хвали́ Го́сподеві возноси́л єси́ во смире́нії ду́ха, немо́лчно призива́я І́м'я Бо́жиє спаси́тельноє.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Госпо́дні за́повіді животво́рния імі́л єси́ напи́санния на скрижа́ліх се́рдця твоєго́, преподо́бне о́тче, і пропові́дник бра́тії твоє́й бил єси́ єва́нгельськаго уче́нія, к Небесі́ возводя́щаго челові́ки, і́же, послу́шающе сего́, моли́твенно призива́ють Боже́ственноє Христо́во І́м'я.","Госпо́день раб бил єси́, Мефо́діє Богому́дре, день і нощ труди́вийся во сла́ву Бо́жию і на по́льзу душе́вную бли́жніх твої́х, ї́хже, я́ко сама́го себі́, возлюби́в усе́рдно, гла́дния пита́л єси́, ни́щія, сироти́ і вдови́ці удовля́л єси́, подвиза́я їх сла́вити о тебі́ Христо́во І́м'я.","Богородичен: Госпо́дня Ма́ти і Влади́чиця всея́ тва́рі яви́лася єси́, Богоро́дице Марі́є, нетлі́нно поро́ждши Єди́наго от Тро́йці, Бо́га Сло́ва, Єго́же моли́, Чи́стая, безслове́сних страсте́й нас ізба́вити, да в тишині́ безстра́стія се́рдцем і усти́ воспіва́єм Єго́ Свято́є І́м'я."]},{"h":"Пісня 6","ps":["Ірмос: Я́ко во́ди морськи́я, Человіколю́бче, волна́ми жите́йськими обурева́юся. Ті́мже, я́ко Іо́на, та́ко вопію́ Ті: возведи́ от тлі живо́т мой, Благоутро́бне Го́споди.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Я́ко кипари́с високове́рхий, возра́сл єси́, преподо́бне Мефо́діє, в пусти́ні непло́дній і плодоноше́нії духо́вними облагоуха́л єси́ Христо́ву Це́рков, оби́тель созда́в, і, в ней і́ноков мно́жество насели́в, ї́хже сло́вом і приме́ром твої́м ко Христу́ наста́вил єси́.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Я́ко при́сний учени́к преподо́бнаго Се́ргия, о́тче Мефо́діє, в устроє́нії оби́телі єму́ подража́л єси́ то́щно, слеза́ми моли́твенними па́че, не́же бога́тством земни́м, сію́ созида́я і при́сно моля́ся ко Го́споду, да от тлі гріхо́вния соблюде́ть ді́ло руку́ твоє́ю.","Я́ко воєво́да благоїску́сний, о́тче, во́їни духо́вния в бра́ніх со враги́ неви́димими к побі́дам руково́дствовал єси́: іскуше́н бо бив сам в по́двизіх пусти́нних, і іскуша́ємим удо́бно помога́л єси́ тлі гріхо́вния ізбіга́ти.","Богородичен: Я́ко воі́стину прибі́жище непости́дноє христия́ном, і щит, і покро́в, Ма́ти Бо́жия, воспіва́ющія Тя бід і скорбе́й свободи́: Тя бо, Єди́ну Благослове́нную в жена́х, Тобо́ю тлі гріхо́вния ізба́вльшіїся, немо́лчними хвала́ми ублажа́єм."]},{"h":"Кондак, глас 4","ps":["Послуша́нія до́брий рачи́тель бив, безпло́тния враги́ сле́зними моли́твами твої́ми крі́пко посрами́л єси́ і яви́лся єси́ Пресвяти́я Тро́йці жили́ще, Ю́же зря, блаже́нне, я́сно, Богому́дре Мефо́діє преподо́бне, чуде́с дар от Нея́ прия́л єси́. Ті́мже ісціля́єши с ві́рою приходя́щих неду́ги, утоля́єши ско́рби і мо́лишися непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Возлюби́в Христо́ви Боже́ственния за́повіді, возненави́діл єси́ ми́ра сего́ наслажде́ніє: плоть твою́, преподо́бне, во вре́менній жи́зні посто́м, бді́нієм і до́лу лега́нієм ізнури́л єси́ і в умерщвле́нном тілесі́ пі́сні немо́лчния, хвали́ і славосло́вія Трієди́ному Бо́гу приноси́л єси́, Мефо́діє о́тче наш, от нас же сли́шиши пі́сні такови́я: ра́дуйся, А́нгеле земни́й і челові́че Небе́сний, А́нгели удиви́вий житія́ твоєго́ чистото́ю і челові́ки научи́вий благоугожда́ти Бо́гу; ра́дуйся, світи́льниче немерца́ющий Боже́ственния благода́ті, в животі́ і по сме́рті сія́яй чудеси́ і си́ми озаря́яй ду́ші і сердця́ челові́чеськія. Ра́дуйся, при́сний наш засту́пниче і о душа́х на́ших ко Го́споду моли́твенниче: мо́лишися бо непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: Халде́йськая пещ, огне́м распала́ємая, ороша́шеся Ду́хом, Бо́жиїм предстоя́нієм, о́троци поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","В пещі́ іскуше́ній пусти́нних, о́тче Мефо́діє, благода́ть Госпо́дню, тя ороша́ющую, стяжа́л єси́, преподо́бне, ті́мже непобіди́м враго́м неви́димим показа́лся єси́ і вся прило́ги дия́вольськия крі́пко сокруши́л єси́, зови́й немо́лчно: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Поревнова́л єси́, преподо́бне о́тче, в житії́ твоє́м вели́ким во отці́х Анто́нію, Пахо́мію і Євфи́мію і, сих нра́ву і чистоті́ ви́ну поуча́яся, я́ко безпло́тен, на землі́ подвиза́лся єси́, сего́ ра́ди сосу́д ізбра́н Ду́ху Свято́му сподо́бился єси́ би́ти, Єго́же ді́йством чудеса́ пресла́вная соді́лал єси́ в житії́ і по сме́рті, о ни́хже ві́рнії благословля́ють Бо́га оте́ць на́ших.","Я́ко крин в пусти́ні, процві́л єси́, преподо́бне, і благоуха́нія Христо́ва іспо́лнил єси́ оте́чество твоє́ земно́є: сві́том до́брих діл твої́х озари́л єси́ сердца́ челові́ков, просвіща́я їх уче́нії твої́ми і науча́я пі́ти Го́сподеві: благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: В пещі́ халде́йськой та́їнство рождества́ Твоєго́ проразумева́я, Богоро́дице, ро́ждшимся от Тебе́ Іскупи́телем спасе́ніє обріто́хом і, подо́бно отроко́м Богосло́вцем, Си́ну Твоєму́ і Го́споду благода́рно зове́м: благослове́н єси́, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: А́нгели і Небеса́, на Престо́лі сла́ви сідя́щаго і я́ко Бо́га непреста́нно сла́вимаго, благослові́те, по́йте і превозносі́те Єго́ во ві́ки.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","А́нгели собесі́дники імі́л єси́, преподо́бне о́тче, і, си́ми укріпля́ємий, в пусти́ні безлю́дней многолі́тні преби́л єси́, єди́н Єди́ному Бо́гу рабо́тая. Сего́ ра́ди ни́ні со Безпло́тними водворя́єшися і поє́ши хвале́бную піснь Трієди́ному Бо́гу, Препе́тому і Превозноси́мому во ві́ки.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","А́нгела тя плотя́наго ві́ми, преподо́бне о́тче Мефо́діє: ангелоподо́бно бо на землі́ пожи́л єси́, і чистоту́ душі́ і ті́ла ре́вностно соблю́л єси́, ни́ні же водворя́єшися там, іді́же нічто́же скве́рно вхо́дить, і поє́ши немо́лчную піснь Бо́гу, Препе́тому і Превозноси́мому во ві́ки.","А́нгелов Творе́ць і всея́ тва́рі Созда́тель подви́жника доброді́телей яви́ тя, Мефо́діє, Єго́же си́лою укріпля́ємий, путе́м ті́сним ше́ствуя, дости́гл єси́ соверше́нства духо́внаго, Ца́рствіє же Христо́во унаслі́довал єси́, і со святи́ми поє́ши ра́достно: Го́спода по́йте і превозносі́те Єго́ во ві́ки.","Богородичен: А́нгельськоє цілова́ніє прино́сим Ті с любо́вію, Богоро́дице Чи́стая: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю. Ти же ра́дости нетлі́нния сподо́би Тя по до́лгу ублажа́ющия, Ро́ждшагося же от Тебе́ Го́спода пою́щия і превознося́щия во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Чу́жде ма́терем ді́вство, і стра́нно ді́вам діторожде́ніє: на Тебі́, Богоро́дице, обоя́ устро́їшася. Тім Тя, вся племена́ земна́я, непреста́нно велича́єм.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Чужд бил єси́, преподо́бне, превозноше́нія тщесла́внаго і в смире́нії глубо́цім житіє́ твоє́ препроводи́л єси́: о́браз смире́нія бил єси́ твої́м ученико́м, ї́хже при́сно поуча́л єси́ бі́гати душепа́губния горди́ні і во смире́нії ду́ха велича́ти Христа́ Жизнода́вця.","Приспів: Преподо́бне о́тче Мефо́діє, моли́ Бо́га о нас.","Чу́ждим прише́льцем і стра́нником убо́гим врата́ оби́телі твоєя́ незатворе́на би́ша, преподо́бне о́тче, но, Авраа́мово страннолю́біє стяжа́в, сія́ с любо́вію прийма́л і упокоєва́л єси́, зря в них Самого́ Христа́, Єго́же при́сно велича́л єси́.","Чужд пра́здности бил єси́, блаже́нне, но при́сно в моли́твах і труді́х тіле́сних подвиза́лся єси́, при сооруже́нії же оби́телі твоєя́ святи́я мно́гія вели́кия труди́ под'я́л єси́, си́лою Го́спода сил укріпля́ємий, Єго́же гла́си хвале́бними немо́лчно велича́л єси́.","Богородичен: Чу́ждих нас яви́, Влади́чице, вла́сті лю́таго мироде́ржця і в час кончи́ни на́шея на по́мощ ускори́ к нам, безпо́мощним: мно́го бо мо́жеть Ма́терняя моли́тва Твоя́ ко Го́споду, і трепе́щуть пред Тобо́ю ду́си тьми, ї́хже наси́лія нас ізба́ви, Всеблага́я, да Тя славосло́вії ра́достними велича́єм."]},{"h":"Світилен","ps":["Процві́л єси́ в по́стничеських по́двизіх, прехва́льне о́тче, і плод чудотворе́нія прине́сл єси́ Христо́вой Це́ркві, я́же і́мать тя, я́ко шипо́к благово́нен, ми́ром Ду́ха Свята́го напо́лненний, і́мже злово́ніє страсте́й упраздня́ється і ісціле́нія подаю́ться с ві́рою і любо́вію к тебі́ притека́ющим.","Богородичен: Тя пі́сньми немо́лчними ублажа́єм, Ді́во, я́ко от Тро́йці Єди́наго родила́ єси́, Богоро́дице, і яви́ла єси́ нам, потемне́нним, світ спасе́нія Боже́ственним і Пречи́стим Твої́м рождество́м."]}],"notes":[]},{"u":"Канон преподобному Кирилу, ігумену Білозерському","e":"Canon to St Cyril, Abbot of Beloozero","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Прекра́сная лоза́ виногра́да Христо́ва бил єси́, прему́дре Кири́лле, і грозд пресла́дкий яви́лся єси́, боже́ственную сла́дость ві́рним істоча́єши, блаже́нне, ку́пно же і ра́дованіє пою́щим тя.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","О́тче Кири́лле, не терп'я́, враг в нача́лі твоєго́ житія́ бу́рю воздви́г, дре́вом напра́сно хотя́ умертви́ти тебі́, а́ще не би боже́ственний глас возгласи́л тя, богому́дре.","Христа́, нас ра́ди смири́вшагося, подража́в і крест твой взем, преподо́бне, Того́ стопа́м послі́довал єси́, вся́ко мирсько́є пристра́стіє от тебе́ оттря́сл єси́, пребога́те.","Богородичен: Во двою́ єстеству́ Єди́н от Святи́я Тро́йці, от чи́стих крове́й Твої́х воплоти́ся, боголі́пно про́йде, і́же от Ада́ма спаса́я, Пречи́стая, бла́гостію."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","А́ще і в ми́рі су́щая, о́тче, преоби́діл єси́, но та́мо преми́рная і нетлі́нная стяжа́л єси́, іді́же глас пра́зднующих і ра́йськоє наслажде́ніє.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Льсти́вий враг хотя́ тебі́ па́кость сотвори́ти, преподо́бне, лука́вия челові́ки на тя вооружа́єть, тебі́ же прирази́вся, постиді́ся, Христу́ бо тя соблюда́ющу.","Уже́ пресла́вноє твоє́ житіє́ всю́ду, преподо́бне, прославля́ється, і чудеса́ твоя́ в конці́х пропові́даються, ті́мже, в па́м'ять твою́ соше́дшеся, почита́єм тя.","Богородичен: Пло́ті бре́нній соєдини́вся, І́же от Отця́ єдиноро́дний, в ложесна́х Твої́х, єди́н от двою́ про́йде без істлі́нія і соблюде́ невреди́мо ді́вство Твоє́, Всепі́тая."]},{"h":"Сідален, глас 4","ps":["Приспі́ пра́здник честна́го твоєго́ успе́нія, блаже́нне Кири́лле, просвіща́я всіх пра́зднующих па́м'ять твою́ сві́тло і Христа́ непреста́нно пі́сньми всегда́ сла́в'ящих.","Богородичен: І́же на престо́лі херуви́мстім сідя́й і в ні́дріх О́тчих водворя́яся я́ко на престо́лі святі́м сіди́ть Своє́м, Влади́чице, в ні́дріх Твої́х; вопло́щся бо Бог воі́стину, воцари́ся над всі́ми язи́ки, і разу́мно ни́ні пої́м Єму́, Єго́же умоли́ спасти́ся рабо́м Твої́м."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","О́тче преподо́бне, сна твої́ма очи́ма не дал єси́, ні ві́ждома дрема́нія, до́ндеже сподо́бился єси́ ви́діти пра́ведних селе́нія, я́же угото́ва Бог лю́б'ящим Єго́.","Уже́ не ктому́ вразі́, ніже́ челові́ци лука́вії, мо́гуть к тебі́ прибли́житися, Кири́лле преподо́бне: ви́діша бо благода́ть Бо́жию, тебі́ всегда́ соблюда́ющую.","Богородичен: На Тя упова́ніє моє́ возложи́х, Ма́ти Присноді́во, спасе́нія моєго́ і Тя Предста́тельницю імі́ю живота́ моєго́, тве́рду же і непоколеби́му."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Ізря́дно твоє́ житіє́ в послі́днія ро́ди і пресла́вно яви́ся, чудеса́ же твоя́ всю́ду ві́рним ізлія́шася. Ті́мже тя всі, о́тче, ублажа́єм.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Ра́йськия добро́ти жела́я, преподо́бне Кири́лле, і тоя́ ра́ди в слеза́х і воздиха́ніїх, бді́ніїх же і моли́твах твою́ жизнь препроводи́л єси́ і отту́ду наслі́дил єси́ жела́ємоє тебі́ блаже́нство.","Пресві́тлий твой пра́здник, о́тче, благоче́стно пра́зднующим подава́й сви́ше спасе́ніє і ізбавле́ніє, да тя всі, блаже́нне Кири́лле, непреста́нно воспіва́єм.","Богородичен: Лю́дем я́ко воі́стину ти́хоє приста́нище Христо́с Тебі́ яви́, ві́рою і любо́вію Тя, і́стинную Влади́чицю, Всенепоро́чная, от со́вісти чи́сти Богоро́дицю іспове́дающим."]},{"h":"Пісня 6","ps":["Ірмос: Ять бисть, но не удержа́н в пе́рсіх ки́тових Іо́на: Твой бо о́браз нося́, страда́вшаго і погребе́нію да́вшагося, я́ко от черто́га, от зві́ря ізи́де. Приглаша́ше же кустоді́ї: храня́щії су́єтная і ло́жная, ми́лость сію́ оста́вили єсте́.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Влади́ку ум поста́вил єси́ над страстьми́ тіле́сними, блаже́нне, ті́мже і Пресвята́го Ду́ха селе́ніє, богоно́се, бил єси́. Єго́же моли́ і нас свободи́ти от страсте́й, да тя почита́єм.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Я́ко побіди́во ві́ка сего́ кня́зя тьми, возше́л єси́ к небе́сним, побі́ди віне́ць нося́ от вседержи́тельния руки́ Бо́га на́шего, моли́ от бід спасти́ся тебі́ почита́ющим.","Плотсько́є мудрова́ніє, є́же на землі́, о́тче, умертви́л єси́ і на небесі́х житіє́ стяжа́л єси́, іді́же святи́х ду́си ра́дуються, пою́ще с тобо́ю Влади́ку твоєго́.","Богородичен: Пречи́стая Влади́чице, ро́ждшая челові́ком ко́рмчію і Го́спода, страсте́й мої́х непостоя́нноє і лю́тоє отжени́ смуще́ніє і тишину́ пода́ждь се́рдцю моєму́."]},{"h":"Кондак, глас 8","ps":["Я́ко преоби́дів тлі́нная і до́лу влеку́щая мудрова́нія, о́тче, к ви́шнему тече́нію ра́достно устреми́лся єси́, і та́мо со святи́ми Пресвяті́й Тро́йце предстоя́, моли́ от враг сохрани́тися ста́ду твоєму́, я́ко да, свято́є твоє́ успе́ніє пра́зднующе, вопіє́м: ра́дуйся, преблаже́нне Кири́лле, о́тче наш."]},{"h":"Ікос","ps":["А́ще і челові́к, о́тче, бил єси́ по єстеству́, но па́че челові́ка житіє́ соверши́л єси́: вся бо, я́же в ми́рі сла́дкая і кра́сная, преоби́дів, послі́довал єси́ Христу́. Ті́мже і от всіх сли́шиши: ра́дуйся, я́ко, Пречи́стою наставля́єм, пусти́ню дости́гл єси́; ра́дуйся, я́ко в той прече́стен храм Бо́жії Ма́тері воздви́гнувий; ра́дуйся, я́ко в нем Бог прославля́ється; ра́дуйся, собра́вий та́мо учени́к мно́жество; ра́дуйся, я́ко с ті́ми прилі́жно Го́сподеві рабо́тал єси́; ра́дуйся, удиви́вий а́нгели житіє́м твої́м; ра́дуйся, я́ко тобо́ю челові́ци по́льзовашася; ра́дуйся, і́же чудеси́ всіх удиви́вий; ра́дуйся, преше́дий от земни́х на небе́сная; ра́дуйся, я́ко, Тро́йце предстоя́, о нас мо́лишися; ра́дуйся, істо́чниче чуде́с неісчерпа́ємий; ра́дуйся, ві́рних плі́нник ізба́вителю; ра́дуйся, преблаже́нне Кири́лле, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла а́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Очи́стив от страсте́й, преподо́бне о́тче, ум твой і Вседержи́телю с преподо́бних ли́ки і пра́ведних предстоя́, всегда́ вопіє́ши: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Врачь преізря́дний ми́ру яви́лся єси́, блаже́нне, ісціля́я всіх, ві́рою притека́ющих ко хра́му твоєму́ свято́му і Христу́ от душі́ вопію́щих непреста́нно: благослове́н Бог оте́ць на́ших.","Посто́м і воздержа́нієм лице́ твоє́ украси́л єси́, преподо́бне, світлі́йши найпа́че яви́лся єси́ многоразли́чними бра́шни пита́ющихся. Ті́мже і Христу́ вопіє́ши: благослове́н Бог оте́ць на́ших.","Богородичен: Тя, Пресвята́я Ма́ти Присноді́во, позна́хом, земні́ї, спасе́ніє, і́бо в ні́дріх Отця́ неразлу́чно живи́й із Тебе́ воплоща́ється. Ті́мже благослове́нна єси́ в род і род."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Гроб, іді́же положено́ бисть честно́є ті́ло твоє́, преподо́бне, освяти́ всіх, к нему́ притека́ющих, істо́чник ісціле́нія істоча́я от душі́ Христу́ вопію́щим і превознося́щим Єго́ во ві́ки.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Во вре́м'я гла́да, раздробля́я, преподо́бне, ни́щим хліб твой, тіх а́лчбу уста́вил єси́, і мене́, та́ющаго гла́дом, боже́ственних дія́ній напита́й: да возмогу́ і аз со всі́ми пі́ти Го́спода во вся ві́ки.","І́же с тобо́ю ученици́ твої́, уче́нію твоєму́ повину́ющеся, преподо́бне, земна́я оста́вльше, во слід тебе́ к небе́сним прейдо́ша, і с тобо́ю пою́ть Христу́, і превозно́сять Єго́ во ві́ки.","Богородичен: В рождестві́ болі́зні ізбіжа́ла єси́, Пречи́стая, і, ро́ждши, па́ки Ді́вою пребила́ єси́: вся бо твори́ть Ісу́с, Бог і Челові́к, Єго́же превозно́сим во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї, Тя ублажа́єм.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Житія́ сего́ непостоя́нную пучи́ну нем'яте́жно преше́л єси́, преподо́бне, ко́рмчію Ма́тер Бо́жию імі́я, на сіє́ наставля́ющую тя. Ті́мже і ко приста́нищем приста́л єси́ а́нгельськаго пребива́нія.","Приспів: Преподо́бне о́тче Крири́лле, моли́ Бо́га о нас.","Я́ко зрі́лая і чисті́йшая пшени́ця, кромі́ всіх зло́бних пле́вел, в небе́сних жи́тницях соблю́лся єси́, преподо́бне, хліб сла́дкий жела́я принести́ся небе́сному Царю́, Єго́же ра́ди вся в ми́рі преоби́діл єси́.","Вели́ким отце́м, дре́вле в пості́х і по́двизіх просія́вшим, подо́б'яся, о́тче, вся дні жи́зні твоєя́ в слеза́х і труді́х препроводи́л єси́, до́ндеже дости́гл єси́ блаже́нную кончи́ну, ю́же і они́ наслі́доваша.","Богородичен: Си́на Безлі́тна, от Отця́ возсія́вша, Ти, во утро́бі несказа́нно заче́нши, родила́ єси́, Богома́ти Чи́стая Ді́во, моли́ непреста́нно о рабі́х Твої́х Того́, я́ко Человіколю́бця Бо́га, спасти́ род наш."]},{"h":"Світилен","ps":["Пречестну́ю і свяще́нную па́м'ять твою́ соверша́ющих, преподо́бне Кири́лле, і мно́гія труди́ твоя́ пою́щих, не преста́й, моля́ Ізба́вителя от напа́стей ізбавля́ти нас і селе́нію святи́х сподо́бити.","Богородичен: Почита́ють Рождество́ Твоє́ безпло́тних чи́ни, ра́дости бо земни́я Ти єди́на іспо́лнила єси́. Ті́мже Тя, Всенепоро́чная, ві́рнії, сла́вим, пі́сньми славосло́в'яще: Світ бо су́щим во тьмі возсія́ла єси́ і Со́лнце незаходя́щеє."]}],"notes":[]},{"u":"Канон преподобному Варлааму Хутинському","e":"Canon to St Barlaam of Khutyn","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Гряді́те, лю́діє, пої́м піснь Христу́ Бо́гу, разді́льшему мо́ре і наста́вльшему лю́ди, я́же ізведе́ із рабо́ти Єги́петськия, я́ко просла́вися.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","От Сві́та Світ, Христе́ мой, от Отця́ пре́жде вік рожде́йся, сий в нача́лі со Отце́м і Ду́хом, согріше́ній мрак душі́ моєя́ отгна́в, озари́ ум мой, молю́ся, да возмогу́ пі́ти Варлаа́ма, Твоєго́ уго́дника.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","От ко́рене блага́го блажа́йшая о́трасль прозя́бл єси́, земни́х маловре́меннаго житія́ ізбі́гл єси́. Тім, ни́ні чистоти́ віне́ць приє́мля, со а́нгели Христу́ воспіва́єши: пої́м Го́сподеві, я́ко просла́вися.","Земна́я і мимотеку́щая, я́ко уме́ти, вміни́в, Христа́ єди́наго приобрі́л єси́, Єго́же сою́зом любве́ уязви́в ду́шу твою́, і Того́ потща́лся єси́ обрісти́ ненасища́ємия добро́ти.","Богородичен: Усли́ша Є́ва прама́ти: в печа́ліх роди́ши ча́да. Ти же, чи́стая Ді́во, усли́шала єси́: Госпо́дь с Тобо́ю, ра́дуйся! — І ра́дованним гла́сом, Богоневі́сто, печа́ль прама́тере потреби́ла єси́."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́, возвесели́бося дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден, па́че Тебі́, Го́споди.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","По апо́столу, о́тче, ви́шніх іща́, і мудрова́ніє імі́я є́же к Бо́гу, вся, я́же на землі́, оста́вил єси́ і па́че єстества́ добро́ти сподо́бился єси́.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Сві́том Боже́ственним осія́єм о нем, і путь, к жи́зні веду́щ, позна́л єси́, о́тче наш Варлаа́ме, і равноа́нгельнаго ра́ди житія́ чудотво́рець наре́клся єси́.","Зако́ни пита́яся всіх Творця́ і Влади́ки, ті́мже і невече́рнім облистава́єм Сві́том, сві́тлоє со́лнце яви́лся єси́ і прему́дрости сокро́вищем, мир обогаща́я.","Богородичен: Во іни́х жена́х ма́ти, до́ндеже ді́ва, не позна́ся, ні ма́ти по рождестві́ ді́вствовати сподо́бися, на Тебі́ же, Ді́во Богома́ти, обоє́ сби́стся. Тім весе́лієм ду́ха воспіва́ю: ність непоро́чни, па́че Тебе́, Влади́чице."]},{"h":"Сідален, глас 8","ps":["Красоти́ мирськи́я от млади́х ногте́й, преподо́бне, возненави́дів, єди́наго же Христа́ от се́рдця возлюби́л єси́ і Тому́ все́ю душе́ю приліпи́лся єси́; я́ко безпло́тен, на землі́ пожи́в с пло́тію, сла́ву же мимотеку́щую і бога́тство в нічто́же вміни́в, небе́сноє бога́тство восприя́л єси́ і сла́ву ві́чную. Ті́мже ублажа́єм свято́є твоє́ успе́ніє і, в нем торжеству́юще, вопіє́м ті: богому́дре о́тче наш Варлаа́ме, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́сто Творця́, я́ко неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Всепі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і де́моном ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́. Світоно́сная, Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Пою́ Тя, слу́хом бо, Го́споди, усли́шах і ужасо́хся: до мене́ бо і́деши, мене́ іща́, заблу́ждшаго. Тім мно́гоє Твоє́ снизхожде́ніє, є́же на м'я, прославля́ю, Многоми́лостиве.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Я́ко в порфи́ру, і виссо́н, і в ца́рськую багряни́цю оді́яся тобо́ю вели́кая Українськая земля́: днесь у́бо, сві́тло торжеству́ющи, весели́ться, Варлаа́ме, імі́ющи тя в себі́, я́ко неістощи́моє сокро́вище.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Ми́ра любве́ отре́кся, дости́гл єси́ го́рній Ієрусали́м, іді́же Христо́с со Отце́м і Ду́хом, і, вінце́в от Него́ сподо́бився, со безпло́тними ли́ки поє́ши, приє́мля Єго́ сія́ніє.","А́ще у́бо, о́тче, ті́сний і болі́зненний путь ше́ствовал єси́ в житії́, но оба́че нетлі́нную жизнь наслі́довал єси́, отону́дними сві́тлостьми бога́тно просвіща́яся, богоблаже́нне Варлаа́ме.","Богородичен: І́стинно Тя сінь свиді́тельствова многоразли́чними о́брази, я́ві показу́ющи Воплоще́ннаго із Тебе́, Єди́наго Тро́йці, Пречи́стая, неізмі́нно, Богома́ти Влади́чице, і мир обнови́вша."]},{"h":"Пісня 5","ps":["Ірмос: Сві́та Пода́телю і віко́в Тво́рче, Го́споди, во сві́ті Твої́х повелі́ній наста́ви нас: ра́зві бо Тебе́, іно́го Бо́га не зна́єм.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Яре́м Госпо́день от ю́ности, му́дре, взем, послі́довал єси́ Христу́ скорбми́ і слеза́ми, преподо́бне, ми́сленно о́ко к Нему́ імі́я, до́ндеже і святи́х селе́ній дости́гл єси́, обрі́т поко́їще Го́рняго гра́да.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Страсте́й отгна́в мглу я́ві заря́ми, о́тче, доброді́телей, просвіще́ніє Ду́ха в се́рдці приє́м, Варлаа́ме, і́мже попали́л єси́ вся де́монськая ополче́нія і по́стничеським лико́м причта́лся єси́.","Насажде́н во дво́ріх Госпо́дніх і в дому́ Бо́га на́шего процві́л єси́. Приє́м небе́сноє сі́м'я, богодухнове́нне, серде́чною браздо́ю клас стори́чествующ прине́сл єси́, ті́мже обогати́лся єси́ вінце́м чуде́с.","Богородичен: Упра́ви ум мой, Влади́чице, тружда́ющийся в пучи́ні скорбе́й і потопля́єм наше́ствієм тлітво́рних страсте́й, і спаси́, Богоро́дице, к Тебі́ прибега́ющия: іни́я бо Помо́щници, Чи́стая, ра́зві Тебе́, не зна́єм."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Мо́ре жите́йськоє, любому́дрієм іспита́в і разумі́в су́єтно су́що і я́ко вско́рі погиба́ющо, отве́ргл єси́, єди́ному приліпи́лся єси́ Христу́. Єго́же ра́ди і тяготу́ дневну́ю поне́сл єси́, о всіх Тому́ восхожде́нія в се́рдці своє́м полага́я.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Ві́трилом окриля́єм воздержа́нія, і отту́ду дости́гл єси́ в приста́нище благоути́шноє, поще́нієм пита́я ду́шу твою́, преподо́бне, і сві́тлу всіх Творцю́ предста́вил єси́ ю. Ті́мже і Христо́с прия́т ю, я́ко світоза́рную звізду́, і своєя́ сла́ви соприча́стну соді́ла.","А́нгельськая во́їнства су́щему во пло́ті житію́ твоєму́ удиви́шася, о́тче Варлаа́ме, бу́ри бо страсте́й отбі́гл і соверше́ннаго ра́ди житія́, ві́трилом воздержа́нія дости́гл єси́ в благоути́шноє приста́нище Христо́во.","Богородичен: Обетша́вшия ни го́рким дре́вле дре́ва вкуше́нієм і па́дшия поползнове́нієм, Пречи́стая, обнови́ла єси́, Зижди́теля ро́ждши, Сло́во Іпоста́сноє, Ді́во Ма́ти Влади́чице."]},{"h":"Кондак, глас 8","ps":["Я́коже други́й Ілия́, о́тче, дождь с небесе́ свел єси́: он у́бо огнь сведе́ і царя́ удиви́, ти же лю́ди твоя́ возвесели́л єси́ і торжествова́ти устро́їл єси́. Вели́кий бо Но́вград вельми́ тобо́ю хва́литься, імі́я мо́щі твоя́ в себі́, єго́же сохраня́й от враг непоколеби́ма, да зове́м ті: ра́дуйся, преподо́бне Варлаа́ме, о́тче наш."]},{"h":"Ікос","ps":["А́ще і челові́к єстество́м бил єси́, преподо́бне о́тче, но Ви́шняго Ієрусали́ма яви́лся єси́ согра́жданин і, челові́к у́бо єстество́м, безпло́тних че́сти сподо́бился єси́. Ті́мже і са́мая, зря́ще, чудеса́ похва́льная удивля́ють нас і науча́ють зва́ти тебі́ такова́я: ра́дуйся, благочести́ва отця́ о́трасле; ра́дуйся, ма́тере благогові́йния ві́тве; ра́дуйся, смире́нія висото́; ра́дуйся, я́ко к позна́нію Бо́га вся приводя́; ра́дуйся, я́ко мно́га чудеса́ о Христі́ сотвори́л єси́; ра́дуйся, цілому́дрія сто́лпе, і́мже де́монськая свирі́пства іскорени́шася; ра́дуйся, світи́льниче многосві́тлий; ра́дуйся, я́ко ув'яди́л єси́ плотська́я мудрова́нія; ра́дуйся, я́ко дождь моли́твою свел єси́ і, па́ки наводне́нію би́вшу, моли́твою водото́чния о́блаки востя́гл єси́; ра́дуйся, Вели́каго Нова́града похвала́ і утвержде́ніє, єго́же і сохрани́ от враг непоколеби́ма до конця́, да зове́м ті: ра́дуйся, преподо́бне Варлаа́ме, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: О́бразу злато́му на по́лі Деї́рі служи́му, тріє́ Твої́ о́троци небрего́ша безбо́жнаго велі́нія, посреді́ же огня́ вве́ржені, ороша́ємі, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Зі́льним поще́нієм, я́ко благово́нною пи́щею, пита́я ду́шу твою́, преподо́бне Варлаа́ме, ті́мже і Трисо́лнечному Божеству́ предстоя́, со а́нгели поє́ши: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Облиста́л єси́ я́коже невече́рнєє со́лнце, оте́чество твоє́ просвіща́я, преподо́бне Варлаа́ме, тьми избавля́я страсте́й, і на нас наві́тующих сові́ти разори́, от враг непреткнове́нним би́ти нам, пою́щим: благослове́н Бог оте́ць на́ших.","Я́ко на боже́ственную доброді́телей лі́ствицю воздержа́нієм, о́тче, возше́д, у́мними очеси́ Христа́ Царя́ ви́діл єси́, оби́льною десни́цею по числу́ доброді́телей, Варлаа́ме, дарова́нія даю́ща от душі́ вопію́щим: благослове́н Бог оте́ць на́ших.","Дрема́нія отню́д і сна твої́м очесе́м не дал єси́, до́ндеже возме́здіє от Христа́ трудо́в обрі́л єси́, наслажде́ніє небе́снаго Ца́рствія, є́же угото́ва от ві́ри пою́щим: благослове́н Бог оте́ць на́ших.","Богородичен: Обновля́ються в Тебі́ єстества́ зако́ни: па́че єстества́ бо єстество́м Непостижи́маго, Ді́во, Бо́га Емману́їла пресла́вно, Чи́стая, родила́ єси́ в на́ше ві́рних обновле́ніє."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго і пла́мень в ро́су прело́жшаго Бо́га, по́йте діла́ я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Слеза́ми твої́ми, о́тче Варлаа́ме, умива́яся, житіє́ проше́л єси́, і ті́ми мно́жества де́монов потопи́л єси́, ві́рних же ми́слі возвесели́л єси́, пою́щих: вся діла́ Го́спода по́йте і превозносі́те Єго́ во ві́ки.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Уязви́лся єси́ боже́ственним жела́нієм, всеблаже́нне, ті́мже і непоро́чноє і пра́ведноє житіє́ проходя́, до́ндеже дости́гл єси́ ца́рськаго престо́ла, отону́дними світлостьми́ осія́я пою́щия: вся діла́ Го́спода по́йте і превозносі́те Єго́ во ві́ки.","К Сві́ту незаходи́мому, сла́вне, взя́лся єси́, наслажде́ніє же земни́х веще́й оплева́во ви́шняго ра́ди наслажде́нія, па́че воздержа́нію поревнова́л єси́ і страсте́й пла́мень потща́лся єси́ угаси́ти слеза́ми твої́х істо́чник, Варлаа́ме, вопія́: вся діла́ Го́спода по́йте і превозносі́те Єго́ во ві́ки.","Богородичен: Расп'я́тіє і погребе́ніє, І́же от Тебе́ небра́чно, Ді́во, проізи́де, претерпі́в нас ра́ди муче́ніє, Єго́же страсте́м ревну́я, преподо́бний Варлаа́м крестови́дно муче́нія поще́нієм Тому́, Чи́стая, послі́дова."]},{"h":"Пісня 9","ps":["Ірмос: Я́же пре́жде со́лнця Світи́льника Бо́га возсія́вшаго, пло́тськи к нам прише́дшаго, із боку́ Діви́чу неізрече́нно воплоти́вшая, Благослове́нная Всечи́стая, Тя, Богоро́дице, велича́єм.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","Пожи́в на землі́ равноа́нгельно, равноа́нгельну обрі́л єси́ сві́тлость, моли́ непреста́нно Ізба́вителя, Варлаа́ме, о творя́щих благоче́стно па́м'ять твою́, о преблаже́нне, мона́шествующих похвало́.","Приспів: Преподо́бне о́тче Варла́ме, моли́ Бо́га о нас.","У́зький і приско́рбний ше́ствовав путь, о́тче Варлаа́ме, і тіле́сні у́бо преста́вился єси́, ду́хом же жив, предстої́ши Бо́гу. Но я́ко імі́я дерзнове́ніє, Єму́же в житії́ рабо́тал єси́, моли́ спасти́ ду́ші на́ша.","Ісціле́ній яви́лся єси́ струя́ оби́льная, многом'яте́жнаго пла́мене у́гліє страсте́й угаси́л єси́. Ум бо твой неокра́ден, преподо́бне о́тче, соблю́л єси́ і, я́ко крі́пок, Варлаа́ме, побіжда́єши іскуси́теля.","Богородичен: Єди́на іму́щи дерзнове́ніє, Влади́чице, за весь мир Си́ну Твоєму́ моли́ся, не помина́я безчи́сленних собла́зн на́ших, і покри́й лю́ди, вопію́щия Ті умиле́нним гла́сом: спаси́, Чи́стая Богоро́дице, тебі́ досто́йно велича́ющия."]},{"h":"Світилен","ps":["Восто́ка восто́ков, разу́мнаго Со́лнця, Христа́, світоза́рная луча́ возсія́, і світи́льник многосві́тлий, пусти́нноє воспита́ніє і чистоти́ кра́сная оби́тель, Христо́ви добро́ти я́сно зря, Єго́же сія́ньми ум твой озари́л єси́. Ті́мже тя світи́льника стяжа́вше, о́тче наш Варлаа́ме, мо́лим тя в ми́рі сохране́нним би́ти па́м'ять твою́ почита́ющим.","Богородичен: Неізрече́ннаго чревоноше́нія била́ єси́, Всенепоро́чная Неві́ста, і я́ко су́щи честні́йший храм, Богоро́дице: Світ бо преві́чний в Тя всели́ся, і родила́ єси́ Бо́га Сло́ва. Пою́ще Твоє́ Рождество́, велича́єм досто́йно, Всенепоро́чная Отрокови́це."]}],"notes":[]},{"u":"Канон апостолу Варфоломію","e":"Canon to the Apostle Bartholomew","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Прові́дець всіх і Бог, ума́ твоєго́ богови́дно зря, ізбра́ і тя сочета́ ли́ку апо́стольську, Варфоломе́є всехва́льне, благода́тію просвіти́в се́рдце твоє́.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Доброді́телей на висоту́ возше́д, язи́ком огнедохнове́нним огневи́дно разділе́нієм обогати́лся єси́, я́ко Христо́в апо́стол, прише́ствієм Уті́шителя, пребога́те, нече́стія хвра́стіє пояда́я, і неразу́мія.","Богоно́сен угль воі́стину, Боже́ственнаго Ду́ха заре́ю разжже́н, показа́лся єси́, пре́лести сі́но попаля́я, Варфоломе́є прехва́льне, і просвіща́я ві́рою сердца́ пою́щих тя.","Богородичен: Чи́стая, рци, ка́ко доі́ши? Ка́ко же Ма́ти била́ єси́, ді́вственними печа́тьми сія́ющи? — Не пита́й бе́здни, неприча́стна єстество́м, іспита́яй єди́н всіх Бог і Госпо́дь, Єго́же і пло́тію роди́х."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня, я́ко крин, Го́споди, язи́чеськая неплодя́щая це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Я́ко дождь небе́сний, ізсо́хшую, прему́дре, вселе́нную всю тьмо́ю безбо́жия напої́л єси́, богови́дче досточу́дне.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Істо́чник ізи́де спаси́тельнаго пи́ва, Варфоломе́є всече́стне, і многосугу́б плод прине́сл єси́ язи́ком спасе́нія, досточу́дне.","Со́лію благода́ті і́дольськоє уста́вил єси́ гноє́ніє, всему́дре, сла́дким сло́вом ві́ри сердца́ услажда́я чту́щих тя.","Богородичен: Єди́ну Ді́ву Тя і Ма́тер чтим, я́ко спасе́нія Хода́таїцю би́вшую нам, Непоро́чная, і мир ізбавля́ющую моли́твами Твої́ми."]},{"h":"Сідален, глас 8","ps":["Мре́жею сло́ва возве́д із глубини́ неразу́мія, боголі́пно язи́ки приве́л єси́ ві́рою і, я́ко істо́чник сий вод духо́вних, вселе́нную всю напої́л єси́ благода́тію. Ті́мже і спа́сшіїся тобо́ю, богогла́се, я́ко дру́га тя бли́жняго Христо́ва ублажа́єм, Варфоломе́є, вопію́ще ті: моли́ Христа́ Бо́га согріше́ній оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́ста Творцю́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Препі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і бісо́м ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні а́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Упраздни́л єси́, кресто́м Госпо́днім огражда́єм, де́монськоє свирі́пство, Варфоломе́є преізря́дне, і сих душегуби́тельную пре́лесть отгна́л єси́ пропові́данієм.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Світ ми́ра, сла́ви боже́ственния сія́ніє Христо́с тя показа́, Варфоломе́є богоприя́тне: всю бо просвіти́л єси́ богоразу́мієм твар, всеблаже́нне.","Возмути́л єси́ язи́чеськая моря́, апо́столе, я́ко конь преізря́ден, колесни́ця Сло́ва бив, ві́рою же погаси́л єси́ го́ркаго безбо́жия конці́.","Богородичен: Ісціля́я Є́вино ве́тхоє преступле́ніє, в Тя, непоро́чную, Пречи́стая, всели́ся, всего́ м'я челові́ка обнови́ па́дшаго Пребоже́ственний."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо Влади́ко, к світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія, приведе́ніє і́мами.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Несозда́нну Сві́ту, нас ра́ди в зда́ніїх я́вльшемуся Христу́, перводі́льно бесі́довал єси́, к Нему́ прише́д, апо́столе, і боже́ственними заря́ми от Него́ просвіща́єм.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Я́ко роса́ Бо́жия, челові́ком ісціле́ніє подаю́щи, в ми́рі бил єси́, о Варфоломе́є преблаже́нне, і зе́млю нече́стія проро́чеськи опрове́ргл єси́.","К пе́рвому Сві́ту присту́пль, бил єси́ світ втори́й: я́же отту́ду сія́нії і світоли́тії озаря́єм, я́ко самови́дець Сло́ва, Варфоломе́є всему́дре.","Богородичен: Глаго́ли Твоя́ по́мняще, Тя ни́ні блажи́м: Тобо́ю бо, Непоро́чная, блаже́нство обріто́хом і жи́знію честно́ю і́стинною обогати́хомся."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Чуде́с благода́ть приє́м і ісціле́ній обога́щся ді́телію, Варфоломе́є всему́дре, язи́к стада́ улови́л єси́.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","О́гненний твой язи́к, пресла́вне, вся́ку пре́лесть, я́ко сі́но, попали́, ві́рних же просвіти́ сердца́ боже́ственним пропові́данієм.","Істо́чника прему́дрости учи́теля імі́я, пресла́вне, Сло́ва Безнача́льнаго, мирську́ю обуї́л єси́, богопропові́дниче, му́дрость благода́тію.","Богородичен: Па́че єстества́, Ді́во, родила́ єси́ і ві́чнуєши Ді́вою, явля́ющи і́стиннаго Божества́, Си́на і Бо́га Твоєго́, о́брази."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ вели́коє со́лнце вселе́нній уче́ній сія́ньми і чуде́с стра́шних, світоводя́ почита́ющия тя, Варфоломе́є, Госпо́день апо́столе."]},{"h":"Ікос","ps":["Я́ко не́бо, сла́ву Бо́жию віща́я, ви́дін бил єси́ Ду́хом Святи́м, апо́столе богови́дче, і, я́ко со́лнце сві́тло, яви́лся єси́ ми́ру, преле́стноє помраче́ніє разгоня́я Боже́ственною благода́тію. Тім молю́ ті ся і мил ся ді́ю: боже́ственними твої́ми луча́ми, душі́ моєя́ осліпле́нния, всебога́те, просвіти́ зі́ниці і сло́во тя пі́ти даждь во отверзе́ніє усто́м мої́м в твоє́й днесь па́м'яті, в ню́же всяк ві́рний, веселя́ся, хва́лить тя, Варфоломе́є, Госпо́день апо́столе."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий Благослове́н і Препросла́влен.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Вели́коє та́їнство, Варфоломе́є, Боже́ственнаго воплоще́нія ми́ру яви́л єси́, є́же всім невмісти́моє і непостижи́моє, єди́нім же вмісти́мо ві́рним, несказа́ємо і ві́руємо.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Я́ко ка́мень, пресвяти́й Варфоломе́є, чи́сті валя́яся, пре́лести утвержде́ніє крі́пко опрове́ргл єси́, Це́ркві же необори́моє основа́ніє я́влься, сохраня́єши сію́ непоколеби́му.","Боже́ственноє подо́біє, Варфоломе́є, доброді́телей ша́ром, преблаже́нне, написа́л єси́, отсю́ду апо́стол боже́ствен бив, всім пропові́дал єси́ Христо́во прише́ствіє многопі́тоє.","Богородичен: Грозд созрі́вший, Єго́же невозді́ланно, Чи́стая, возрасти́ла єси́, на дре́ві я́ко узрі́вши пові́шена, вопія́ла єси́: Ча́до сла́дкоє, мсто іска́пи, і́мже страсте́й пія́нство оти́меться."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Ве́ліє і ма́ло, мно́го же і ума́лено, Спа́сово Єва́нгеліє прему́дро научи́л єси́. Ве́лія і пресла́вная сложе́нними глаго́ли всім назна́менал єси́, Варфоломе́є богому́дре.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Я́коже ріка́, от Сіо́на ісходя́, церко́вния со́нми напоя́єши, пребога́те, і пото́к боже́ственния пи́щі іспусти́л єси́ явле́ннійше, зови́й: благослові́те, вся діла́ Госпо́дня, Го́спода.","Боже́ственних даро́в я́ві світлі́йшими і вели́кими я́ко апо́стол боже́ственне украси́лся єси́. Превосхо́дить сан благосла́вія всего́, блаже́нне, су́щеє во челові́ціх зри́моє благода́тію.","Богородичен: Ум безстра́стен в ложесна́х Твої́х єдини́ться челові́чу уму́, Всечи́стая, пло́ті же дебельство́м подлі́тен бив, віко́в преви́шшій. Тім Тя, Богоро́дице, ві́рою і любо́вію сла́вим."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Сло́ва бив самови́дець і служи́тель, учени́к же і пропові́дник богови́ден, іді́же ни́ні єсть Сло́во, ти жи́ти воі́стину сподо́бился єси́, я́коже Сам обіща́ нело́жно Преблаги́й.","Приспів: Святи́й апо́столе Вафоломе́є, моли́ Бо́га о нас.","Я́ко ни́ні предстоя́ престо́лу Влади́ки твоєго́ і отону́дними заря́ми осія́єм, о Варфоломе́є богому́дре, півці́ твоя́ назира́я, страсте́й ізбавля́єши і разли́чних обстоя́ній.","Син ві́ри ра́ди сподо́блься би́ти Бо́гу, оте́чеських наслі́дник сокро́вищ бил єси́. О, великода́рния дла́ни! О, дарова́нія, ни́ні превосходя́щаго, Христа́, просла́вльшаго тя, богови́дче всеблаже́нне!","Богородичен: Разумі́вше іздале́ча прозорли́вима очи́ма, проро́ци Тя всі провозгласи́ша, хотя́щую Ма́тер би́ти Вседі́теля і всіх Влади́ки. Тім Тя, Всепі́тую Богоро́дицю, возвіща́єм."]},{"h":"Світилен","ps":["Апо́столи Христо́ви прийді́те, лю́діє, воспої́м, боже́ственнаго Варфоломе́я і Варна́ву му́драго, пропові́дники ві́ри, я́ко моля́щіяся Христу́ о душа́х на́ших.","Богородичен: Чи́стая Влади́чице Свята́я і єди́на Муженеїску́сная, спасе́ніє і упова́ніє Ти, моли́ із Тебе́ рожде́ннаго Ізба́вителя на́шего спасти́ мир от ле́сти, бід і скорбе́й."]}],"notes":[]},{"u":"Канон апостолу Варнаві (Йосії)","e":"Canon to the Apostle Barnabas (Joses)","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть, препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Я́ко муж сий благ і утіше́нія син я́влься, душі́ моєя́ озлобле́ніє і гріха́ душегу́бную печа́ль отжени́, я́ко да, весе́лія іспо́лнен бив, воспою́ тя.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Одержи́м, блаже́нне, чи́стим сія́нієм, прозя́бшаго от колі́на Іу́дова, пребога́те, Христа́ Всецаря́, от леви́тська сро́дства прише́дша свяще́нна, зако́на же преложе́ніє пропові́дал єси́.","Сві́тлая твоя́, прему́дре, жизнь, пе́рвия бла́гості і єсте́ственнаго существа́ показа́ бо́га тя втора́го, є́же отту́ду ублажа́єма благода́тьми, сла́вне Варна́во, порожде́ніє Боже́ственнаго утіше́нія.","Богородичен: Отрокови́ць Боже́ственний лик боже́ственно в жена́х Тя до́брую воспіва́єть, Богоро́дице Влади́чице, добро́тами укра́шену Божества́: добротвори́тельноє бо Сло́во па́че сло́ва родила́ єси́."]},{"h":"Пісня 3","ps":["Ірмос: Процвіла́ єсть пусти́ня, я́ко крин, Го́споди, язи́чеськая неплодя́щая Це́рков, прише́ствієм Твої́м, в не́йже утверди́ся моє́ се́рдце.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","О́блак во́льний, нам дождь нося́щий от істо́чника благода́ті, ви́дін бил єси́, Варна́во сла́вне, і пи́щний пото́к напая́ющий.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Разли́чними одарова́на сія́нії ви́дящи Всеси́льнаго Ду́ха власть, та́йнам Христо́вим служи́теля, отлучи́ тя, прехва́льне.","Просвіща́ємі благода́тію Креста́ Твоєго́, Влади́ко, благосла́внії апо́столи тебі́ язи́ки ві́рою приведо́ша, Варна́ва і Па́вел Богому́дрії.","Богородичен: Яви́лася єси́ чистото́ю, я́ко крин, Влади́чице, посреді́ те́рнія возсія́вши заря́ми ді́вства Твоєго́, Богоро́дице Всечи́стая."]},{"h":"Кондак, глас 3","ps":["Госпо́день бил єси́ всеї́стинний служи́тель, апо́столов же яви́лся єси́ седьми́десятих пе́рвий, озари́л єси́ і с Па́влом про́повідь твою́, всім возвіща́яй Христа́ Спа́са, сего́ ра́ди піснопі́нії Боже́ственную па́м'ять твою́, Варна́во, соверша́єм."]},{"h":"Ікос","ps":["Син Бо́жий, соприсносу́щний Ду́ху, благоволе́нієм на землі́ плоть приє́м, я́ко Челові́к, і стра́стію честно́ю безстра́стіє дав, тя полага́єть, блаже́нне, апо́стола і виті́я ві́ри, му́дра в сло́ві і досточу́дна, пропові́дника че́стна, язи́ков учи́теля, Варна́во блаже́нне, і Тро́йці і́стинна покло́нника. Ті́мже возсія́ ві́рним честна́я денни́ця сві́тлая, озаря́ющая твоя́ Боже́ственная па́м'ять, ю́же досто́йно соверша́єм."]},{"h":"Сідален, глас 8","ps":["Слове́сен показа́лся єси́, я́ко Небе́сную пові́дуя сла́ву Бо́жию чуде́с сві́тлостію і си́ли луча́ми, неразу́мія нощ отгоня́ благода́тію, богоразу́мія же лучи́ облиста́я конце́м. Ті́мже світоно́сную і святу́ю твою́ па́м'ять сла́вим днесь, ві́рнії, і вопіє́м ті: Варна́во всехва́льне, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́ста Творцю́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Препі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і бісо́м ігра́лище в ра́зумі би́вша, потщи́ся от тіх злоді́йства м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні А́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Послі́дуя повелі́нієм Влади́ки, апо́столе Варна́во прехва́льне, ни́щим разда́л єси́ все твоє́ імі́ніє, і Христо́в пропові́дник бив велегла́сен.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Дости́гл єси́ доброді́телей сві́тлость коне́чную і, Па́вла обрі́т, Богогла́снаго апо́стола, с ни́мже всім возвісти́л єси́ та́їнства глубину́ неізрече́нную.","Я́ко со́лнце, претека́я ми́ра конці́, Варна́во всече́стне, зарелу́чними сія́нії, Па́влу послі́дуя, просвіща́єши сло́вом благода́ті.","Соприча́стник страсте́й Спа́са бив, Варна́во прехва́льне, в небе́сних се́ліх с Ним прославля́єшися, па́че ума́ весе́лія насища́яся.","Богородичен: Є́ви прама́тере кля́тва упраздни́ся Тобо́ю, Всенепоро́чная: воплоще́ннаго бо Сло́ва родила́ єси́ Присносу́щнаго, благослове́ньми мир вінча́вшаго."]},{"h":"Пісня 5","ps":["Ірмос: Хода́тай Бо́гу і челові́ком бил єси́, Христе́ Бо́же: Тобо́ю бо Влади́ко, к світонача́льнику Отцю́ Твоєму́, от но́щі неві́дінія, приведе́ніє і́мами.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Зако́на сінь преше́д і благода́тію сія́я, язи́ком ісполне́ніє благовіству́я, просвіти́л єси́, Богому́дрий Варна́во, Христо́вим пропові́данієм.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Крі́постію держа́вною Свята́го Ду́ха, апо́столе, я́ві обложе́н, лука́вствія ду́хи низложи́в, от тіх злоді́йства мир ізба́вил єси́.","Вопію́щаго глас в пусти́х язи́ціх бил єси́, му́дре, Боже́ственнаго воплоще́нія непостижи́моє та́їнство возвіща́я всім, Варна́во пребога́те.","Богородичен: Се во утро́бі, Богоро́дице Пречи́стая, Христа́ Бо́га па́че сло́ва імі́ла єси́, я́коже Іса́їя предрече́, ви́ше єстества́ же Сего́, Богороди́тельнице, родила́ єси́."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же м'я возведи́.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Возсія́в ми́ру, Христе́ Бо́же, Пра́вди Со́лнце, Влади́ко, я́коже лучи́ сія́ющия, Варна́ву і Па́вла возблиста́л єси́.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Кореносі́чна сіки́ра бил єси́, олядені́вшую пре́лесть сіку́щи па́че сло́ва чудеси́, Богоглаго́ливе Варна́во чу́дне.","Законополо́жник показа́лся єси́ благода́ті, я́ко ве́тхаго заві́та о́брази ко і́стинному явле́нію прелага́я, Варна́во Богоприя́тне.","Богородичен: Небеса́ Простри́й во́лею, не́бо земно́є друго́є показа́ Тя, Богома́ти Пречи́стая, і, із Тебе́ возсія́в, яви́ся."]},{"h":"Пісня 7","ps":["Ірмос: Богопроти́вноє велі́ніє беззако́ннующаго мучи́теля висо́к пла́мень вознесло́ єсть: Христо́с же простре́ Богочести́вим отроко́м ро́су духо́вную, Сий благослове́н і препросла́влен.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Свя́то Свята́го, во святи́х почива́ющаго, Варна́во, пропові́дал єси́ Си́на, собезнача́льна Отцю́ і сопресто́льна, Челові́ка би́вша, нам спасе́ніє содіва́юща.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Лучи́, блиста́ющия Боже́ственноє сія́ніє, Варна́ва всечестни́й і Па́вел Богоприя́тний, я́ко світ, ісхо́дять, просвіща́ющия сло́вом благода́ті язи́к всенаслі́діє, христопропові́дници.","Ра́дується днесь воспита́вий тя, Варна́во, цвіту́щаго сло́во благода́тноє, Христо́ві тя прозя́бши, Богоблаже́нне. Єго́же ізміни́в, ни́нішняго пліне́нія ізба́ви моли́твами твої́ми.","Богородичен: Направля́ющи, Всечи́стая, мою́ жизнь, ко Твоєму́ благоути́шному приста́нищу наста́ви, Бо́га ро́ждшая, благи́х істо́чника, всім подаю́ща ві́рним незави́стную бла́гость."]},{"h":"Пісня 8","ps":["Ірмос: Пещ іногда́ о́гненная во Вавило́ні ді́йства разділя́ше, Бо́жиїм велі́нієм халде́ї опаля́ющая, ві́рния же ороша́ющая, пою́щия: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Мо́ре язи́чеськоє возмути́ти Твоя́ ко́ни, я́ко Благоді́тель, наве́л єси́ — Варна́ву сла́внаго і Па́вла чу́днаго, пре́лесть многобо́жную уче́ньми, Живода́вче, благоче́стія отгоня́щия.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Положи́, я́ко Бог, Уті́шителю Ду́ше вседі́тельний, в Це́ркві Твоє́й світи́ла сія́ющая, Твою́ си́лу пропові́дающая, Си́ну же і Роди́телю зову́щая: благослові́те, вся діла́ Госпо́дня, Го́спода.","Облиста́л єси́ сві́тло, я́ко со́лнце, в ми́рі, ми́сленному бесі́довав я́ві Со́лнцю, Богоприя́тне: разже́гся бо сія́нієм, світ втори́й бил єси́, всім явля́я та́їнства си́лу.","Зе́млю всю уче́ньми просвіти́в, є́же па́че ума́ блаже́нство досто́йно улучи́л єси́, в Небе́сних се́ліх, Варна́во всече́стне, віне́ць благолі́пія от Влади́ки приє́м.","Богородичен: Да кля́тву пе́рвую погуби́ши і сме́рті осужде́ніє дре́внія прама́тере, от Ді́ви Богома́тере Сло́во Бо́жиє роди́ся, всім дарова́ безсме́ртіє неги́блющеє."]},{"h":"Пісня 9","ps":["Ірмос: Безнача́льна Роди́теля Син, Бог і Госпо́дь, вопло́щся от Ді́ви, нам яви́ся, омраче́нная просвіти́ти, собра́ти расточе́нная, тім Всепі́тую Богоро́дицю, велича́єм.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Світ би́вше доброді́телію, апо́столи, і Сві́ту вели́кому ни́ні предстоя́ще, ми́ру мир пода́ти і на́шу спасти́ Це́рков, ю́же соста́висте, Влади́ку умолі́те.","Приспів: Святи́й апо́столе Варна́во, моли́ Бо́га о нас.","Виті́йськую лю́тость прему́дрости твоєя́ пла́менем, Богоявле́нне Варна́во, я́ві погаси́л єси́, сія́ній Боже́ственних, я́ко істо́чник, внутр імі́я. Ті́мже всесвяще́нний пра́здник твой почита́єм.","Ві́рою па́м'ять твою́ соверша́юще ни́ні, апо́столе, моли́твенника ко Влади́ці тя предлага́єм, разріше́нія прося́ще согріше́ній твої́м прия́ти хода́тайством, Варна́во всече́стне, Богопропові́дниче свяще́нне.","Богородичен: Я́ко у́тро обрі́теся у́треннєє, в жите́йстей но́щі ді́вства заря́ми сія́ющи, восто́к Со́лнця разу́мнаго пра́вди нам я́вльши, Богома́ти Всечи́стая."]}],"notes":[]}];
export default D;
